module sequence_detector (
    input clk,
    input reset_n,
    input data_in,
    output sequence_detected
);

    parameter IDLE = 3'b000;
    parameter S1 = 3'b001;
    parameter S2 = 3'b010;
    parameter S3 = 3'b011;
    parameter S4 = 3'b100;

    reg [2:0] state, next_state;


    always @ (posedge clk or negedge reset_n) begin
        if (!reset_n)
            state <= IDLE;
        else
            state <= next_state;
    end


    always @ (*) begin
        case (state)
            IDLE: 
                if (data_in)
                    next_state = S1;
                else
                    next_state = IDLE;
            S1:
                if (data_in)
                    next_state = S1;
                else
                    next_state = S2;
            S2:
                if (data_in)
                    next_state = S1;
                else
                    next_state = S3;
            S3:
                if (data_in)
                    next_state = S4;
                else
                    next_state = IDLE;
            S4:
                next_state = IDLE;
            default:
                next_state = IDLE;
        endcase
    end


    assign sequence_detected = (state == S4);

endmodule

