module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wclk,
    input wrstn,
    input rclk,
    input rrstn,
    input winc,
    input rinc,
    input [WIDTH-1:0] wdata,
    output wfull,
    output rempty,
    output [WIDTH-1:0] rdata
);

    localparam ADDR_BITS = $clog2(DEPTH);
    localparam PTR_BITS = ADDR_BITS + 1;


    wire [$clog2(DEPTH)-1:0] waddr_bin, raddr_bin;
    wire [PTR_BITS-1:0] wptr_bin, rptr_bin;
    wire [PTR_BITS-1:0] wptr_gray, rptr_gray;
    reg [PTR_BITS-1:0] wptr_bin_reg, rptr_bin_reg;


    reg [PTR_BITS-1:0] rptr_gray_sync1, rptr_gray_sync2;
    reg [PTR_BITS-1:0] wptr_gray_sync1, wptr_gray_sync2;


    function [PTR_BITS-1:0] bin2gray(input [PTR_BITS-1:0] bin);
        bin2gray = (bin >> 1) ^ bin;
    endfunction


    assign waddr_bin = wptr_bin_reg[ADDR_BITS-1:0];
    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            wptr_bin_reg <= 0;
        end else if (winc && !wfull) begin
            wptr_bin_reg <= wptr_bin_reg + 1;
        end
    end
    assign wptr_gray = bin2gray(wptr_bin_reg);


    assign raddr_bin = rptr_bin_reg[ADDR_BITS-1:0];
    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            rptr_bin_reg <= 0;
        end else if (rinc && !rempty) begin
            rptr_bin_reg <= rptr_bin_reg + 1;
        end
    end
    assign rptr_gray = bin2gray(rptr_bin_reg);


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            {rptr_gray_sync1, rptr_gray_sync2} <= 0;
        end else begin
            rptr_gray_sync1 <= rptr_gray;
            rptr_gray_sync2 <= rptr_gray_sync1;
        end
    end


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            {wptr_gray_sync1, wptr_gray_sync2} <= 0;
        end else begin
            wptr_gray_sync1 <= wptr_gray;
            wptr_gray_sync2 <= wptr_gray_sync1;
        end
    end


    assign rempty = (rptr_gray == rptr_gray_sync2);


    wire msb_diff = (wptr_gray[PTR_BITS-1] != rptr_gray_sync2[PTR_BITS-1]);
    wire msb2_diff = (wptr_gray[PTR_BITS-2] != rptr_gray_sync2[PTR_BITS-2]);
    wire lower_same = (wptr_gray[PTR_BITS-3:0] == rptr_gray_sync2[PTR_BITS-3:0]);
    assign wfull = msb_diff && msb2_diff && lower_same;


    dual_port_RAM #(.WIDTH(WIDTH), .DEPTH(DEPTH)) ram (
        .wclk(wclk),
        .wenc(winc && !wfull),
        .waddr(waddr_bin),
        .wdata(wdata),
        .rclk(rclk),
        .renc(rinc && !rempty),
        .raddr(raddr_bin),
        .rdata(rdata)
    );

endmodule


module dual_port_RAM #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
)(
    input wclk,
    input wenc,
    input [$clog2(DEPTH)-1:0] waddr,
    input [WIDTH-1:0] wdata,
    input rclk,
    input renc,
    input [$clog2(DEPTH)-1:0] raddr,
    output reg [WIDTH-1:0] rdata
);
    reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];


    always @(posedge wclk) begin
        if (wenc) begin
            RAM_MEM[waddr] <= wdata;
        end
    end


    always @(posedge rclk) begin
        if (renc) begin
            rdata <= RAM_MEM[raddr];
        end
    end
endmodule

