module parallel2serial (
    input clk,
    input rst_n,
    input [3:0] d,
    output reg valid_out,
    output reg dout
);

reg [3:0] data_reg;
reg [1:0] cnt;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cnt <= 2'd0;
        data_reg <= 4'd0;
        valid_out <= 1'd0;
    end else begin
        if (cnt == 2'd3) begin
            data_reg <= d;
            cnt <= 2'd0;
            valid_out <= 1'd1;
        end else begin
            data_reg <= {data_reg[2:0], data_reg[3]};
            cnt <= cnt + 1;
            valid_out <= 1'd0;
        end
        dout <= data_reg[3];
    end
