module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

    parameter S0 = 2'd0, S1 = 2'd1, S2 = 2'd2;
    reg [1:0] state;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            state <= S0;
            data_out <= 0;
        end
        else begin
            case (state)
                S0: begin
                    data_out <= 0;
                    if (data_in)
                        state <= S1;
                    else
                        state <= S0;
                end
                S1: begin
                    data_out <= 0;
                    if (!data_in)
                        state <= S2;
                    else
                        state <= S1;
                end
                S2: begin
                    data_out <= 1;
                    state <= S0;
                end
                default: begin
                    state <= S0;
                    data_out <= 0;
                end
            endcase
        end
    end

endmodule

