module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);


    localparam [1:0] 
        idle = 0,
        s1_red = 1,
        s2_yellow = 2,
        s3_green = 3;


    reg [1:0] state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;


    assign red = p_red;
    assign yellow = p_yellow;
    assign green = p_green;
    assign clock = cnt;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
        end else begin
            case (state)
                idle: begin
                    state <= s1_red;
                    p_red <= 1;
                    p_yellow <= 0;
                    p_green <= 0;
                end
                s1_red: begin
                    if (cnt == 0) begin
                        state <= s3_green;
                        p_green <= 1;
                        p_red <= 0;
                        p_yellow <= 0;
                    end else begin
                        p_red <= 1;
                        p_yellow <= 0;
                        p_green <= 0;
                    end
                end
                s3_green: begin
                    if (cnt == 0) begin
                        state <= s2_yellow;
                        p_yellow <= 1;
                        p_green <= 0;
                        p_red <= 0;
                    end else begin
                        p_red <= 0;
                        p_yellow <= 0;
                        p_green <= 1;
