                        p_red <= 0;
                        p_yellow <= 1;
                        p_green <= 0;
                    end
                end
                default: begin
                    state <= idle;
                    p_red <= 0;
                    p_yellow <= 0;
                    p_green <= 0;
                end
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 10;
        end else begin

            if (pass_request && green) begin
                if (cnt > 10) 
                    cnt <= 10;
            end

            else if (!green && p_green) 
                cnt <= 60;

            else if (!yellow && p_yellow) 
                cnt <= 10;

            else if (!red && p_red) 
                cnt <= 5;

            else 
                cnt <= cnt - 1;
        end
    end

