module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [7:0] saved_dividend, saved_divisor;
    reg [7:0] abs_dividend, abs_divisor;
    reg [7:0] neg_divisor;
    reg [15:0] SR;
    reg [3:0] cnt;
    reg start_cnt;
    reg [7:0] quotient;
    reg [7:0] remainder;
    reg [7:0] temp_divisor;
    reg temp_sign;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            cnt <= 0;
            start_cnt <= 0;
            quotient <= 0;
            remainder <= 0;
            SR <= 0;
            temp_sign <= 0;
            saved_dividend <= 0;
            saved_divisor <= 0;
            abs_dividend <= 0;
            abs_divisor <= 0;
            neg_divisor <= 0;
            result <= 0;
        end else begin
            if (opn_valid && !res_valid) begin

                saved_dividend <= dividend;
                saved_divisor <= divisor;
                temp_sign <= sign;

                if (sign) begin
                    abs_dividend <= dividend[7] ? -dividend : dividend;
                    abs_divisor <= divisor[7] ? -divisor : divisor;
                    temp_divisor <= divisor[7] ? -divisor : divisor;
                end else begin
                    abs_dividend <= dividend;
                    abs_divisor <= divisor;
                    temp_divisor <= divisor;
                end


                SR <= {abs_dividend, 8'b0} << 1;
                neg_divisor <= ~abs_divisor + 1;
                quotient <= 0;
                cnt <= 1;
                start_cnt <= 1;
                res_valid <= 0;
            end else if (start_cnt && cnt <= 8) begin

                if (cnt <= 8) begin

                    {remainder, quotient} = SR;
                    remainder = remainder - neg_divisor;
                    if (remainder[8] == 0) begin 
                        quotient = (quotient << 1) | 1;
                        SR = {remainder[7:0], quotient[7:1]};
                    end else begin
                        quotient = quotient << 1;
                        SR = {remainder[7:0], quotient[7:1]};
                    end
                    cnt <= cnt + 1;
                end

                if (cnt == 8) begin
                    start_cnt <= 0;
                    cnt <= 0;
                end
            end

            if (cnt == 8 && start_cnt) begin

                if (temp_sign) begin
                    if (saved_dividend[7] ^ saved_divisor[7]) begin
                        quotient = -quotient;
                    end
                    if (saved_dividend[7]) begin
                        remainder = -remainder;
                    end
                end


                result <= {remainder, quotient};
                res_valid <= 1;
            end else begin
                res_valid <= 0;
            end
        end
    end

endmodule

