module fixed_point_adder #(
    parameter N = 16,
    parameter Q = 8
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

    reg [N-1:0] res;


    reg sign_a, sign_b;
    reg [N-1:0] abs_a, abs_b;


    reg [N-1:0] res_temp;
    reg sign_res_temp;

    always @* begin

        sign_a = a[N-1];
        sign_b = b[N-1];


        abs_a = sign_a ? (~a + 1) : a;
        abs_b = sign_b ? (~b + 1) : b;


        res_temp = 0;
        sign_res_temp = 0;


        if (sign_a == sign_b) begin
            res_temp = a + b;
            sign_res_temp = sign_a;
        end else begin

            if (abs_a > abs_b) begin
                res_temp = a - b;
                sign_res_temp = sign_a;
            end else if (abs_b > abs_a) begin
                res_temp = b - a;
                sign_res_temp = sign_b;
            end else begin

                res_temp = 0;
                sign_res_temp = 0;
            end
        end


        if (sign_res_temp)
            res = ~res_temp + 1;
        else
            res = res_temp;
    end

    assign c = res;

endmodule

