module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [9:0] a_exponent, b_exponent, z_exponent;
    reg [23:0] a_mantissa, b_mantissa;
    reg [49:0] product;
    reg guard, round, sticky;
    reg is_nan, is_inf_a, is_inf_b, is_zero_a, is_zero_b;


    wire a_exp_zero = (a[30:23] == 0);
    wire b_exp_zero = (b[30:23] == 0);
    wire a_mant_zero = (a[22:0] == 0);
    wire b_mant_zero = (b[22:0] == 0);

    assign is_nan = ((a_exp_zero && !a_mant_zero) || (b_exp_zero && !b_mant_zero));
    assign is_inf_a = a_exp_zero && a_mant_zero;
    assign is_inf_b = b_exp_zero && b_mant_zero;
    assign is_zero_a = a_exp_zero && a_mant_zero;
    assign is_zero_b = b_exp_zero && b_mant_zero;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'h0;
        end else begin
            case (counter)
                0: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= {1'b0, a[30:23]};
                    b_exponent <= {1'b0, b[30:23]};
                    a_mantissa <= a_exp_zero ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                    b_mantissa <= b_exp_zero ? {1'b0, b[22:0]} : {1'b1, b[22:0]};


                    if (is_nan) begin
                        z <= {1'b0, 8'hff, 23'h1};

                        counter <= 0;
                    end else if ((is_inf_a && is_zero_b) || (is_zero_a && is_inf_b)) begin
                        z <= {1'b0, 8'hff, 23'h1};

                        counter <= 0;
                    end else if (is_inf_a || is_inf_b) begin
                        z_sign <= a_sign ^ b_sign;
                        z_exponent <= 9'h1fe;

                        z <= {z_sign, 8'hff, 23'h0};

                        counter <= 0;
                    end else if (is_zero_a || is_zero_b) begin
                        z <= 32'h0;

                        counter <= 0;
                    end else begin
                        counter <= 1;
                    end
                end

                1: begin

                    product <= a_mantissa * b_mantissa;
                    z_exponent <= a_exponent + b_exponent - 10'd127;


                    if (product[49]) begin
                        product <= product >> 1;
                        z_exponent <= z_exponent + 1;
                    end
                    guard <= product[0];
                    round <= product[1];
                    sticky <= |product[49:2];

                    counter <= 2;
                end

                2: begin

                    if (sticky && round) begin
                        product[22:0] <= product[22:0] + 1;
                        if (product[23]) begin
                            z_exponent <= z_exponent + 1;
                        end
                    end


                    if (z_exponent >= 9'h1fe) begin
                        z <= {z_sign, 8'hff, 23'h0};

                    end else if (z_exponent <= 0) begin
                        z <= {z_sign, 31'h0};

                    end else begin
                        z <= {z_sign, z_exponent[7:0], product[22:0]};
                    end

                    counter <= 0;
                end

                default: counter <= 0;
            endcase
        end
    end

endmodule

