    .WIDTH(WIDTH),
    .DEPTH(DEPTH)
) ram (
    .wclk(wclk),
    .wenc(wen),
    .waddr(wptr[ADDR_WIDTH-1:0]),
    .wdata(wdata),
    .rclk(rclk),
    .renc(ren),
    .raddr(rptr[ADDR_WIDTH-1:0]),
    .rdata(rdata)
);


assign wptr_gray = wptr ^ (wptr >> 1);
assign rptr_gray = rptr ^ (rptr >> 1);


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        rptr_gray_sync_wr0 <= 0;
        rptr_gray_sync_wr <= 0;
    end else begin
        rptr_gray_sync_wr0 <= rptr_gray;
        rptr_gray_sync_wr <= rptr_gray_sync_wr0;
    end
end


function [PTR_WIDTH-1:0] gray2bin;
    input [PTR_WIDTH-1:0] gray;
    integer i;
    begin
        gray2bin[PTR_WIDTH-1] = gray[PTR_WIDTH-1];
        for (i = PTR_WIDTH-2;
 i >=0;
 i = i -1)
            gray2bin[i] = gray2bin[i+1] ^ gray[i];
    end
endfunction

wire [PTR_WIDTH-1:0] rptr_sync_w_bin = gray2bin(rptr_gray_sync_wr);
wire [PTR_WIDTH:0] wptr_diff = wptr - rptr_sync_w_bin;


assign wfull = (wptr_diff >= DEPTH);


always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        wptr_gray_sync_rd0 <= 0;
        wptr_gray_sync_rd <= 0;
    end else begin
        wptr_gray_sync_rd0 <= wptr_gray;
        wptr_gray_sync_rd <= wptr_gray_sync_rd0;
    end
end


wire [PTR_WIDTH-1:0] wptr_sync_r_bin = gray2bin(wptr_gray_sync_rd);


assign rempty = (rptr == wptr_sync_r_bin);


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        wptr <= 0;
    end else if (wen) begin
        wptr <= wptr_bin_next;
    end
end


always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        rptr <= 0;
    end else if (ren) begin
        rptr <= rptr_bin_next;
    end
end

