module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);

    parameter idle = 0, s1_red = 1, s2_yellow = 2, s3_green = 3;

    reg [1:0] state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;

    assign red = p_red;
    assign yellow = p_yellow;
    assign green = p_green;
    assign clock = cnt;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end else begin
            case (state)
                idle: state <= s1_red;
                s1_red: if (cnt == 0) state <= s3_green;
                s3_green: if (cnt == 0) state <= s2_yellow;
                s2_yellow: if (cnt == 0) state <= s1_red;
                default: state <= idle;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 10;
        end else begin
            if (pass_request && green) begin
                if (cnt > 10) cnt <= 10;
            end else if (!green && p_green) 
                cnt <= 60;
            else if (!yellow && p_yellow) 
                cnt <= 5;
            else if (!red && p_red) 
                cnt <= 10;
            else
                cnt <= cnt - 1;
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            {p_red, p_yellow, p_green} <= 3'b000;
        end else begin
            case (state)
                idle: {p_red, p_yellow, p_green} <= 3'b100;
                s1_red: {p_red, p_yellow, p_green} <= 3'b100;
                s3_green: {p_red, p_yellow, p_green} <= 3'b001;
                s2_yellow: {p_red, p_yellow, p_green} <= 3'b010;
                default: {p_red, p_yellow, p_green} <= 3'b000;
            endcase
        end
    end

endmodule

