module edge_detect (
    input clk,
    input rst_n,
    input a,
    output rise,
    output down
);

    reg a_prev;
    reg rise_reg, down_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            a_prev <= 1'b0;
            rise_reg <= 1'b0;
            down_reg <= 1'b0;
        end else begin
            a_prev <= a;
            if (rise_reg || down_reg) begin
                if (a_prev != a) begin
                    rise_reg <= 1'b0;
                    down_reg <= 1'b0;
                end
            end else begin
                if (a_prev == 1'b0 && a == 1'b1) begin
                    rise_reg <= 1'b1;
                end else if (a_prev == 1'b1 && a == 1'b0) begin
                    down_reg <= 1'b1;
                end
            end
        end
    end

    assign rise = rise_reg;
    assign down = down_reg;

endmodule

