    always @(posedge clk_a or negedge arstn) begin
        if (!arstn)
            data_reg <= 4'b0;
        else
            data_reg <= data_in;
    end


    always @(posedge clk_a or negedge arstn) begin
        if (!arstn)
            en_data_reg <= 1'b0;
        else
            en_data_reg <= data_en;
    end


    always @(posedge clk_b or negedge brstn) begin
        if (!brstn) begin
            en_clap_one <= 1'b0;
            en_clap_two <= 1'b0;
        end else begin
            en_clap_one <= en_data_reg;
            en_clap_two <= en_clap_one;
        end
    end


    always @(posedge clk_b or negedge brstn) begin
        if (!brstn)
            dataout_reg <= 4'b0;
        else if (en_clap_two)
            dataout_reg <= data_reg;

    end

    assign dataout = dataout_reg;

