module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output reg carry,
    output reg negative,
    output reg overflow,
    output reg flag
);


    parameter ADD = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND = 6'b100100;
    parameter OR = 6'b100101;
    parameter XOR = 6'b100110;
    parameter NOR = 6'b100111;
    parameter SLT = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL = 6'b000000;
    parameter SRL = 6'b000010;
    parameter SRA = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI = 6'b001111;

    reg [31:0] res;
    reg [32:0] sum, diff;

    assign zero = (r == 0);

    always @* begin
        r = 32'bz;
        carry = 0;
        negative = 0;
        overflow = 0;
        flag = 1'bz;
        res = 0;

        case (aluc)
            ADD: begin
                sum = {1'b0, a} + {1'b0, b};
                res = sum[31:0];
                carry = sum[32];
                overflow = (a[31] == b[31]) && (res[31] != a[31]);
                negative = res[31];
            end

            ADDU: begin
                res = a + b;
                carry = 0;
                overflow = 0;
                negative = res[31];
            end

            SUB: begin
                diff = {1'b0, a} - {1'b0, b};
                res = diff[31:0];
                carry = ~diff[32];
                overflow = (a[31] != b[31]) && (res[31] != a[31]);
                negative = res[31];
            end

            SUBU: begin
                res = a - b;
                carry = (a >= b) ? 1 : 0;
                overflow = 0;
                negative = res[31];
            end

            AND: begin
                res = a & b;
                negative = res[31];
            end

            OR: begin
                res = a | b;
                negative = res[31];
            end

            XOR: begin
                res = a ^ b;
                negative = res[31];
            end

            NOR: begin
                res = ~(a | b);
                negative = res[31];
            end

            SLT: begin
                res = ($signed(a) < $signed(b)) ? 1 : 0;
                flag = res[0];
                negative = res[31];
            end

            SLTU: begin
                res = (a < b) ? 1 : 0;
                flag = res[0];
                negative = res[31];
            end

            SLL: begin
                res = b << a[4:0];
                negative = res[31];
            end

            SRL: begin
                res = b >> a[4:0];
                negative = res[31];
            end

            SRA: begin
                res = $signed(b) >>> a[4:0];
                negative = res[31];
            end

            SLLV: begin
                res = b << a[4:0];
                negative = res[31];
            end

            SRLV: begin
                res = b >> a[4:0];
                negative = res[31];
            end

            SRAV: begin
                res = $signed(b) >>> a[4:0];
                negative = res[31];
            end

            LUI: begin
                res = {a[15:0], 16'b0};
                negative = res[31];
            end

            default: begin
                res = 32'bz;
                carry = 0;
                overflow = 0;
                negative = 0;
            end
        endcase

        r = res;
    end

endmodule

