module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output [15:0] result
);

    reg [7:0] saved_dividend, saved_divisor;
    reg [15:0] SR;
    reg [7:0] neg_divisor;
    reg [3:0] cnt;
    reg processing;
    reg [7:0] quotient;
    reg [7:0] remainder;


    wire dividend_sign = sign && saved_dividend[7];
    wire divisor_sign = sign && saved_divisor[7];
    wire quotient_sign = dividend_sign ^ divisor_sign;
    wire remainder_sign = dividend_sign;

    reg [15:0] res_reg;
    assign result = res_reg;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            processing <= 0;
            cnt <= 0;
            SR <= 0;
            saved_dividend <= 0;
            saved_divisor <= 0;
            neg_divisor <= 0;
            quotient <= 0;
            remainder <= 0;
            res_reg <= 0;
        end else begin
            if (opn_valid && !res_valid && !processing) begin

                if (sign) begin
                    saved_dividend <= dividend[7] ? (~dividend + 1) : dividend;
                    saved_divisor <= divisor[7] ? (~divisor + 1) : divisor;
                end else begin
                    saved_dividend <= dividend;
                    saved_divisor <= divisor;
                end
                neg_divisor <= -saved_divisor;
                SR <= {saved_dividend, 8'd0} << 1;
                cnt <= 1;
                processing <= 1;
                res_valid <= 0;
            end

            if (processing) begin
                if (cnt <= 8) begin

                    reg [15:0] temp_SR;
                    temp_SR = SR;
                    if (temp_SR[15:8] >= saved_divisor) begin
                        temp_SR[15:8] = temp_SR[15:8] - saved_divisor;
                        quotient <= {quotient[6:0], 1'b1};
                    end else begin
                        quotient <= {quotient[6:0], 1'b0};
                    end
                    temp_SR = temp_SR << 1;
                    SR <= temp_SR;
                    cnt <= cnt + 1;
                end else begin

                    remainder <= SR[15:8];

                    res_reg[15:8] <= remainder_sign ? -remainder : remainder;
                    res_reg[7:0] <= quotient_sign ? -quotient : quotient;
                    res_valid <= 1;
                    processing <= 0;
                    cnt <= 0;
                end
            end

            if (res_valid) begin


                res_valid <= 0;
            end
        end
    end

endmodule

