module fixed_point_adder #(
    parameter Q = 8,
    parameter N = 16
)(
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);

    reg [N-1:0] res;

    wire same_sign;
    wire [N-1:0] abs_a, abs_b;
    wire abs_compare;

    assign same_sign = (a[N-1] == b[N-1]);


    assign abs_a = a[N-1] ? (-a) : a;
    assign abs_b = b[N-1] ? (-b) : b;


    assign abs_compare = (abs_a > abs_b);


    always @* begin
        if (same_sign) begin
            res = a + b;
        end else begin
            if (abs_compare) begin
                res = a - b;
            end else begin
                res = b - a;
            end
        end
    end

    assign c = res;

endmodule

