module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent;
    reg [22:0] a_mantissa, b_mantissa;
    reg [23:0] a_mantissa24, b_mantissa24;
    reg [47:0] product;
    reg [9:0] exp_sum;
    reg [23:0] z_mantissa;
    reg [9:0] z_exponent;

    reg guard, round, sticky;

    reg a_is_nan, b_is_nan, a_is_inf, b_is_inf, a_is_zero, b_is_zero;

    always @* begin
        a_is_nan = (a_exponent == 8'hff) && (|a_mantissa);
        b_is_nan = (b_exponent == 8'hff) && (|b_mantissa);
        a_is_inf = (a_exponent == 8'hff) && (~|a_mantissa);
        b_is_inf = (b_exponent == 8'hff) && (~|b_mantissa);
        a_is_zero = (a_exponent == 0) && (~|a_mantissa);
        b_is_zero = (b_exponent == 0) && (~|b_mantissa);
    end

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            z <= 0;
        end else begin
            case (counter)
                0: begin
                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= a[22:0];
                    b_mantissa <= b[22:0];
                    a_mantissa24 <= (a_exponent == 0) ? {1'b0, a_mantissa} : {1'b1, a_mantissa};
                    b_mantissa24 <= (b_exponent == 0) ? {1'b0, b_mantissa} : {1'b1, b_mantissa};
                    counter <= 1;
                end
                1: begin
                    if (a_is_nan || b_is_nan) begin
                        z <= {1'b0, 8'hff, 23'h1};
                        counter <= 4;
                    end else if ((a_is_inf && b_is_zero) || (b_is_inf && a_is_zero)) begin
                        z <= {1'b0, 8'hff, 23'h1};
                        counter <=4;
                    end else if (a_is_inf || b_is_inf) begin
                        z <= {(a_sign ^ b_sign), 8'hff, 23'h0};
                        counter <=4;
                    end else if (a_is_zero || b_is_zero) begin
                        z <= { (a_sign ^ b_sign), 31'h0 };
                        counter <=4;
                    end else begin
                        exp_sum = a_exponent + b_exponent - 9'd127;
                        product = a_mantissa24 * b_mantissa24;
                        counter <=2;
                    end
                end
                2: begin
                    if (product[47]) begin
                        product = product >> 1;
                        exp_sum = exp_sum + 1;
                    end

                    guard = product[0];
                    round = product[1];
                    sticky = |product[24:1];

                    if (guard && (round || sticky || (z_mantissa[0]))) begin
                        z_mantissa = product[47:25] + 1;
                        if (z_mantissa == 24'h1_000000) begin
                            z_mantissa = 0;
                            exp_sum = exp_sum + 1;
                        end
                    end else begin
                        z_mantissa = product[47:24];
                    end
                    counter <=3;
                end
                3: begin
                    if (exp_sum >= 255) begin
                        z_exponent = 8'hff;
                        z_mantissa = 0;
                    end else if (exp_sum < 1) begin
                        z_exponent = 0;

                        z_mantissa = 0;
                    end else begin
                        z_exponent = exp_sum[7:0];
                    end
                    z <= {z_sign, z_exponent, z_mantissa[22:0]};
                    counter <=0;
                end
                default: counter <=0;
            endcase
        end
    end

endmodule

