module asyn_fifo #(
  parameter WIDTH = 8,
  parameter DEPTH = 16
)(
  input wclk,
  input wrstn,      
  input winc,
  input [WIDTH-1:0] wdata,

  input rclk,
  input rrstn,      
  input rinc,

  output wfull,
  output rempty,
  output [WIDTH-1:0] rdata
);

localparam ADDR_WIDTH = $clog2(DEPTH);
localparam PTR_WIDTH = ADDR_WIDTH + 1;


reg [PTR_WIDTH-1:0] wptr, rptr;


reg [PTR_WIDTH-1:0] wgray, rgray;


reg [PTR_WIDTH-1:0] r2w_gray, r2w_gray_sync;
reg [PTR_WIDTH-1:0] w2r_gray, w2r_gray_sync;


wire [PTR_WIDTH-1:0] wptr_next = wptr + 1;
wire [PTR_WIDTH-1:0] rptr_next = rptr + 1;


wire wen = winc && !wfull;
wire ren = rinc && !rempty;


dual_port_RAM #(
  .WIDTH(WIDTH),
  .DEPTH(DEPTH)
) ram_inst (
  .wclk(wclk),
  .wen(wen),
  .waddr(wptr[ADDR_WIDTH-1:0]),
  .wdata(wdata),
  .rclk(rclk),
  .ren(ren),
  .raddr(rptr[ADDR_WIDTH-1:0]),
  .rdata(rdata)
);


always @(posedge wclk or negedge wrstn) begin
  if (!wrstn) wptr <= 0;
  else if (wen) wptr <= wptr_next;
end

always @* begin
  wgray = (wptr >> 1) ^ wptr;
end


always @(posedge wclk or negedge wrstn) begin
  if (!wrstn) {r2w_gray_sync, r2w_gray} <= 0;
  else begin
    r2w_gray <= rgray;
    r2w_gray_sync <= r2w_gray;
  end
end


always @(posedge rclk or negedge rrstn) begin
  if (!rrstn) rptr <= 0;
  else if (ren) rptr <= rptr_next;
end

always @* begin
  rgray = (rptr >> 1) ^ rptr;
end


always @(posedge rclk or negedge rrstn) begin
  if (!rrstn) {w2r_gray_sync, w2r_gray} <= 0;
  else begin
    w2r_gray <= wgray;
    w2r_gray_sync <= w2r_gray;
  end
end


assign wfull = ( (wgray[PTR_WIDTH-1] != r2w_gray_sync[PTR_WIDTH-1]) 
                && (wgray[PTR_WIDTH-2] != r2w_gray_sync[PTR_WIDTH-2]) 
                && (wgray[PTR_WIDTH-3:0] == r2w_gray_sync[PTR_WIDTH-3:0]) );


assign rempty = (rgray == w2r_gray_sync);

endmodule


module dual_port_RAM #(
  parameter WIDTH = 8,
  parameter DEPTH = 16
)(
  input wclk,
  input wen,
  input [$clog2(DEPTH)-1:0] waddr,
  input [WIDTH-1:0] wdata,
  input rclk,
  input ren,
  input [$clog2(DEPTH)-1:0] raddr,
  output [WIDTH-1:0] rdata
);

reg [WIDTH-1:0] RAM [0:DEPTH-1];


always @(posedge wclk) begin
  if (wen) RAM[waddr] <= wdata;
end


reg [WIDTH-1:0] rdata_reg;
always @(posedge rclk) begin
  if (ren) rdata_reg <= RAM[raddr];
end

assign rdata = rdata_reg;

endmodule

