module LIFObuffer (
    input Clk,
    input Rst,
    input EN,
    input RW,
    input [3:0] dataIn,
    output EMPTY,
    output FULL,
    output [3:0] dataOut
);

reg [3:0] stack_mem [0:3];
reg [2:0] stack_ptr;
reg [3:0] dataOut_reg;

assign EMPTY = (stack_ptr == 4);
assign FULL = (stack_ptr == 0);
assign dataOut = dataOut_reg;

always @(posedge Clk) begin
    if (Rst) begin
        stack_mem[0] <= 0;
        stack_mem[1] <= 0;
        stack_mem[2] <= 0;
        stack_mem[3] <= 0;
        stack_ptr <= 4;
        dataOut_reg <= 0;
    end
    else if (EN) begin
        if (!FULL && !RW) begin 
            stack_mem[stack_ptr - 1] <= dataIn;
            stack_ptr <= stack_ptr - 1;
        end
        else if (!EMPTY && RW) begin 
            dataOut_reg <= stack_mem[stack_ptr];
            stack_mem[stack_ptr] <= 0;
            stack_ptr <= stack_ptr + 1;
        end
    end
end

endmodule

