module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

    reg [1:0] state;
    parameter IDLE = 2'd0;
    parameter S1 = 2'd1;
    parameter S2 = 2'd2;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            data_out <= 0;
        end else begin
            data_out <= 0;

            case (state)
                IDLE: begin
                    if (data_in == 0)
                        state <= S1;
                    else
                        state <= IDLE;
                end
                S1: begin
                    if (data_in == 1)
                        state <= S2;
                    else
                        state <= IDLE;

                end
                S2: begin
                    if (data_in == 0) begin
                        data_out <= 1;

                        state <= IDLE;
                    end else
                        state <= IDLE;

                end
                default: state <= IDLE;
            endcase
        end
    end

endmodule

