module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);

    parameter idle = 2'd0;
    parameter s1_red = 2'd1;
    parameter s2_yellow = 2'd2;
    parameter s3_green = 2'd3;

    reg [1:0] state, next_state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;


    assign clock = cnt;


    assign red = p_red;
    assign yellow = p_yellow;
    assign green = p_green;


    always @ (posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end else begin
            state <= next_state;
        end
    end


    always @ (*) begin
        case (state)
            idle: next_state = s1_red;
            s1_red: next_state = (cnt == 3) ? s3_green : s1_red;
            s3_green: next_state = (cnt == 3) ? s2_yellow : s3_green;
            s2_yellow: next_state = (cnt == 3) ? s1_red : s2_yellow;
            default: next_state = idle;
        endcase
    end


    always @ (posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 10;
        end else begin
            if (pass_request && green) begin
                if (cnt > 10) cnt <= 10;
            end
            else if (!green && p_green) begin
                cnt <= 60;
            end
            else if (!yellow && p_yellow) begin
                cnt <= 5;
            end
            else if (!red && p_red) begin
                cnt <= 10;
            end
            else begin
                cnt <= cnt - 1;
            end
        end
    end


    always @ (posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
        end else begin
            case (state)
                s1_red: begin
                    p_red <= 1;
                    p_yellow <= 0;
                    p_green <= 0;
                end
                s3_green: begin
                    p_red <= 0;
                    p_yellow <= 0;
                    p_green <= 1;
                end
                s2_yellow: begin
                    p_red <= 0;
                    p_yellow <= 1;
                    p_green <= 0;
                end
                default: begin
                    p_red <= 0;
                    p_yellow <= 0;
                    p_green <= 0;
                end
            endcase
        end
    end

endmodule

