module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output carry,
    output negative,
    output overflow,
    output flag
);

    parameter ADD  = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB  = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND  = 6'b100100;
    parameter OR   = 6'b100101;
    parameter XOR  = 6'b100110;
    parameter NOR  = 6'b100111;
    parameter SLT  = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL  = 6'b000000;
    parameter SRL  = 6'b000010;
    parameter SRA  = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI  = 6'b001111;

    reg [64:0] res;

    reg flag_reg;

    wire a_lt_slt = ($signed(a) < $signed(b));
    wire a_lt_sltu = (a < b);

    assign zero = (r == 32'b0);
    assign negative = r[31];
    assign carry = res[64];
    assign overflow = (aluc == ADD || aluc == SUB) ? (
        (aluc == ADD) ? ((a[31] == b[31]) && (res[31] != a[31])) :
        ((a[31] != b[31]) && (res[31] != a[31]))
    ) : 0;
    assign flag = (aluc == SLT || aluc == SLTU) ? flag_reg : 1'bz;

    always @* begin
        res = 65'b0;
        flag_reg = 1'bz;
        r = 32'b0;

        case (aluc)
            ADD: begin
                {res[64:32], r} = {1'b0, a} + {1'b0, b};
            end
            ADDU: begin
                {res[64:32], r} = a + b;
            end
            SUB: begin
                {res[64:32], r} = {1'b0, a} - {1'b0, b};
            end
            SUBU: begin
                {res[64:32], r} = a - b;
            end
            AND: r = a & b;
            OR: r = a | b;
            XOR: r = a ^ b;
            NOR: r = ~(a | b);
            SLT: begin
                r = a_lt_slt ? 32'd1 : 32'd0;
                flag_reg = a_lt_slt;
            end
            SLTU: begin
                r = a_lt_sltu ? 32'd1 : 32'd0;
                flag_reg = a_lt_sltu;
            end
            SLL: r = b << a[4:0];
            SRL: r = b >> a[4:0];
            SRA: r = $signed(b) >>> a[4:0];
            SLLV: r = a << b[4:0];
            SRLV: r = a >> b[4:0];
            SRAV: r = $signed(a) >>> b[4:0];
            LUI: r = {b[15:0], 16'b0};
            default: r = 32'bz;
        endcase
    end

endmodule

