module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [7:0] saved_div, saved_divisor;
    reg saved_sign;
    reg [15:0] SR;
    reg [3:0] cnt;
    reg [7:0] divisor_abs, neg_divisor;
    reg start_cnt;
    reg quotient_sign, remainder_sign;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            start_cnt <= 0;
            cnt <= 0;
            SR <= 0;
            saved_div <= 0;
            saved_divisor <= 0;
            saved_sign <= 0;
            quotient_sign <= 0;
            remainder_sign <= 0;
            result <= 0;
            divisor_abs <= 0;
            neg_divisor <= 0;
        end else begin
            if (opn_valid && !res_valid) begin

                saved_sign <= sign;
                saved_div <= sign ? (dividend[7] ? (~dividend +1) : dividend) : dividend;
                saved_divisor <= sign ? (divisor[7] ? (~divisor +1) : divisor) : divisor;
                quotient_sign <= 0;
                remainder_sign <= sign ? dividend[7] : 0;

                divisor_abs <= sign ? (divisor[7] ? (~divisor +1) : divisor) : divisor;
                neg_divisor <= -divisor_abs;


                SR <= {saved_div, 8'd0} << 1;
                cnt <= 0;
                start_cnt <= 1;
                res_valid <= 0;
            end else if (start_cnt && !res_valid) begin
                if (cnt < 8) begin

                    if (SR[15:8] >= divisor_abs) begin
                        SR[15:8] <= SR[15:8] - divisor_abs;
                        SR <= {SR[15:8] - divisor_abs, SR[7:0], 1'b1};
                    end else begin
                        SR <= {SR[15:8], SR[7:0], 1'b0};
                    end
                    cnt <= cnt + 1;
                end else begin

                    if (saved_sign) begin

                        result[15:8] <= remainder_sign ? (~SR[15:8] +1) : SR[15:8];

                        result[7:0] <= quotient_sign ? (~SR[7:0] +1) : SR[7:0];
                    end else begin
                        result <= {SR[15:8], SR[7:0]};
                    end
                    res_valid <= 1;
                    start_cnt <= 0;
                end
            end else if (!opn_valid && res_valid) begin
                res_valid <= 0;
            end
        end
    end
endmodule

