module multi_booth_8bit (
    input clk,
    input reset,
    input [7:0] a,
    input [7:0] b,
    output [15:0] p,
    output reg rdy
);

reg [15:0] multiplier;
reg [15:0] multiplicand;
reg [4:0] ctr;
reg [15:0] product_reg;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        multiplier <= {{8{a[7]}}, a};
        multiplicand <= {{8{b[7]}}, b};
        product_reg <= 0;
        ctr <= 0;
        rdy <= 0;
    end
    else begin
        rdy <= 0;
        if (ctr < 16) begin
            multiplicand <= multiplicand << 1;
            if (multiplier[ctr]) begin
                product_reg <= product_reg + multiplicand;
            end
            ctr <= ctr + 1;
        end
        if (ctr >= 16) begin
            rdy <= 1;
        end
    end
end

assign p = product_reg;

