module multi_16bit (
  input clk,
  input rst_n,
  input start,
  input [15:0] ain,
  input [15:0] bin,
  output reg [31:0] yout,
  output reg done
);

  reg [4:0] i;

  reg [15:0] areg;

  reg [15:0] breg;

  reg [31:0] yout_r;


  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      i <= 5'd0;
    end else begin
      if (start) begin
        if (i < 17)
          i <= i + 1;
      end else begin
        i <= 5'd0;
      end
    end
  end


  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      done <= 1'b0;
    end else begin
      if (i == 16)
        done <= 1'b1;
      else if (i == 17)
        done <= 1'b0;
    end
  end


  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      areg <= 16'd0;
      breg <= 16'd0;
      yout_r <= 32'd0;
    end else begin
      if (i == 5'd0 && start) begin

        areg <= ain;
        breg <= bin;
      end else if (i > 5'd0 && i < 17) begin
        if (areg[i-1]) begin
          yout_r <= yout_r + ( { {16{1'b0}}, breg } << (i-1) );
        end
      end
    end
  end


  always @* begin
    yout = yout_r;
  end

endmodule

