module fixed_point_subtractor #(
    parameter Q = 8,
    parameter N = 16
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);
    reg [N-1:0] res;
    reg a_sign, b_sign;
    reg [N-1:0] a_abs, b_abs;
    reg [N-1:0] res_mag;
    reg res_sign;

    always @* begin
        a_sign = a[N-1];
        b_sign = b[N-1];


        a_abs = a_sign ? (~a + 1) : a;
        b_abs = b_sign ? (~b + 1) : b;

        if (a_sign == b_sign) begin

            res = a - b;
            res[N-1] = a_sign;

            if (res == 0)
                res[N-1] = 0;

        end else begin

            if (a_abs >= b_abs) begin
                res_mag = a_abs - b_abs;
                res_sign = a_sign;
            end else begin
                res_mag = b_abs - a_abs;
                res_sign = b_sign;
            end
            res = {res_sign, res_mag};
            if (res_abs == 0) 
                res[N-1] = 0;
        end
    end

    assign c = res;
endmodule

