            dataOut_reg <= 0;

            for (i = 0;
 i < 4;
 i = i + 1)
                stack_mem[i] <= 0;
        end else if (EN) begin
            if (!RW) begin 
                if (!FULL) begin
                    stack_mem[SP - 1] <= dataIn;
                    SP <= SP - 1;
                end
            end else begin 
                if (!EMPTY) begin
                    dataOut_reg <= stack_mem[SP - 1];
                    SP <= SP + 1;
                end
            end
        end
    end
