module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);

    parameter idle = 2'd0;
    parameter s1_red = 2'd1;
    parameter s2_yellow = 2'd2;
    parameter s3_green = 2'd3;

    reg [1:0] state, next_state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;
    reg r_red, r_yellow, r_green;

    assign clock = cnt;
    assign red = r_red;
    assign yellow = r_yellow;
    assign green = r_green;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end else begin
            case (state)
                idle: state <= s1_red;
                s1_red: state <= (cnt == 0) ? s3_green : s1_red;
                s3_green: state <= (cnt == 0) ? s2_yellow : s3_green;
                s2_yellow: state <= (cnt == 0) ? s1_red : s2_yellow;
                default: state <= idle;
            endcase
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 10;
        end else begin
            if (pass_request && green) begin
                if (cnt > 10) cnt <= 10;
            end else begin
                if ((p_green && !green)) cnt <= 60;
                else if ((p_yellow && !yellow)) cnt <=5;
                else if ((p_red && !red)) cnt <=10;
                else cnt <= cnt -1;
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
        end else begin
            case (state)
                idle: {p_red, p_yellow, p_green} <= 3'b000;
                s1_red: {p_red, p_yellow, p_green} <= 3'b100;
                s3_green: {p_red, p_yellow, p_green} <= 3'b001;
                s2_yellow: {p_red, p_yellow, p_green} <= 3'b010;
                default: {p_red, p_yellow, p_green} <= 3'b000;
            endcase
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            {r_red, r_yellow, r_green} <= 3'b000;
        end else begin
            {r_red, r_yellow, r_green} <= {p_red, p_yellow, p_green};
        end
    end

endmodule

