module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output [31:0] r,
    output zero,
    output carry,
    output negative,
    output overflow,
    output flag
);


    parameter [5:0] 
        ADD = 6'b100000,
        ADDU = 6'b100001,
        SUB = 6'b100010,
        SUBU = 6'b100011,
        AND = 6'b100100,
        OR = 6'b100101,
        XOR = 6'b100110,
        NOR = 6'b100111,
        SLT = 6'b101010,
        SLTU = 6'b101011,
        SLL = 6'b000000,
        SRL = 6'b000010,
        SRA = 6'b000011,
        SLLV = 6'b000100,
        SRLV = 6'b000110,
        SRAV = 6'b000111,
        LUI = 6'b001111;

    reg [31:0] res;
    reg carry_out, overflow_out;
    reg flag_reg;


    assign r = res;
    assign zero = (res == 32'd0);
    assign carry = carry_out;
    assign negative = res[31];
    assign overflow = overflow_out;
    assign flag = (aluc == SLT || aluc == SLTU) ? flag_reg : 1'bz;


    always @* begin
        res = 32'd0;
        carry_out = 1'b0;
        overflow_out = 1'b0;
        flag_reg = 1'b0;

        case (aluc)
            ADD: begin
                {carry_out, res} = {1'b0, a} + {1'b0, b};
                overflow_out = ( (a[31] == b[31]) && (res[31] != a[31]) );
            end
            ADDU: begin
                {carry_out, res} = a + b;
                overflow_out = 1'b0;
            end
            SUB: begin
                {carry_out, res} = {1'b0, a} - {1'b0, b};
                overflow_out = ( (a[31] != b[31]) && (res[31] != a[31]) );
            end
            SUBU: begin
                res = a - b;
                overflow_out = 1'b0;
                carry_out = (a >= b);

            end
            AND: res = a & b;
            OR:  res = a | b;
            XOR: res = a ^ b;
            NOR: res = ~(a | b);
            SLT: begin
                res = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
                flag_reg = res[0];
            end
            SLTU: begin
                res = (a < b) ? 32'd1 : 32'd0;
                flag_reg = res[0];
            end
            SLL:   res = b << a[4:0];
            SRL:   res = b >> a[4:0];
            SRA:   res = $signed(b) >>> a[4:0];
            SLLV:  res = a << b[4:0];
            SRLV:  res = a >> b[4:0];
            SRAV:  res = $signed(a) >>> b[4:0];
            LUI:   res = {b[15:0], 16'b0};
            default: res = 32'bz;
        endcase
    end

endmodule

