module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output [15:0] result
);

    reg [7:0] dividend_abs;
    reg [7:0] divisor_abs;
    reg sign_quotient;
    reg sign_remainder;
    reg [15:0] result_reg;

    reg [8:0] SR;

    reg [3:0] cnt;
    reg start_cnt;

    reg [7:0] quotient;
    reg [7:0] remainder;


    reg [7:0] dividend_reg;
    reg [7:0] divisor_reg;

    assign result = result_reg;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            SR <= 0;
            cnt <= 0;
            start_cnt <= 0;
            quotient <= 0;
            remainder <= 0;
            dividend_reg <= 0;
            divisor_reg <= 0;
            sign_quotient <= 0;
            sign_remainder <= 0;
            dividend_abs <= 0;
            divisor_abs <= 0;
            result_reg <= 0;
        end else begin
            if (opn_valid && !res_valid && !start_cnt) begin

                sign_quotient <= sign ? (dividend[7] ^ divisor[7]) : 0;
                sign_remainder <= sign ? dividend[7] : 0;


                dividend_abs <= sign && dividend[7] ? (~dividend + 1) : dividend;
                divisor_abs <= sign && divisor[7] ? (~divisor + 1) : divisor;


                SR <= { (sign ? (~dividend + 1) : dividend), 1'b0 };

                cnt <= 0;
                start_cnt <= 1;
                res_valid <= 0;
            end else if (start_cnt && !res_valid) begin
                if (cnt == 8) begin

                    SR <= { remainder, quotient };
                    start_cnt <= 0;
                    cnt <= 0;
                    res_valid <= 1;


                    if (sign_quotient) quotient <= ~quotient + 1;
                    if (sign_remainder) remainder <= ~remainder + 1;
                    result_reg <= { remainder, quotient };
                end else begin

                    if (SR[8] >= divisor_abs[7:0]) begin
                        remainder = SR[8:1] - divisor_abs[7:0];
                        quotient = (quotient << 1) | 1;
                    end else begin
                        remainder = SR[8:1];
                        quotient = quotient << 1;
                    end
                    SR <= { remainder, quotient };
                    cnt <= cnt + 1;
                end
            end
        end
    end

endmodule

