module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output [15:0] result,
    output [15:0] odd
);

    reg [15:0] a_reg;
    reg [7:0] b_reg;
    reg [15:0] quotient;
    reg [15:0] remainder;


    always @ (A, B) begin
        a_reg = A;
        b_reg = B;
    end


    always @ (*) begin
        integer i;
        reg [15:0] temp;

        temp = 16'd0;
        quotient = 16'd0;

        for (i = 15;
 i >= 0;
 i = i - 1) begin

            temp = (temp << 1) | (a_reg[i]);


            if (temp >= {8'd0, b_reg}) begin
                quotient[i] = 1;
                temp = temp - {8'd0, b_reg};
            end else begin
                quotient[i] = 0;
            end
        end


        remainder = temp;
    end


    assign result = quotient;
    assign odd = remainder;

endmodule

