module fixed_point_subtractor #(
    parameter Q = 16,
    parameter N = 32
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

    reg [N-1:0] res;
    wire sign_a, sign_b;
    wire [N-1:0] abs_a, abs_b;

    assign sign_a = a[N-1];
    assign sign_b = b[N-1];


    assign abs_a = sign_a ? (~a + 1) : a;
    assign abs_b = sign_b ? (~b + 1) : b;

    always @* begin
        if (sign_a == sign_b) begin

            res = a - b;


            if (res == 0)
                res[N-1] = 1'b0;
        end else begin

            if (sign_a == 1'b0 && sign_b == 1'b1) begin

                res = abs_a + abs_b;
                res[N-1] = 1'b0;

            end else begin

                if (abs_a > abs_b) begin
                    res = abs_a - abs_b;
                    res[N-1] = 1'b1;

                end else begin
                    res = abs_b - abs_a;
                    res[N-1] = 1'b0;

                end
            end
        end
    end

    assign c = res;

endmodule

