assign wgray = (waddr_bin >> 1) ^ waddr_bin;
assign rgray = (raddr_bin >> 1) ^ raddr_bin;


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        rgray_sync1 <= 0;
        rgray_sync <= 0;
    end else begin
        rgray_sync1 <= rgray;
        rgray_sync <= rgray_sync1;
    end
