    if (!rrstn) begin
        wgray_sync1 <= 0;
        wgray_sync <= 0;
    end else begin
        wgray_sync1 <= wgray;
        wgray_sync <= wgray_sync1;
    end
end


assign full = (wgray[PTR_WIDTH-1] != rgray_sync[PTR_WIDTH-1]) &&
              (wgray[PTR_WIDTH-2] != rgray_sync[PTR_WIDTH-2]) &&
              (wgray[PTR_WIDTH-3:0] == rgray_sync[PTR_WIDTH-3:0]);


assign empty = (rgray == wgray_sync);



always @(posedge wclk or negedge wrstn) begin
    if (!wrstn)
        waddr_bin <= 0;
    else if (winc && !full)
        waddr_bin <= waddr_bin + 1;
