module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);

    parameter idle = 0,
              s1_red = 1,
              s2_yellow = 2,
              s3_green = 3;

    reg [1:0] state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;
    reg r, y, g;

    assign red = p_red;
    assign yellow = p_yellow;
    assign green = p_green;
    assign clock = cnt;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
            cnt <= 10;
            r <= 0;
 y <= 0;
 g <= 0;
        end
        else begin

            r <= p_red;
            y <= p_yellow;
            g <= p_green;

            case (state)
                idle: begin
                    state <= s1_red;
                    {p_red, p_yellow, p_green} <= 3'b100;
                    cnt <= 3;
                end

                s1_red: begin
                    if (cnt == 0) begin
                        state <= s3_green;
                        {p_red, p_yellow, p_green} <= 3'b001;
                        cnt <= 60;
                    end
                    else cnt <= cnt - 1;
                end

                s3_green: begin
                    if (pass_request && p_green) begin
                        if (cnt > 10) cnt <= 10;
                    end
                    if (cnt == 0) begin
                        state <= s2_yellow;
                        {p_red, p_yellow, p_green} <= 3'b010;
                        cnt <=5;
                    end
                    else cnt <= cnt -1;
                end

                s2_yellow: begin
                    if (cnt ==0) begin
                        state <= s1_red;
                        {p_red, p_yellow, p_green} <= 3'b100;
                        cnt <=10;
                    end
                    else cnt <= cnt -1;
                end

                default: state <= idle;
            endcase
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) cnt <=10;
        else begin
            if (pass_request && p_green) begin
                if (cnt > 10) cnt <=10;
            end
            else begin
                if (!p_green && g) cnt <=60;
                else if (!p_yellow && y) cnt <=5;
                else if (!p_red && r) cnt <=10;
                else cnt <= cnt -1;
            end
        end
    end

endmodule

