module fixed_point_adder #(
    parameter Q = 8,
    parameter N = 32
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

    reg [N-1:0] res;
    reg [N-1:0] abs_a, abs_b;
    reg a_sign, b_sign;
    reg sign_res;
    reg [N-1:0] mag;

    always @* begin
        a_sign = a[N-1];
        b_sign = b[N-1];

        if (a_sign == b_sign) begin

            res = a + b;
        end else begin

            abs_a = a_sign ? (~a + 1) : a;
            abs_b = b_sign ? (~b + 1) : b;


            if (abs_a > abs_b) begin
                mag = abs_a - abs_b;
                sign_res = a_sign;
            end else begin
                mag = abs_b - abs_a;
                sign_res = b_sign;
            end


            if (sign_res)
                res = ~mag + 1;
            else
                res = mag;
        end
    end

    assign c = res;

endmodule

