module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent;
    reg [22:0] a_mantissa, b_mantissa;
    reg [9:0] z_exponent;
    reg [49:0] product;
    reg [22:0] z_mantissa;
    reg guard_bit, round_bit, sticky;


    wire a_zero = (a_exponent == 8'd0) && (a_mantissa == 23'd0);
    wire b_zero = (b_exponent == 8'd0) && (b_mantissa == 23'd0);
    wire a_inf = (a_exponent == 8'hFF) && (a_mantissa == 23'd0);
    wire b_inf = (b_exponent == 8'hFF) && (b_mantissa == 23'd0);
    wire a_nan = (a_exponent == 8'hFF) && (a_mantissa != 23'd0);
    wire b_nan = (b_exponent == 8'hFF) && (b_mantissa != 23'd0);

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            z <= 0;
        end else begin
            case (counter)

                3'd0: begin
                    a_sign <= a[31];
                    a_exponent <= a[30:23];
                    a_mantissa <= a[22:0];

                    b_sign <= b[31];
                    b_exponent <= b[30:23];
                    b_mantissa <= b[22:0];

                    counter <= counter + 1;
                end


                3'd1: begin
                    if (a_nan || b_nan) begin

                        z <= 32'h7FC00000;

                        counter <= 0;
                    end else if ((a_zero && b_inf) || (b_zero && a_inf)) begin

                        z <= 32'h7FC00000;
                        counter <= 0;
                    end else if (a_inf || b_inf) begin

                        z <= {a_sign ^ b_sign, 8'hFF, 23'd0};
                        counter <= 0;
                    end else if (a_zero || b_zero) begin

                        z <= {a_sign ^ b_sign, 31'd0};
                        counter <= 0;
                    end else begin

                        product <= {1'b1, a_mantissa} * {1'b1, b_mantissa};
                        z_exponent <= a_exponent + b_exponent - 8'd127 + 1;
                        z_sign <= a_sign ^ b_sign;
                        counter <= counter + 1;
                    end
                end


                3'd2: begin

                    if (product[49]) begin 
                        z_mantissa <= product[48:25];
                        z_exponent <= z_exponent + 1;
                    end else begin
                        z_mantissa <= product[47:24];
                    end


                    if (z_exponent >= 9'h0FE) begin 
                        z <= {z_sign, 8'hFF, 23'd0};
                    end else if (z_exponent == 0) begin 
                        z <= {z_sign, 31'd0};
                    end else begin

                        z <= {z_sign, z_exponent[7:0], z_mantissa};
                    end
                    counter <= 0;
                end
            endcase
        end
    end

endmodule

