module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
)(
    input wclk,
    input rclk,
    input wrstn,
    input rrstn,
    input winc,
    input rinc,
    input [WIDTH-1:0] wdata,
    output wfull,
    output rempty,
    output [WIDTH-1:0] rdata
);

localparam ADDR_WIDTH = $clog2(DEPTH);


reg [ADDR_WIDTH:0] wptr_bin, rptr_bin;
reg [ADDR_WIDTH:0] wptr_gray, rptr_gray;


reg [ADDR_WIDTH:0] rptr_gray_sync_r1, rptr_gray_sync_r2;
reg [ADDR_WIDTH:0] wptr_gray_sync_w1, wptr_gray_sync_w2;


wire wen = winc && !wfull;
wire ren = rinc && !rempty;


wire [ADDR_WIDTH-1:0] waddr_ram = wptr_bin[ADDR_WIDTH-1:0];
wire [ADDR_WIDTH-1:0] raddr_ram = rptr_bin[ADDR_WIDTH-1:0];


dual_port_RAM #(
    .WIDTH(WIDTH),
    .DEPTH(DEPTH)
) ram_inst (
    .wclk(wclk),
    .wen(wen),
    .waddr(waddr_ram),
    .wdata(wdata),
    .rclk(rclk),
    .ren(ren),
    .raddr(raddr_ram),
    .rdata(rdata)
);


function [ADDR_WIDTH:0] bin2gray(input [ADDR_WIDTH:0] bin);
    bin2gray = bin ^ (bin >> 1);
endfunction


function [ADDR_WIDTH:0] gray2bin(input [ADDR_WIDTH:0] gray);
    integer i;
    begin
        gray2bin[ADDR_WIDTH] = gray[ADDR_WIDTH];
        for (i = ADDR_WIDTH-1;
 i >= 0;
 i = i-1)
            gray2bin[i] = gray2bin[i+1] ^ gray[i];
    end
endfunction


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        wptr_bin <= 0;
        wptr_gray <= 0;
    end else if (wen) begin
        wptr_bin <= wptr_bin + 1;
        wptr_gray <= bin2gray(wptr_bin + 1);
    end
end


always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        rptr_bin <= 0;
        rptr_gray <= 0;
    end else if (ren) begin
        rptr_bin <= rptr_bin + 1;
        rptr_gray <= bin2gray(rptr_bin + 1);
    end
end


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        rptr_gray_sync_r1 <= 0;
        rptr_gray_sync_r2 <= 0;
    end else begin
        rptr_gray_sync_r1 <= rptr_gray;
        rptr_gray_sync_r2 <= rptr_gray_sync_r1;
    end
end


always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        wptr_gray_sync_w1 <= 0;
        wptr_gray_sync_w2 <= 0;
    end else begin
        wptr_gray_sync_w1 <= wptr_gray;
        wptr_gray_sync_w2 <= wptr_gray_sync_w1;
    end
end


wire [ADDR_WIDTH:0] rptr_sync_bin = gray2bin(rptr_gray_sync_w2);
assign wfull = (wptr_bin - rptr_sync_bin) >= DEPTH;
assign rempty = (rptr_gray == wptr_gray_sync_r2);

endmodule


module dual_port_RAM #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
)(
    input wclk,
    input wen,
    input [$clog2(DEPTH)-1:0] waddr,
    input [WIDTH-1:0] wdata,
    input rclk,
    input ren,
    input [$clog2(DEPTH)-1:0] raddr,
    output reg [WIDTH-1:0] rdata
);

reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];


always @(posedge wclk) begin
    if (wen)
        RAM_MEM[waddr] <= wdata;
end


always @(posedge rclk) begin
    if (ren)
        rdata <= RAM_MEM[raddr];
end

