module LIFObuffer (
    input [3:0] dataIn,
    input RW,
    input EN,
    input Rst,
    input Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);

reg [3:0] stack_mem [0:3];
reg [2:0] SP;


integer i;

always @(posedge Clk) begin
    if (Rst) begin
        SP <= 4;

        EMPTY <= 1;
        FULL <= 0;
        dataOut <= 0;

        for (i = 0;
 i < 4;
 i = i + 1)
            stack_mem[i] <= 0;
    end else if (EN) begin
        if (RW) begin 
            if (!EMPTY) begin
                dataOut <= stack_mem[SP];
                stack_mem[SP] <= 0;

                SP <= SP + 1;

            end
        end else begin 
            if (!FULL) begin
                stack_mem[SP] <= dataIn;
                SP <= SP - 1;

            end
        end

        EMPTY <= (SP == 4);
        FULL <= (SP == 0);
    end
end

endmodule

