module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);

    parameter [1:0] idle = 2'd0,
                    s1_red = 2'd1,
                    s3_green = 2'd2,
                    s2_yellow = 2'd3;

    reg [1:0] state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;


    assign red = p_red;
    assign yellow = p_yellow;
    assign green = p_green;
    assign clock = cnt;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end else begin
            case (state)
                idle:        state <= s1_red;
                s1_red:      state <= (cnt == 0) ? s3_green : s1_red;
                s3_green:    state <= (cnt == 0) ? s2_yellow : s3_green;
                s2_yellow:   state <= (cnt == 0) ? s1_red : s2_yellow;
                default:     state <= idle;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 8'd10;
        end else begin
            if (pass_request && green && cnt > 8'd10) begin
                cnt <= 8'd10;
            end else if (!green && p_green) begin
                cnt <= 8'd60;

            end else if (!yellow && p_yellow) begin
                cnt <= 8'd5;

            end else if (!red && p_red) begin
                cnt <= 8'd10;

            end else begin
                cnt <= cnt - 1;
            end
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
        end else begin
            case (state)
                s1_red: begin
                    p_red <= 1;
                    p_yellow <= 0;
                    p_green <= 0;
                end
                s3_green: begin
                    p_red <= 0;
                    p_yellow <= 0;
                    p_green <= 1;
                end
                s2_yellow: begin
                    p_red <= 0;
                    p_yellow <= 1;
                    p_green <= 0;
                end
                default: begin
                    p_red <= 0;
                    p_yellow <= 0;
                    p_green <= 0;
                end
            endcase
        end
    end

endmodule

