module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg processing;
    reg [3:0] cnt;
    reg [7:0] divd_abs, divs_abs;
    reg [7:0] quotient, remainder;
    reg [15:0] SR;
    reg [7:0] saved_dividend, saved_divisor;
    reg sign_quotient, sign_remainder;

    wire [8:0] subtract;
    wire subtract_borrow, carry_out;


    assign subtract = {1'b0, SR[15:8]} - {1'b0, divs_abs};
    assign subtract_borrow = subtract[8];
    assign carry_out = ~subtract_borrow;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            processing <= 0;
            cnt <= 0;
            SR <= 0;
            quotient <= 0;
            remainder <= 0;
            sign_quotient <= 0;
            sign_remainder <= 0;
            saved_dividend <= 0;
            saved_divisor <= 0;
        end else begin
            if (processing) begin
                if (cnt == 8) begin

                    processing <= 0;
                    res_valid <= 1;

                    if (sign) begin
                        quotient <= (sign_quotient) ? (~quotient + 1) : quotient;
                        remainder <= (sign_remainder) ? (~remainder + 1) : remainder;
                    end
                    result <= {remainder, quotient};
                end else begin

                    if (carry_out) begin
                        remainder <= subtract[7:0];
                        quotient <= {quotient[6:0], 1'b1};
                    end else begin
                        quotient <= {quotient[6:0], 1'b0};
                    end

                    SR <= {remainder, quotient} << 1;
                    cnt <= cnt + 1;
                end
            end else if (opn_valid && !res_valid) begin

                saved_dividend <= dividend;
                saved_divisor <= divisor;
                processing <= 1;
                cnt <= 1;
                res_valid <= 0;


                if (sign) begin
                    sign_quotient <= (dividend[7] ^ divisor[7]);
                    sign_remainder <= dividend[7];
                    divd_abs <= (dividend[7]) ? (~dividend + 1) : dividend;
                    divs_abs <= (divisor[7]) ? (~divisor + 1) : divisor;
                end else begin
                    sign_quotient <= 0;
                    sign_remainder <= 0;
                    divd_abs <= dividend;
                    divs_abs <= divisor;
                end

                SR <= {divd_abs, 8'd0} << 1;
            end

            if (opn_valid && !res_valid) res_valid <= 0;
        end
    end

endmodule

