module fixed_point_adder #(
    parameter Q = 8,
    parameter N = 16
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

    reg [N-1:0] res;


    wire sign_a = a[N-1];
    wire sign_b = b[N-1];


    wire [N-1:0] abs_a = sign_a ? (~a + 1) : a;
    wire [N-1:0] abs_b = sign_b ? (~b + 1) : b;


    wire same_sign = (sign_a == sign_b);

    always @* begin
        if (same_sign) begin

            res = abs_a + abs_b;
            res[N-1] = sign_a;
        end else begin

            if (abs_a > abs_b) begin
                res = abs_a - abs_b;
                res[N-1] = sign_a;
            end else if (abs_b > abs_a) begin
                res = abs_b - abs_a;
                res[N-1] = sign_b;
            end else begin

                res = 0;
            end
        end
    end

    assign c = res;

endmodule

