module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

reg [2:0] counter;
reg a_sign, b_sign;
reg [7:0] a_exponent, b_exponent;
reg [22:0] a_mantissa, b_mantissa;
reg [47:0] product;
reg z_sign;
reg [7:0] sum_exp;
reg [22:0] z_mant;
reg [7:0] z_exponent;
reg guard_bit, round_bit, sticky_bit;


wire a_is_nan = (a_exponent == 8'hFF) && (|a_mantissa);
wire b_is_nan = (b_exponent == 8'hFF) && (|b_mantissa);
wire a_is_inf = (a_exponent == 8'hFF) && (a_mantissa == 0);
wire b_is_inf = (b_exponent == 8'hFF) && (b_mantissa == 0);
wire a_is_zero = (a_exponent == 0) && (a_mantissa == 0);
wire b_is_zero = (b_exponent == 0) && (b_mantissa == 0);


reg [23:0] a_mant, b_mant;


reg round_up;

always @(posedge clk) begin
    if (rst) begin
        counter <= 0;
        z <= 0;
    end else begin
        case (counter)

            0: begin
                a_sign <= a[31];
                b_sign <= b[31];
                a_exponent <= a[30:23];
                b_exponent <= b[30:23];
                a_mantissa <= a[22:0];
                b_mantissa <= b[22:0];
                counter <= 1;
            end

            1: begin

                if (a_exponent == 0) begin
                    a_mant = (a_mantissa == 0) ? 0 : {1'b0, a_mantissa};
                end else begin
                    a_mant = {1'b1, a_mantissa};
                end

                if (b_exponent == 0) begin
                    b_mant = (b_mantissa == 0) ? 0 : {1'b0, b_mantissa};
                end else begin
                    b_mant = {1'b1, b_mantissa};
                end


                if (a_is_nan || b_is_nan) begin
                    z <= {1'b0, 8'hFF, 1'b1, 22'h0};
                    counter <= 0;
                end else if ((a_is_inf && b_is_zero) || (b_is_inf && a_is_zero)) begin
                    z <= {1'b0, 8'hFF, 1'b1, 22'h0};
                    counter <= 0;
                end else if (a_is_inf || b_is_inf) begin
                    z <= {(a_is_inf || b_is_inf), 8'hFF, 23'h0};
                    counter <= 0;
                end else if (a_is_zero || b_is_zero) begin
                    z <= {a_sign ^ b_sign, 31'h0};
                    counter <= 0;
                end else begin
                    product <= a_mant * b_mant;
                    sum_exp <= a_exponent + b_exponent - 8'hFF;

                    counter <= 2;
                end
            end

            2: begin

                if (product[47]) begin 
                    product <= product >> 1;
                    sum_exp <= sum_exp + 1;
                end

                guard_bit <= product[0];
                round_bit <= product[1];
                sticky_bit <= |product[63:2];

                round_up <= guard_bit & (round_bit | sticky_bit);

                z_mant <= product[46:24];

                sum_exp <= (sum_exp > 0) ? sum_exp : 0;


                if (sum_exp >= 255) begin 
                    z_exponent <= 255;
                    z_mant <= 0;
                end else if (sum_exp <= 0) begin 
                    z_exponent <= 0;
                    z_mant <= 0;
                end else begin
                    z_exponent <= sum_exp;
                end

                z <= {z_sign ^ (a_sign ^ b_sign), z_exponent, z_mant};
                counter <= 0;
            end
        endcase
    end
end

endmodule

