module fsm (IN, CLK, RST, MATCH);
    input IN, CLK, RST;
    output reg MATCH;

    reg [2:0] state, next_state;
    localparam S0 = 0, S1 = 1, S2 = 2, S3 = 3, S4 = 4;


    always @(posedge CLK or posedge RST) begin
        if (RST) begin
            state <= S0;
        end else begin
            state <= next_state;
        end
    end


    always @* begin
        if (RST) begin
            MATCH = 0;
            next_state = S0;
        end else begin
            MATCH = 0;
            next_state = state;
            case (state)
                S0: begin
                    if (IN) next_state = S1;
                    else next_state = S0;
                end
                S1: begin
                    if (~IN) next_state = S2;
                    else next_state = S1;
                end
                S2: begin
                    if (~IN) next_state = S3;
                    else next_state = S1;
                end
                S3: begin
                    if (IN) next_state = S4;
                    else next_state = S2;
                end
                S4: begin
                    if (IN) begin
                        MATCH = 1;
                        next_state = S1;
                    end else begin
                        next_state = S0;
                    end
                end
                default: next_state = S0;
            endcase
        end
    end
endmodule

