    mux2X1 #(8) mux2(
        .a(shifted4),
        .b(rotated2),
        .sel(ctrl[1]),
        .y(shifted2)
    );

    wire [7:0] rotated1;
    assign rotated1 = {shifted2[0], shifted2[7:1]};

    mux2X1 #(8) mux1(
        .a(shifted2),
        .b(rotated1),
        .sel(ctrl[0]),
        .y(out)
    );

