reg [PTR_WIDTH-1:0] wptr_gray, rptr_gray;


reg [PTR_WIDTH-1:0] wptr_gray_sync_rd0, wptr_gray_sync_rd;
reg [PTR_WIDTH-1:0] rptr_gray_sync_wr0, rptr_gray_sync_wr;


