module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);

    parameter idle = 2'd0;
    parameter s1_red = 2'd1;
    parameter s2_yellow = 2'd2;
    parameter s3_green = 2'd3;

    reg [1:0] state, next_state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;

    assign clock = cnt;
    assign red = p_red;
    assign yellow = p_yellow;
    assign green = p_green;


    always @ (posedge clk or negedge rst_n) begin
        if (!rst_n) state <= idle;
        else state <= next_state;
    end


    always @ (*) begin
        case (state)
            idle: next_state = s1_red;
            s1_red: next_state = (cnt == 3) ? s3_green : s1_red;
            s3_green: next_state = (cnt == 60) ? s2_yellow : s3_green;
            s2_yellow: next_state = (cnt == 5) ? s1_red : s2_yellow;
            default: next_state = idle;
        endcase
    end


    always @ (posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 10;
        end else begin

            if (pass_request && green && (cnt > 10))
                cnt <= 10;

            else if (state != s3_green && state != s2_yellow && state != s1_red)
                cnt <= 60;
            else if (state != s2_yellow && state != s3_green)
                cnt <= 5;
            else if (state != s1_red)
                cnt <= 10;

            else if (cnt > 0)
                cnt <= cnt - 1;
        end
    end


    always @ (posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
        end else begin
            case (state)
                s1_red: begin
                    p_red <= 1;
                    p_yellow <= 0;
                    p_green <= 0;
                end
                s3_green: begin
                    p_red <= 0;
                    p_yellow <= 0;
                    p_green <= 1;
                end
                s2_yellow: begin
                    p_red <= 0;
                    p_yellow <= 1;
                    p_green <= 0;
                end
                default: begin
                    p_red <= 0;
                    p_yellow <= 0;
                    p_green <= 0;
                end
            endcase
        end
    end

endmodule

