module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output [15:0] result
);

    reg [7:0] saved_dividend;
    reg [7:0] saved_divisor;
    reg [7:0] abs_dividend;
    reg [7:0] abs_divisor;
    reg [7:0] divisor_neg;
    reg [15:0] SR;
    reg [3:0] cnt;
    reg processing;
    reg sign_reg;

    reg [7:0] quotient;
    reg [7:0] remainder;
    reg [15:0] result_reg;

    wire [15:0] sub_result = SR - {8'b0, divisor_neg};
    wire carry = ~sub_result[15];



    assign result = result_reg;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            processing <= 0;
            cnt <= 0;
            result_reg <= 0;
            sign_reg <= 0;
            saved_dividend <= 0;
            saved_divisor <= 0;
            abs_dividend <= 0;
            abs_divisor <= 0;
            divisor_neg <= 0;
            quotient <= 0;
            remainder <= 0;
            SR <= 0;
        end else begin
            if (opn_valid && !res_valid && !processing) begin

                sign_reg <= sign;
                saved_dividend <= dividend;
                saved_divisor <= divisor;


                abs_dividend <= sign && dividend[7] ? (~dividend + 1) : dividend;
                abs_divisor <= sign && divisor[7] ? (~divisor + 1) : divisor;


                divisor_neg <= ~abs_divisor + 1;
                SR <= {abs_dividend, 8'b0};

                cnt <= 0;
                quotient <= 0;
                processing <= 1;
                res_valid <= 0;
            end else if (processing) begin
                if (cnt < 8) begin
                    if (carry) begin
                        SR <= {sub_result[14:8], SR[7:1], 1'b1};
                        quotient <= {quotient[6:0], 1'b1};
                    end else begin
                        SR <= {SR[14:8], SR[7:1], 1'b0};
                        quotient <= {quotient[6:0], 1'b0};
                    end
                    cnt <= cnt + 1;
                end else begin

                    remainder <= SR[15:8];

                    result_reg <= {remainder, quotient};
                    processing <= 0;
                    res_valid <= 1;
                end
            end


            if (opn_valid || rst) res_valid <= 0;
        end
    end

endmodule

