    reg [7:0] b_reg;


    reg [15:0] temp_rem;
    reg [15:0] temp_quot;
    integer i;


    always @ (A or B) begin
        a_reg = A;
        b_reg = B;
    end


    always @ (a_reg or b_reg) begin
        temp_rem = 16'd0;
        temp_quot = 16'd0;

        for (i = 15;
 i >= 0;
 i = i - 1) begin

            temp_rem = {temp_rem[14:0], a_reg[i]};

            if (temp_rem >= {8'd0, b_reg}) begin
                temp_rem = temp_rem - {8'd0, b_reg};
                temp_quot[i] = 1'b1;
            end else begin
                temp_quot[i] = 1'b0;
            end
        end
    end

    assign result = temp_quot;
    assign odd = temp_rem;

