                done_r <= 1'd1;
            else if (i == 17)
                done_r <= 1'd0;


            if (start) begin
                if (i == 0) begin
                    areg <= ain;
                    breg <= bin;
                    yout_r <= 32'd0;
                end
                else if (i <= 16) begin
                    if (areg[i-1])
                        yout_r <= yout_r + ( {16'd0, breg} << (i - 1) );
