module fixed_point_adder #(
    parameter Q = 8,
    parameter N = 16
)(
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

    reg [N-1:0] res;
    reg res_sign;
    reg [N-1:0] sum_abs;
    reg [N-1:0] abs_a;
    reg [N-1:0] abs_b;


    wire sign_a = a[N-1];
    wire sign_b = b[N-1];

    assign abs_a = sign_a ? (~a + 1) : a;
    assign abs_b = sign_b ? (~b + 1) : b;


    wire same_sign = (sign_a == sign_b);

    always @* begin
        if (same_sign) begin
            sum_abs = abs_a + abs_b;
            res_sign = sign_a;
        end
        else begin
            if (abs_a > abs_b) begin
                sum_abs = abs_a - abs_b;
                res_sign = sign_a;
            end
            else if (abs_b > abs_a) begin
                sum_abs = abs_b - abs_a;
                res_sign = sign_b;
            end
            else begin
                sum_abs = 0;
                res_sign = 0;
            end
        end


        res = {res_sign, sum_abs[N-2:0]};
    end

    assign c = res;

endmodule

