reg [PTR_WIDTH-1:0] wgray, rgray;


reg [PTR_WIDTH-1:0] rgray_sync1, rgray_sync2;
reg [PTR_WIDTH-1:0] wgray_sync1, wgray_sync2;


wire [PTR_WIDTH-1:0] rptr_bin_sync = gray2bin(rgray_sync2);
wire [PTR_WIDTH-1:0] wptr_bin_sync = gray2bin(wgray_sync2);


wire wen = winc && !wfull;
wire ren = rinc && !rempty;


reg [WIDTH-1:0] ram [0:DEPTH-1];


wire [ADDR_WIDTH-1:0] waddr = wptr_bin[ADDR_WIDTH-1:0];
wire [ADDR_WIDTH-1:0] raddr = rptr_bin[ADDR_WIDTH-1:0];


