    if (ren) rdata_reg <= ram[raddr];
end
assign rdata = rdata_reg;


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        wptr_bin <= 0;
        wgray <= 0;
    end else begin
        if (wen) begin
            wptr_bin <= wptr_bin + 1;
            wgray <= bin2gray(wptr_bin + 1);
        end else begin
            wgray <= bin2gray(wptr_bin);
        end
    end
end


always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        rptr_bin <= 0;
        rgray <= 0;
    end else begin
        if (ren) begin
            rptr_bin <= rptr_bin + 1;
            rgray <= bin2gray(rptr_bin + 1);
        end else begin
            rgray <= bin2gray(rptr_bin);
        end
    end
end


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        {rgray_sync2, rgray_sync1} <= 0;
