             (wptr_bin[PTR_WIDTH-2:0] == rptr_bin_sync[PTR_WIDTH-2:0]));
    rempty = (rptr_bin == wptr_bin_sync);
end


always @(posedge wclk) begin
    if (wen) ram[waddr] <= wdata;
