module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);

    localparam [1:0] idle     = 2'b00,
                     s1_red   = 2'b01,
                     s2_yellow= 2'b10,
                     s3_green = 2'b11;

    reg [7:0] cnt;
    reg [1:0] state;
    reg p_red, p_yellow, p_green;


    assign clock = cnt;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end else begin
            case (state)
                idle:     state <= s1_red;
                s1_red:   if (cnt == 0) state <= s3_green;
                s3_green: if (cnt == 0) state <= s2_yellow;
                s2_yellow:if (cnt == 0) state <= s1_red;
                default:  state <= idle;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 8'd10;
        end else begin
            if (pass_request && p_green) begin
                if (cnt > 8'd10) cnt <= 8'd10;
            end else begin
                case (state)
                    s1_red:   if (cnt == 0) cnt <= 8'd3;

                    s3_green: if (cnt == 0) cnt <= 8'd60;

                    s2_yellow:if (cnt == 0) cnt <= 8'd5;

                    default:  if (cnt > 0) cnt <= cnt - 1;
                endcase
            end
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            {p_red, p_yellow, p_green} <= 3'b000;
        end else begin
            case (state)
                s1_red:    {p_red, p_yellow, p_green} <= 3'b100;
                s3_green:  {p_red, p_yellow, p_green} <= 3'b001;
                s2_yellow: {p_red, p_yellow, p_green} <= 3'b010;
                default:   {p_red, p_yellow, p_green} <= 3'b000;
            endcase
        end
    end


    assign red    = p_red;
    assign yellow = p_yellow;
    assign green  = p_green;

endmodule

