module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output reg carry,
    output negative,
    output reg overflow,
    output reg flag
);


parameter ADD  = 6'b100000;
parameter ADDU = 6'b100001;
parameter SUB  = 6'b100010;
parameter SUBU = 6'b100011;
parameter AND  = 6'b100100;
parameter OR   = 6'b100101;
parameter XOR  = 6'b100110;
parameter NOR  = 6'b100111;
parameter SLT  = 6'b101010;
parameter SLTU = 6'b101011;
parameter SLL  = 6'b000000;
parameter SRL  = 6'b000010;
parameter SRA  = 6'b000011;
parameter SLLV = 6'b000100;
parameter SRLV = 6'b000110;
parameter SRAV = 6'b000111;
parameter LUI  = 6'b001111;

reg [32:0] temp_add, temp_sub;
reg [31:0] slt_result;

assign zero = (r == 0);
assign negative = r[31];

always @* begin
    r = 32'bz;
    carry = 0;
    overflow = 0;
    flag = 1'bz;

    case (aluc)
        ADD: begin
            temp_add = {1'b0, a} + {1'b0, b};
            r = temp_add[31:0];
            carry = temp_add[32];
            overflow = (a[31] == b[31]) && (r[31] != a[31]);
        end

        ADDU: begin
            temp_add = {1'b0, a} + {1'b0, b};
            r = temp_add[31:0];
            carry = temp_add[32];
        end

        SUB: begin
            temp_sub = {1'b0, a} - {1'b0, b};
            r = temp_sub[31:0];
            carry = ~temp_sub[32];
            overflow = (a[31] != b[31]) && (r[31] != a[31]);
        end

        SUBU: begin
            temp_sub = {1'b0, a} - {1'b0, b};
            r = temp_sub[31:0];
            carry = ~temp_sub[32];
        end

        AND: r = a & b;

        OR: r = a | b;

        XOR: r = a ^ b;

        NOR: r = ~(a | b);

        SLT: begin
            slt_result = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
            r = slt_result;
        end

        SLTU: begin
            slt_result = (a < b) ? 32'd1 : 32'd0;
            r = slt_result;
        end

        SLL: r = b << a[4:0];

        SRL: r = b >> a[4:0];

        SRA: r = $signed(b) >>> a[4:0];

        SLLV: r = b << a[4:0];

        SRLV: r = b >> a[4:0];

        SRAV: r = $signed(b) >>> a[4:0];

        LUI: r = {b[15:0], 16'b0};

        default: r = 32'bz;
    endcase

    if (aluc == SLT || aluc == SLTU)
        flag = 1'b1;
    else
        flag = 1'bz;
end

endmodule

