        if (rst) begin
            res_valid <= 0;
            start <= 0;
            cnt <= 0;
            SR <= 0;
            original_sign_dividend <= 0;
            original_sign_divisor <= 0;
            NEG_DIVISOR <= 0;
            quotient <= 0;
            remainder <= 0;
            remainder_adj <= 0;
            quotient_adj <= 0;
        end else begin
            if (opn_valid && !res_valid) begin

                if (sign) begin
                    original_sign_dividend <= dividend[7];
                    absolute_dividend <= dividend[7] ? -dividend : dividend;
                    original_sign_divisor <= divisor[7];
                    absolute_divisor <= divisor[7] ? -divisor : divisor;
