                        quotient_adj <= (original_sign_dividend ^ original_sign_divisor) ? -quotient : quotient;
                        remainder_adj <= original_sign_dividend ? -remainder : remainder;
                    end else begin
                        quotient_adj <= quotient;
                        remainder_adj <= remainder;
                    end
                    result <= {remainder_adj, quotient_adj};
