module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output [15:0] result,
    output [15:0] odd
);

    reg [15:0] a_reg;
    reg [7:0] b_reg;
    reg [15:0] quotient;
    reg [15:0] remainder;
    reg [15:0] temp_remainder;
    integer i;


    always @* begin
        a_reg = A;
        b_reg = B;
    end


    always @* begin
        quotient = 16'b0;
        remainder = 16'b0;
        temp_remainder = 16'b0;

        for (i = 15;
 i >= 0;
 i = i - 1) begin
            temp_remainder = (temp_remainder << 1) | (a_reg[i]);
            if (temp_remainder >= b_reg) begin
                temp_remainder = temp_remainder - b_reg;
                quotient[i] = 1;
            end else begin
                quotient[i] = 0;
            end
        end

        remainder = temp_remainder;
    end

    assign result = quotient;
    assign odd = remainder;

endmodule

