            sum_reg <= 10'd0;
            count_reg <= 2'd0;
            valid_out <= 1'b0;
            data_out <= 10'd0;
        end else begin
            valid_out <= 1'b0;

            if (valid_in) begin
                sum_reg <= sum_reg + data_in;
