                    data_out <= sum_reg + data_in;
                    valid_out <= 1'b1;
                    sum_reg <= 10'd0;
                    count_reg <= 2'd0;
                end else begin
                    count_reg <= count_reg + 1;
                end
            end
        end
    end

endmodule

