module fsm (
    input IN,
    input CLK,
    input RST,
    output reg MATCH
);

    parameter S0 = 3'd0, S1 = 3'd1, S2 = 3'd2, S3 = 3'd3, S4 = 3'd4;
    reg [2:0] current_state, next_state;

    always @* begin
        next_state = current_state;
        MATCH = 1'b0;

        if (RST) begin
            MATCH = 1'b0;
        end
        else begin
            case (current_state)
                S0: begin
                    next_state = IN ? S1 : S0;
                end
                S1: begin
                    next_state = IN ? S1 : S2;
                end
                S2: begin
                    next_state = IN ? S1 : S3;
                end
                S3: begin
                    next_state = IN ? S4 : S0;
                end
                S4: begin
                    if (IN) begin
                        MATCH = 1'b1;
                        next_state = S1;
                    end else begin
                        next_state = S0;
                    end
                end
                default: next_state = S0;
            endcase
        end
    end

    always @(posedge CLK) begin
        if (RST) current_state <= S0;
        else current_state <= next_state;
    end

endmodule

