wire [PTR_WIDTH-1:0] wptr_gray = (wptr_bin >> 1) ^ wptr_bin;
wire [PTR_WIDTH-1:0] rptr_gray = (rptr_bin >> 1) ^ rptr_bin;


reg [PTR_WIDTH-1:0] rptr_gray_sync1, rptr_gray_sync2;

reg [PTR_WIDTH-1:0] wptr_gray_sync1, wptr_gray_sync2;


function [PTR_WIDTH-1:0] gray2bin(input [PTR_WIDTH-1:0] gray);
    integer i;
    begin
        gray2bin[PTR_WIDTH-1] = gray[PTR_WIDTH-1];
        for (i = PTR_WIDTH-2;
 i >= 0;
 i = i - 1)
            gray2bin[i] = gray2bin[i+1] ^ gray[i];
    end
endfunction

wire [PTR_WIDTH-1:0] rptr_bin_sync = gray2bin(rptr_gray_sync2);
wire [PTR_WIDTH-1:0] wptr_bin_sync = gray2bin(wptr_gray_sync2);


wire wen = winc && !wfull;
always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        wptr_bin <= 0;
        {rptr_gray_sync1, rptr_gray_sync2} <= 0;
    end else begin
        if (wen)
            wptr_bin <= wptr_bin + 1;

        rptr_gray_sync1 <= rptr_gray;
        rptr_gray_sync2 <= rptr_gray_sync1;
    end
end


wire ren = rinc && !rempty;
always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        rptr_bin <= 0;
        {wptr_gray_sync1, wptr_gray_sync2} <= 0;
    end else begin
        if (ren)
            rptr_bin <= rptr_bin + 1;

        wptr_gray_sync1 <= wptr_gray;
        wptr_gray_sync2 <= wptr_gray_sync1;
    end
end


wire full_cond = (wptr_bin - rptr_bin_sync) == DEPTH;
wire empty_cond = (wptr_bin_sync == rptr_bin);

always @(*) begin
    wfull = full_cond;
    rempty = empty_cond;
end


wire [ADDR_WIDTH-1:0] waddr = wptr_bin[ADDR_WIDTH-1:0];
wire [ADDR_WIDTH-1:0] raddr = rptr_bin[ADDR_WIDTH-1:0];

