module LIFObuffer (
    input [3:0] dataIn,
    input RW,
    input EN,
    input Rst,
    input Clk,
    output EMPTY,
    output FULL,
    output reg [3:0] dataOut
);

    reg [3:0] stack_mem [0:3];
    reg [2:0] stack_ptr;
    integer i;


    assign EMPTY = (stack_ptr == 3'd4);
    assign FULL = (stack_ptr == 3'd0);

    always @(posedge Clk) begin
        if (Rst) begin

            for (i = 0;
 i < 4;
 i = i + 1) begin
                stack_mem[i] <= 4'b0;
            end
            stack_ptr <= 3'd4;
            dataOut <= 4'b0;
        end
        else if (EN) begin
            if (!RW) begin 
                if (!FULL) begin
                    stack_mem[stack_ptr - 1] <= dataIn;
                    stack_ptr <= stack_ptr - 1;
                end
            end
            else begin 
                if (!EMPTY) begin
                    dataOut <= stack_mem[stack_ptr - 1];
                    stack_mem[stack_ptr - 1] <= 4'b0;

                    stack_ptr <= stack_ptr + 1;
                end
            end
        end
    end

endmodule

