module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);


    parameter idle = 2'd0;
    parameter s1_red = 2'd1;
    parameter s2_yellow = 2'd2;
    parameter s3_green = 2'd3;

    reg [1:0] state;
    reg [1:0] next_state;


    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;


    assign clock = cnt;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end else begin
            state <= next_state;
        end
    end


    always @(*) begin
        case (state)
            idle: next_state = s1_red;
            s1_red: next_state = (cnt == 0) ? s3_green : s1_red;
            s3_green: next_state = (cnt == 0) ? s2_yellow : s3_green;
            s2_yellow: next_state = (cnt == 0) ? s1_red : s2_yellow;
            default: next_state = idle;
        endcase
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 10;
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
        end else begin

            if (pass_request && p_green && (cnt > 10))
                cnt <= 10;
            else begin
                case (state)
                    idle: cnt <= 10;
                    s1_red: begin
                        if (cnt == 0) begin
                            cnt <= 60;
                        end else begin
                            cnt <= cnt - 1;
                        end
                    end
                    s3_green: begin
                        if (cnt == 0) begin
                            cnt <= 5;
                        end else begin
                            cnt <= cnt - 1;
                        end
                    end
                    s2_yellow: begin
                        if (cnt == 0) begin
                            cnt <= 10;
                        end else begin
                            cnt <= cnt - 1;
                        end
                    end
                    default: cnt <= 10;
                endcase
            end


            case (next_state)
                s1_red: p_red <= 1;
                s2_yellow: p_yellow <= 1;
                s3_green: p_green <= 1;
                default: begin
                    p_red <= 0;
                    p_yellow <= 0;
                    p_green <= 0;
                end
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            red <= 0;
            yellow <= 0;
            green <= 0;
        end else begin
            red <= p_red;
            yellow <= p_yellow;
            green <= p_green;
        end
    end

endmodule

