module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output carry,
    output negative,
    output overflow,
    output flag
);

parameter ADD  = 6'b100000;
parameter ADDU = 6'b100001;
parameter SUB  = 6'b100010;
parameter SUBU = 6'b100011;
parameter AND  = 6'b100100;
parameter OR   = 6'b100101;
parameter XOR  = 6'b100110;
parameter NOR  = 6'b100111;
parameter SLT  = 6'b101010;
parameter SLTU = 6'b101011;
parameter SLL  = 6'b000000;
parameter SRL  = 6'b000010;
parameter SRA  = 6'b000011;
parameter SLLV = 6'b000100;
parameter SRLV = 6'b000110;
parameter SRAV = 6'b000111;
parameter LUI  = 6'b001111;

reg [31:0] res_temp;
reg carry_temp;
reg overflow_temp;
reg negative_temp;
reg flag_temp;

wire slt_flag = ($signed(a) < $signed(b));
wire sltu_flag = (a < b);

assign flag = ((aluc == SLT) || (aluc == SLTU)) ? ((aluc == SLT) ? slt_flag : sltu_flag) : 1'bz;

assign zero = (r == 32'd0);
assign carry = carry_temp;
assign negative = negative_temp;
assign overflow = overflow_temp;

always @* begin
    carry_temp = 1'b0;
    overflow_temp = 1'b0;
    negative_temp = 1'b0;
    res_temp = 32'd0;

    case (aluc)
        ADD: begin
            {carry_temp, res_temp} = {1'b0, a} + {1'b0, b};
            overflow_temp = ( (a[31] == b[31]) && (res_temp[31] != a[31]) );
        end
        ADDU: begin
            res_temp = a + b;
        end
        SUB: begin
            {carry_temp, res_temp} = {1'b0, a} - {1'b0, b};
            overflow_temp = ( (a[31] != b[31]) && (res_temp[31] != a[31]) );
        end
        SUBU: begin
            res_temp = a - b;
        end
        AND: begin
            res_temp = a & b;
        end
        OR: begin
            res_temp = a | b;
        end
        XOR: begin
            res_temp = a ^ b;
        end
        NOR: begin
            res_temp = ~(a | b);
        end
        SLT: begin
            res_temp = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
        end
        SLTU: begin
            res_temp = (a < b) ? 32'd1 : 32'd0;
        end
        SLL: begin
            res_temp = b << a[4:0];
        end
        SRL: begin
            res_temp = b >> a[4:0];
        end
        SRA: begin
            res_temp = $signed(b) >>> a[4:0];
        end
        SLLV: begin
            res_temp = b << a[4:0];
        end
        SRLV: begin
            res_temp = b >> a[4:0];
        end
        SRAV: begin
            res_temp = $signed(b) >>> a[4:0];
        end
        LUI: begin
            res_temp = {a[31:16], 16'd0};
        end
        default: begin
            res_temp = 32'bz;
        end
    endcase
end

assign r = res_temp;
assign negative_temp = res_temp[31];

endmodule

