module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg processing;
    reg [7:0] quotient, remainder;
    reg [7:0] divisor_abs, NEG_DIVISOR;
    reg [3:0] cnt;
    reg [7:0] dividend_abs;
    reg sign_reg;
    reg remainder_sign, quotient_sign;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            processing <= 0;
            cnt <= 0;
            quotient <= 0;
            remainder <= 0;
            dividend_abs <= 0;
            divisor_abs <= 0;
            NEG_DIVISOR <= 0;
            remainder_sign <= 0;
            quotient_sign <= 0;
            sign_reg <= 0;
        end else begin
            if (opn_valid && !processing) begin

                sign_reg <= sign;
                dividend_abs <= sign ? (dividend[7] ? -dividend : dividend) : dividend;
                divisor_abs <= sign ? (divisor[7] ? -divisor : divisor) : divisor;
                NEG_DIVISOR <= -divisor_abs;

                remainder <= { (sign ? (dividend[7] ? -dividend : dividend) : dividend), 1'b0 };
                quotient <= 0;
                cnt <= 1;
                processing <= 1;
                remainder_sign <= sign && dividend[7];
                quotient_sign <= (sign && (dividend[7] ^ divisor[7])) ? 1 : 0;
            end else if (processing && cnt <= 8) begin
                if (remainder >= {1'b0, divisor_abs}) begin
                    remainder <= remainder - {1'b0, divisor_abs};
                    quotient <= {quotient[6:0], 1'b1};
                end else begin
                    quotient <= {quotient[6:0], 1'b0};
                end
                remainder <= remainder << 1;
                cnt <= cnt + 1;
            end else if (processing && cnt == 9) begin
                processing <= 0;
                res_valid <= 1;

                if (sign_reg) begin
                    quotient <= quotient_sign ? -quotient : quotient;
                    remainder <= remainder_sign ? -remainder : remainder;
                end
                result <= { remainder, quotient };
            end

            if (res_valid) begin
                res_valid <= 0;
            end
        end
    end

endmodule

