module cla_16bit(
    input [16:1] A,
    input [16:1] B,
    input C0,
    output [16:1] S,
    output C16
);

    wire [16:1] G, P;
    wire [17:1] C;

    assign C[1] = C0;

    generate
        genvar i;
        for (i = 1;
 i <= 16;
 i = i + 1) begin: cla_loop
            assign G[i] = A[i] & B[i];
            assign P[i] = A[i] ^ B[i];
            assign C[i+1] = G[i] | (P[i] & C[i]);
            assign S[i] = P[i] ^ C[i];
        end
    endgenerate

    assign C16 = C[17];

