module fixed_point_adder #(
    parameter Q = 8,
    parameter N = 16
)(
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

    reg [N-1:0] res;
    wire sign_a = a[N-1];
    wire sign_b = b[N-1];


    wire [N-1:0] abs_a = sign_a ? (~a + 1) : a;
    wire [N-1:0] abs_b = sign_b ? (~b + 1) : b;


    wire same_sign = (sign_a == sign_b);


    reg [N-1:0] res_mag;
    reg res_sign;

    always @* begin
        if (same_sign) begin
            res_mag = abs_a + abs_b;
            res_sign = sign_a;
        end else begin
            if (abs_a > abs_b) begin
                res_mag = abs_a - abs_b;
                res_sign = sign_a;
            end else if (abs_b > abs_a) begin
                res_mag = abs_b - abs_a;
                res_sign = sign_b;
            end else begin 
                res_mag = 0;
                res_sign = 0;

            end
        end
    end


    always @* begin
        if (res_sign)
            res = (~res_mag) + 1;
        else
            res = res_mag;
    end

    assign c = res;

endmodule

