localparam STAGE_INPUT = 3'd0;
localparam STAGE_SPECIAL = 3'd1;
localparam STAGE_MULT = 3'd2;
localparam STAGE_NORM = 3'd3;
localparam STAGE_ROUND = 3'd4;
localparam STAGE_FINAL = 3'd5;


always @(posedge clk) begin
    if (rst) begin
        counter <= STAGE_INPUT;
        z <= 32'h0;
    end else begin
        case (counter)
            STAGE_INPUT: begin
                a_sign <= a[31];
                b_sign <= b[31];
                a_exponent <= a[30:23];
                b_exponent <= b[30:23];
                a_mantissa <= a[22:0];
                b_mantissa <= b[22:0];
                z_sign <= a[31] ^ b[31];
                counter <= STAGE_SPECIAL;
            end

            STAGE_SPECIAL: begin

                if ((a_exponent == 8'hFF && a_mantissa != 0) || 
                    (b_exponent == 8'hFF && b_mantissa != 0)) begin
                    z <= {1'b0, 8'hFF, 23'h1};
                    is_nan <= 1;
                    counter <= STAGE_FINAL;
                end

                else if ((a_exponent == 8'hFF && a_mantissa == 0 && 
                         (b_exponent == 0 || (b_exponent == 8'hFF && b_mantissa == 0))) ||
                         (b_exponent == 8'hFF && b_mantissa == 0 && 
                         (a_exponent == 0 || (a_exponent == 8'hFF && a_mantissa == 0)))) begin
                    z <= {1'b0, 8'hFF, 23'h0};
                    is_nan <= 1;
                    counter <= STAGE_FINAL;
                end

                else if (a_exponent == 0 && a_mantissa == 0) begin
                    z <= {z_sign, 31'h0};
                    counter <= STAGE_FINAL;
                end
                else if (b_exponent == 0 && b_mantissa == 0) begin
                    z <= {z_sign, 31'h0};
                    counter <= STAGE_FINAL;
                end

                else if (a_exponent == 8'hFF || b_exponent == 8'hFF) begin
                    z <= {z_sign, 8'hFF, 23'h0};
                    is_inf <= 1;
                    counter <= STAGE_FINAL;
                end
                else begin

                    product <= {1'b1, a_mantissa} * {1'b1, b_mantissa};
                    sum_exp <= {1'b0, a_exponent} + {1'b0, b_exponent} - 9'd127;
                    counter <= STAGE_NORM;
                end
            end

            STAGE_NORM: begin

                if (product[47]) begin
                    sum_exp <= sum_exp + 1;
                    product <= product >> 1;
                end

                product <= product << (48 - sum_exp[6:0]);
                counter <= STAGE_ROUND;
            end

            STAGE_ROUND: begin




                if (sum_exp > 254) z <= {z_sign, 8'hFF, 23'h0};
                else if (sum_exp < 1) z <= {z_sign, 8'h0, 23'h0};
                else z <= {z_sign, sum_exp[7:0], product[46:24]};
                counter <= STAGE_FINAL;
            end

            STAGE_FINAL: begin
                z <= z;
                counter <= STAGE_INPUT;
            end

            default: counter <= STAGE_INPUT;
        endcase
    end
end

