module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid = 0,
    output reg [15:0] result
);

    reg [7:0] saved_dividend, saved_divisor;
    reg processing;
    reg [3:0] cnt;
    reg sign_reg;
    reg [15:0] SR;
    reg [7:0] abs_dividend, abs_divisor;
    reg quo_neg, rem_neg;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            processing <= 0;
            cnt <= 0;
            saved_dividend <= 0;
            saved_divisor <= 0;
            SR <= 0;
            sign_reg <= 0;
            abs_dividend <= 0;
            abs_divisor <= 0;
            quo_neg <= 0;
            rem_neg <= 0;
            result <= 0;
        end else begin
            if (opn_valid && !res_valid && !processing) begin

                saved_dividend <= sign ? (~dividend + 1) : dividend;
                saved_divisor <= sign ? (~divisor + 1) : divisor;
                sign_reg <= sign;
                abs_dividend <= (dividend[7] & sign) ? (~dividend + 1) : dividend;
                abs_divisor <= (divisor[7] & sign) ? (~divisor + 1) : divisor;
                rem_neg <= dividend[7];
                quo_neg <= (dividend[7] ^ divisor[7]) & sign;


                SR <= { (dividend[7] & sign) ? (~dividend + 1) : dividend, 1'b0 } << 8;
                cnt <= 0;
                processing <= 1;
            end

            if (processing) begin
                if (cnt < 8) begin

                    if (SR[15:8] >= abs_divisor) begin
                        SR[15:8] <= SR[15:8] - abs_divisor;
                        SR <= { SR[15:8] - abs_divisor, SR[7:1], 1'b1 };
                    end else begin
                        SR <= { SR[15:8], SR[7:1], 1'b0 };
                    end
                    cnt <= cnt + 1;
                end else begin
                    processing <= 0;
                    res_valid <= 1;

                    if (sign_reg) begin
                        result[15:8] <= rem_neg ? (~SR[15:8] + 1) : SR[15:8];
                        result[7:0] <= quo_neg ? (~SR[7:0] + 1) : SR[7:0];
                    end else begin
                        result <= SR;
                    end
                end
            end

            if (res_valid && !opn_valid) begin
                res_valid <= 0;
            end
        end
    end
endmodule

