    reg [2:0] count;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sum_reg <= 10'd0;
            count <= 3'd0;
            valid_out <= 1'b0;
            data_out <= 10'd0;
        end else begin
            valid_out <= 1'b0;

            if (valid_in) begin
                sum_reg <= sum_reg + data_in;

                if (count == 3'd4) begin
                    valid_out <= 1'b1;
                    data_out <= sum_reg + data_in;
                    sum_reg <= 10'd0;
                    count <= 3'd0;
                end else begin
                    count <= count + 3'd1;
                end
            end
        end
    end

endmodule

