module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exp, b_exp, z_exp;
    reg [22:0] a_man, b_man;
    reg [49:0] product;
    reg guard, round, sticky;
    reg [47:0] normalized_mantissa;
    reg [7:0] exponent_sum;
    reg a_zero, b_zero, a_inf, b_inf, a_nan, b_nan;

    localparam IDLE = 0, PROCESS = 1, NORMALIZE = 2, ROUND = 3, FINAL = 4;


    wire a_is_nan = (a_exp == 8'hFF) && (a_man != 0);
    wire b_is_nan = (b_exp == 8'hFF) && (b_man != 0);
    wire a_is_inf = (a_exp == 8'hFF) && (a_man == 0);
    wire b_is_inf = (b_exp == 8'hFF) && (b_man == 0);
    wire a_is_zero = (a_exp == 0) && (a_man == 0);
    wire b_is_zero = (b_exp == 0) && (b_man == 0);


    wire [23:0] a_man_leading = (a_exp != 0) ? {1'b1, a_man} : {1'b0, a_man};
    wire [23:0] b_man_leading = (b_exp != 0) ? {1'b1, b_man} : {1'b0, b_man};

    always @(posedge clk) begin
        if (rst) begin
            counter <= IDLE;
            z <= 0;
            a_sign <= 0;
 b_sign <= 0;
            z_sign <= 0;
 z_exp <= 0;
        end else begin
            case (counter)
                IDLE: begin
                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exp <= a[30:23];
                    b_exp <= b[30:23];
                    a_man <= a[22:0];
                    b_man <= b[22:0];
                    counter <= PROCESS;
                end

                PROCESS: begin
                    a_zero <= a_is_zero;
                    b_zero <= b_is_zero;
                    a_inf <= a_is_inf;
                    b_inf <= b_is_inf;
                    a_nan <= a_is_nan;
                    b_nan <= b_is_nan;

                    if (a_nan || b_nan) begin
                        z <= {1'b0, 8'hFF, 23'h1};

                        counter <= IDLE;
                    end else if (a_zero || b_zero) begin
                        z <= {a_sign ^ b_sign, 8'h0, 23'h0};
                        counter <= IDLE;
                    end else if (a_inf || b_inf) begin
                        if ((a_zero && b_inf) || (b_zero && a_inf)) begin
                            z <= {1'b0, 8'hFF, 23'h1};

                        end else begin
                            z <= {a_sign ^ b_sign, 8'hFF, 23'h0};

                        end
                        counter <= IDLE;
                    end else begin
                        product <= a_man_leading * b_man_leading;
                        exponent_sum <= a_exp + b_exp - 8'd127;
                        counter <= NORMALIZE;
                    end
                end

                NORMALIZE: begin
                    if (product[48]) begin
                        normalized_mantissa <= product[48:25];
                        exponent_sum <= exponent_sum + 1;
                    end else begin
                        normalized_mantissa <= product[47:24];
                    end
                    counter <= ROUND;
                end

                ROUND: begin

                    guard <= product[23];
                    round <= product[22];
                    sticky <= |product[21:0];

                    if (guard && (round | sticky)) begin
                        if (normalized_mantissa[0])
                            normalized_mantissa <= normalized_mantissa + 1;

                        if (normalized_mantissa[47])
                            exponent_sum <= exponent_sum + 1;
                    end
                    counter <= FINAL;
                end

                FINAL: begin
                    if (exponent_sum >= 255) begin 
                        z <= {z_sign, 8'hFF, 23'h0};
                    end else if (exponent_sum == 0) begin 
                        z <= {z_sign, 8'h0, 23'h0};
                    end else begin
                        z <= {z_sign, exponent_sum, normalized_mantissa[46:24]};
                    end
                    counter <= IDLE;
                end
            endcase
        end
    end

