module fsm (
    input IN,
    input CLK,
    input RST,
    output reg MATCH
);


    reg [2:0] state, next_state;
    parameter S0 = 3'd0, S1 = 3'd1, S2 = 3'd2, S3 = 3'd3, S4 = 3'd4;


    always @(posedge CLK or posedge RST) begin
        if (RST)
            state <= S0;
        else
            state <= next_state;
    end


    always @(*) begin
        case (state)
            S0: begin
                MATCH = 0;
                next_state = IN ? S1 : S0;
            end
            S1: begin
                MATCH = 0;
                next_state = IN ? S1 : S2;
            end
            S2: begin
                MATCH = 0;
                next_state = IN ? S1 : S3;
            end
            S3: begin
                MATCH = 0;
                next_state = IN ? S4 : S1;
            end
            S4: begin
                MATCH = IN ? 1 : 0;
                next_state = IN ? S1 : S0;
            end
            default: begin
                MATCH = 0;
                next_state = S0;
            end
        endcase
    end

endmodule

