module asyn_fifo #(
  parameter WIDTH = 8,
  parameter DEPTH = 16
) (
  input wclk,
  input wrstn,
  input winc,
  input [WIDTH-1:0] wdata,
  output wfull,
  output rempty,
  input rclk,
  input rrstn,
  input rinc,
  output [WIDTH-1:0] rdata
);

  localparam ADDR_WIDTH = $clog2(DEPTH);
  localparam PTR_WIDTH = ADDR_WIDTH + 1;


  reg [PTR_WIDTH-1:0] wbin, rbin;

  reg [PTR_WIDTH-1:0] wgray, rgray;

  reg [PTR_WIDTH-1:0] wgray_sync_rclk1, wgray_sync_rclk2;
  reg [PTR_WIDTH-1:0] rgray_sync_wclk1, rgray_sync_wclk2;


  wire wen, rene;


  wire full;
  wire empty;


  function [PTR_WIDTH-1:0] bin2gray(input [PTR_WIDTH-1:0] bin);
    bin2gray = (bin >> 1) ^ bin;
  endfunction


  always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
      wgray <= 0;
    end else begin
      wgray <= bin2gray(wbin);
    end
  end

  always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
      rgray <= 0;
    end else begin
      rgray <= bin2gray(rbin);
    end
  end


  always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
      wgray_sync_rclk1 <= 0;
      wgray_sync_rclk2 <= 0;
    end else begin
      wgray_sync_rclk1 <= wgray;
      wgray_sync_rclk2 <= wgray_sync_rclk1;
    end
  end


  always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
      rgray_sync_wclk1 <= 0;
      rgray_sync_wclk2 <= 0;
    end else begin
      rgray_sync_wclk1 <= rgray;
      rgray_sync_wclk2 <= rgray_sync_wclk1;
    end
  end


  always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
      wbin <= 0;
    end else if (wen) begin
      wbin <= wbin + 1;
    end
  end

  always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
      rbin <= 0;
    end else if (rene) begin
      rbin <= rbin + 1;
    end
  end


  assign full = ((wgray[PTR_WIDTH-1 : PTR_WIDTH-2] != rgray_sync_wclk2[PTR_WIDTH-1 : PTR_WIDTH-2]) &&
                 (wgray[ADDR_WIDTH-1 :0] == rgray_sync_wclk2[ADDR_WIDTH-1 :0]));

  assign empty = (rgray == wgray_sync_rclk2);


  assign wen = winc && !wfull;
  assign rene = rinc && !rempty;


  assign wfull = full;
  assign rempty = empty;


  dual_port_RAM #(
    .WIDTH(WIDTH),
    .DEPTH(DEPTH),
    .ADDR_WIDTH(ADDR_WIDTH)
  ) ram (
    .wclk(wclk),
    .wenc(wen),
    .waddr(wbin[ADDR_WIDTH-1:0]),
    .wdata(wdata),
    .rclk(rclk),
    .renc(rene),
    .raddr(rbin[ADDR_WIDTH-1:0]),
    .rdata(rdata)
  );

endmodule

module dual_port_RAM #(
