module LIFObuffer (
    input [3:0] dataIn,
    input RW,
    input EN,
    input Rst,
    input Clk,
    output EMPTY,
    output FULL,
    output [3:0] dataOut
);

    reg [3:0] stack_mem [0:3];
    reg [2:0] SP;

    reg [3:0] dataOut_reg;

    assign EMPTY = (SP == 4);
    assign FULL = (SP == 0);
    assign dataOut = dataOut_reg;

    integer i;

    always @(posedge Clk) begin
        if (Rst) begin
            SP <= 4;
            for (i = 0;
 i < 4;
 i = i + 1)
                stack_mem[i] <= 0;
            dataOut_reg <= 0;
        end else if (EN) begin
            if (!RW) begin 
                if (!FULL) begin
                    stack_mem[SP - 1] <= dataIn;
                    SP <= SP - 1;
                end
            end else begin 
                if (!EMPTY) begin
                    dataOut_reg <= stack_mem[SP];
                    stack_mem[SP] <= 0;
                    SP <= SP + 1;
                end
            end
        end
    end

endmodule

