module alu (
    input [31:0] a, b,
    input [5:0] aluc,
    output reg [31:0] r,
    output reg zero,
    output reg carry,
    output reg negative,
    output reg overflow,
    output reg flag
);


    parameter ADD  = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB  = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND  = 6'b100100;
    parameter OR   = 6'b100101;
    parameter XOR  = 6'b100110;
    parameter NOR  = 6'b100111;
    parameter SLT  = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL  = 6'b000000;
    parameter SRL  = 6'b000010;
    parameter SRA  = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI  = 6'b001111;

    reg [31:0] res;
    reg temp_carry, temp_overflow;

    always @* begin
        res = 32'd0;
        temp_carry = 1'b0;
        temp_overflow = 1'b0;
        flag = 1'bz;
        zero = 1'b0;
        carry = 1'b0;
        negative = 1'b0;
        overflow = 1'b0;

        case (aluc)
            ADD: begin
                {temp_carry, res} = {1'b0, a} + {1'b0, b};
                overflow = ( (a[31] == b[31]) && (res[31] != a[31]) );
            end
            ADDU: begin
                {temp_carry, res} = {1'b0, a} + {1'b0, b};
            end
            SUB: begin
                {temp_carry, res} = {1'b0, a} - {1'b0, b};
                overflow = ( (a[31] != b[31]) && (res[31] != a[31]) );
            end
            SUBU: begin
                {temp_carry, res} = {1'b0, a} - {1'b0, b};
                carry = temp_carry;
            end
            AND: begin
                res = a & b;
            end
            OR: begin
                res = a | b;
            end
            XOR: begin
                res = a ^ b;
            end
            NOR: begin
                res = ~(a | b);
            end
            SLT: begin
                res = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
                flag = ($signed(a) < $signed(b)) ? 1'b1 : 1'bz;
            end
            SLTU: begin
                res = (a < b) ? 32'd1 : 32'd0;
                flag = (a < b) ? 1'b1 : 1'bz;
            end
            SLL: begin
                res = b << a[4:0];
            end
            SRL: begin
                res = b >> a[4:0];
            end
            SRA: begin
                res = $signed(b) >>> a[4:0];
            end
            SLLV: begin
                res = b << a[4:0];
            end
            SRLV: begin
                res = b >> a[4:0];
            end
            SRAV: begin
                res = $signed(b) >>> a[4:0];
            end
            LUI: begin
                res = {a[15:0], 16'b0};
            end
            default: res = 32'bz;
        endcase


        zero = (res == 0);
        negative = res[31];
        r = res;


        if (aluc == SLT || aluc == SLTU) flag = res[0];


        if (aluc == ADD) begin
            carry = temp_carry;
            overflow = ( (a[31] == b[31]) && (res[31] != a[31]) );
        end
        else if (aluc == ADDU) carry = temp_carry;
        else if (aluc == SUB) begin
            carry = ~temp_carry;
            overflow = ( (a[31] != b[31]) && (res[31] != a[31]) );
        end
        else if (aluc == SUBU) begin
            carry = ~temp_carry;
        end
    end
endmodule

