module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output [15:0] result
);

    reg [15:0] SR;
    reg [7:0] abs_divisor;
    reg processing;
    reg [3:0] cnt;
    reg [7:0] quotient;
    reg [7:0] remainder;
    reg remainder_sign;
    reg [7:0] saved_dividend;
    reg [7:0] saved_divisor;
    reg sign_quotient;
    reg signed [15:0] NEG_DIVISOR;

    assign result = {remainder, quotient};

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            processing <= 0;
            cnt <= 0;
            SR <= 0;
            quotient <= 0;
            remainder <= 0;
            remainder_sign <= 0;
            saved_dividend <= 0;
            saved_divisor <= 0;
            sign_quotient <= 0;
            abs_divisor <= 0;
            NEG_DIVISOR <= 0;
        end else begin
            if (opn_valid && !res_valid && !processing) begin

                processing <= 1;
                res_valid <= 0;
                cnt <= 0;
                remainder <= 0;
                quotient <= 0;


                if (sign) begin
                    sign_quotient <= (dividend[7] ^ divisor[7]);
                    remainder_sign <= dividend[7];
                    saved_dividend <= dividend[7] ? (~dividend + 1) : dividend;
                    saved_divisor <= divisor[7] ? (~divisor + 1) : divisor;
                    abs_divisor <= divisor[7] ? (~divisor + 1) : divisor;
                    NEG_DIVISOR <= - (divisor[7] ? (~divisor + 1) : divisor);
                end else begin
                    sign_quotient <= 0;
                    remainder_sign <= 0;
                    saved_dividend <= dividend;
                    saved_divisor <= divisor;
                    abs_divisor <= divisor;
                    NEG_DIVISOR <= -divisor;
                end


                SR <= { (sign && dividend[7]) ? (~dividend + 1) : dividend, 8'b0 } << 1;
            end else if (processing && !res_valid) begin
                if (cnt < 8) begin

                    if (SR[15:8] >= abs_divisor) begin
                        SR[15:8] <= SR[15:8] - abs_divisor;
                        quotient <= {quotient[6:0], 1'b1};
                    end else begin
                        quotient <= {quotient[6:0], 1'b0};
                    end

                    SR <= { SR[14:8], SR[7:0], 1'b0 };
                    cnt <= cnt + 1;
                end else begin

                    processing <= 0;
                    res_valid <= 1;


                    if (sign) begin
                        if (sign_quotient) begin
                            quotient <= ~quotient + 1;
                        end
                        if (remainder_sign && (abs_divisor != 0 || remainder != 0)) begin
                            remainder <= ~remainder + 1;
                        end
                    end
                end
            end
            if (res_valid && !opn_valid) begin
                res_valid <= 0;
            end
        end
    end

endmodule

