module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output [15:0] result,
    output [15:0] odd
);

    reg [15:0] a_reg;
    reg [7:0] b_reg;
    reg [15:0] q;
    reg [15:0] rem;
    integer i;


    always @* begin
        a_reg = A;
        b_reg = B;
    end


    always @* begin
        rem = 16'd0;
        q = 16'd0;

        for (i = 15;
 i >= 0;
 i = i - 1) begin
            rem = (rem << 1) | a_reg[i];
            if (rem >= {8'd0, b_reg}) begin
                rem = rem - {8'd0, b_reg};
                q[i] = 1'b1;
            end else begin
                q[i] = 1'b0;
            end
        end
    end

    assign result = q;
    assign odd = rem;

endmodule

