module fixed_point_subtractor #(
    parameter Q = 4,
    parameter N = 8
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

    reg [N-1:0] res;
    wire same_sign;
    wire sign_a, sign_b;
    reg [N-1:0] mag_a, mag_b;
    reg [N-1:0] diff_mag;
    reg result_sign;

    assign sign_a = a[N-1];
    assign sign_b = b[N-1];
    assign same_sign = (sign_a == sign_b);

    always @* begin
        if (same_sign) begin

            res = a - b;
            res[N-1] = sign_a;



            if (res == 0)
                res[N-1] = 0;
        end else begin

            mag_a = sign_a ? (~a + 1) : a;
            mag_b = sign_b ? (~b + 1) : b;

            if (mag_a > mag_b) begin
                diff_mag = mag_a - mag_b;
                result_sign = sign_a;
            end else if (mag_b > mag_a) begin
                diff_mag = mag_b - mag_a;
                result_sign = sign_b;
            end else begin
                diff_mag = 0;
                result_sign = 0;

            end


            res = {result_sign, diff_mag[N-2:0]};

            if (diff_mag == 0)
                res[N-1] = 0;
        end
    end

    assign c = res;

endmodule

