module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);
    reg [2:0] counter;
    reg a_sign, b_sign;
    reg [7:0] a_exponent, b_exponent;
    reg [22:0] a_mantissa, b_mantissa;
    reg [7:0] z_exponent;
    reg z_sign;
    reg [47:0] product;
    reg [23:0] z_mantissa;
    reg guard, round, sticky;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
        end else begin
            case(counter)

                3'd0: begin
                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= a[22:0];
                    b_mantissa <= b[22:0];
                    counter <= 3'd1;
                end


                3'd1: begin
                    if ((a_exponent == 8'hFF && |a_mantissa) || (b_exponent == 8'hFF && |b_mantissa)) begin
                        z <= 32'h7FC00000;

                    end else if ((a_exponent == 8'hFF && &a_mantissa) && (b_exponent == 0 && &b_mantissa)) begin
                        z <= 32'h7FC00000;

                    end else if ((a_exponent == 0 && &a_mantissa) || (b_exponent == 0 && &b_mantissa)) begin
                        z <= {a_sign ^ b_sign, 31'd0};

                    end else begin
                        counter <= 3'd2;
                    end
                end


                3'd2: begin
                    product <= {1'b1, a_mantissa} * {1'b1, b_mantissa};
                    z_sign <= a_sign ^ b_sign;
                    counter <= 3'd3;
                end


                3'd3: begin
                    if (product[47]) begin
                        product <= product >> 1;
                        z_exponent <= a_exponent + b_exponent - 126;

                    end else begin
                        z_exponent <= a_exponent + b_exponent - 127;
                    end

                    guard <= product[0];
                    round <= product[1];
                    sticky <= |product[46:2];
                    counter <= 3'd4;
                end


                3'd4: begin

                    if (guard && (round || sticky || z_mantissa[0])) begin
                        if (product[47]) begin
                            z_mantissa <= {product[46:2], 1'b0};
                        end else begin
                            z_mantissa <= {product[46:23], 1'b0};
                        end
                        z_exponent <= z_exponent + 1;
                    end else begin
                        if (product[47]) begin
                            z_mantissa <= {product[46:23]};
                        end else begin
                            z_mantissa <= {product[45:23]};
                        end
                    end


                    if (z_exponent > 8'hFE) begin 
                        z <= {z_sign, 8'hFF, 23'd0};
                    end else begin
                        z <= {z_sign, z_exponent, z_mantissa[22:0]};
                    end

                    counter <= 3'd0;
                end
                default: counter <= 0;
            endcase
        end
    end
endmodule

