            bin[ADDR_BITS] = gray[ADDR_BITS];
            for (i = ADDR_BITS-1;
 i >= 0;
 i = i-1)
                bin[i] = bin[i+1] ^ gray[i];
            gray2bin = bin;
        end
    endfunction

    wire [ADDR_BITS:0] rptr_bin_synced = gray2bin(wptr_gray_sync2);
    wire [ADDR_BITS:0] wptr_bin_synced = gray2bin(rptr_gray_sync2);



    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            rptr_gray_sync1 <= 0;
            rptr_gray_sync2 <= 0;
        end else begin
            rptr_gray_sync1 <= rptr_gray;
            rptr_gray_sync2 <= rptr_gray_sync1;
        end
    end


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            wptr_gray_sync1 <= 0;
            wptr_gray_sync2 <= 0;
        end else begin
            wptr_gray_sync1 <= wptr_gray;
            wptr_gray_sync2 <= wptr_gray_sync1;
        end
    end


    assign rempty = (rptr_bin == rptr_bin_synced);
    assign wfull = ((wptr_bin[ADDR_BITS] != rptr_bin_synced[ADDR_BITS]) &&
                   (wptr_bin[ADDR_BITS-1] != rptr_bin_synced[ADDR_BITS-1]) &&
                   (wptr_bin[ADDR_BITS-2:0] == rptr_bin_synced[ADDR_BITS-2:0]));



    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            wptr_bin <= 0;
        end else if (winc && !wfull) begin
            wptr_bin <= wptr_bin + 1;
        end
    end


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            rptr_bin <= 0;
        end else if (rinc && !rempty) begin
            rptr_bin <= rptr_bin + 1;
        end
    end


    dual_port_RAM #(
        .WIDTH(WIDTH),
        .DEPTH(DEPTH)
    ) ram (
        .wclk(wclk),
        .wenc(winc && !wfull),
        .waddr(wptr_bin[ADDR_BITS-1:0]),
        .wdata(wdata),
        .rclk(rclk),
        .renc(rinc && !rempty),
        .raddr(rptr_bin[ADDR_BITS-1:0]),
        .rdata(rdata)
    );

endmodule

module dual_port_RAM #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
)(
    input wclk,
    input wenc,
    input [$clog2(DEPTH)-1:0] waddr,
    input [WIDTH-1:0] wdata,
    input rclk,
    input renc,
    input [$clog2(DEPTH)-1:0] raddr,
    output reg [WIDTH-1:0] rdata
);

    reg [WIDTH-1:0] RAM [0:DEPTH-1];


    always @(posedge wclk) begin
        if (wenc) begin
            RAM[waddr] <= wdata;
        end
    end


    always @(posedge rclk) begin
        if (renc) begin
            rdata <= RAM[raddr];
        end
    end

endmodule

