module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);


parameter idle = 2'b00;
parameter s1_red = 2'b01;
parameter s2_yellow = 2'b10;
parameter s3_green = 2'b11;


reg [1:0] state;
reg [7:0] cnt;
reg p_red, p_yellow, p_green;


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= idle;
    end else begin
        case (state)
            idle:   state <= s1_red;
            s1_red: state <= (cnt == 0) ? s3_green : s1_red;
            s3_green: state <= (cnt == 0) ? s2_yellow : s3_green;
            s2_yellow: state <= (cnt == 0) ? s1_red : s2_yellow;
            default: state <= idle;
        endcase
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cnt <= 10;
    end else begin
        if (pass_request && p_green && cnt > 10)
            cnt <= 10;
        else if (state == idle) begin
            cnt <= 10;
        end else begin
            if (state == s1_red && p_red)
                cnt <= 60;
            else if (state == s2_yellow && p_yellow)
                cnt <= 5;
            else if (state == s3_green && p_green)
                cnt <= 10;
            else if (~p_red && p_red)
                cnt <= 10;
            else if (~p_green && p_green)
                cnt <= 5;
            else if (~p_yellow && p_yellow)
                cnt <= 60;
            else if (cnt != 0)
                cnt <= cnt - 1;
        end
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        p_red <= 0;
        p_yellow <= 0;
        p_green <= 0;
    end else begin
        p_red <= (state == s1_red);
        p_yellow <= (state == s2_yellow);
        p_green <= (state == s3_green);
    end
end

assign clock = cnt;
assign red = p_red;
assign yellow = p_yellow;
assign green = p_green;

endmodule

