module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output [31:0] r,
    output zero,
    output carry,
    output negative,
    output overflow,
    output flag
);

    parameter ADD  = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB  = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND  = 6'b100100;
    parameter OR   = 6'b100101;
    parameter XOR  = 6'b100110;
    parameter NOR  = 6'b100111;
    parameter SLT  = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL  = 6'b000000;
    parameter SRL  = 6'b000010;
    parameter SRA  = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI  = 6'b001111;

    reg [31:0] res;
    reg carry_r, overflow_r, negative_r, zero_r, flag_val;
    reg flag_z;

    assign r = res;
    assign zero = (res == 0);
    assign carry = carry_r;
    assign overflow = overflow_r;
    assign negative = res[31];
    assign flag = (aluc == SLT || aluc == SLTU) ? flag_val : 1'bz;

    always @* begin
        res = 32'b0;
        carry_r = 0;
        overflow_r = 0;
        flag_val = 0;
        case (aluc)
            ADD: begin
                {carry_r, res} = {1'b0, a} + {1'b0, b};
                overflow_r = (a[31] == b[31]) && (res[31] != a[31]);
            end
            ADDU: begin
                res = a + b;
                carry_r = ( (a + b) > 32'hFFFFFFFF ) ? 1 : 0;
            end
            SUB: begin
                {carry_r, res} = {1'b1, a} - {1'b0, b};
                overflow_r = (a[31] != b[31]) && (res[31] != a[31]);
            end
            SUBU: begin
                res = a - b;
                carry_r = (a >= b);
            end
            AND: begin
                res = a & b;
            end
            OR: begin
                res = a | b;
            end
            XOR: begin
                res = a ^ b;
            end
            NOR: begin
                res = ~(a | b);
            end
            SLT: begin
                flag_val = ($signed(a) < $signed(b)) ? 1 : 0;
                res = {31'b0, flag_val};
            end
            SLTU: begin
                flag_val = (a < b) ? 1 : 0;
                res = {31'b0, flag_val};
            end
            SLL: begin
                res = b << a[4:0];
            end
            SRL: begin
                res = b >> a[4:0];
            end
            SRA: begin
                res = $signed(b) >>> a[4:0];
            end
            SLLV: begin
                res = b << a[4:0];
            end
            SRLV: begin
                res = b >> a[4:0];
            end
            SRAV: begin
                res = $signed(b) >>> a[4:0];
            end
            LUI: begin
                res = {a[15:0], 16'b0};
            end
            default: begin
                res = 32'bz;
                carry_r = 0;
                overflow_r = 0;
            end
        endcase
    end
endmodule

