module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid = 0,
    output [15:0] result
);

    reg [7:0] dividend_abs, divisor_abs;
    reg [7:0] divisor_neg;
    reg [8:0] SR;
    reg [3:0] cnt;
    reg start_cnt;
    reg [7:0] quotient;
    reg [7:0] remainder;
    reg [15:0] result_reg;
    reg dividend_sign, divisor_sign;

    assign result = result_reg;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            cnt <= 0;
            start_cnt <= 0;
            SR <= 0;
            quotient <= 0;
            remainder <= 0;
            dividend_abs <= 0;
            divisor_abs <= 0;
            divisor_neg <= 0;
            dividend_sign <= 0;
            divisor_sign <= 0;
            result_reg <= 0;
        end else begin
            if (~res_valid) begin
                if (opn_valid) begin

                    dividend_sign <= sign & dividend[7];
                    divisor_sign <= sign & divisor[7];
                    dividend_abs <= sign ? (dividend[7] ? (~dividend + 1) : dividend) : dividend;
                    divisor_abs <= sign ? (divisor[7] ? (~divisor + 1) : divisor) : divisor;
                    SR <= {dividend_abs, 1'b0};

                    divisor_neg <= ~divisor_abs + 1;

                    cnt <= 0;
                    start_cnt <= 1;
                    quotient <= 0;
                    remainder <= 0;
                end else if (start_cnt) begin
                    if (cnt < 8) begin

                        if (SR >= {divisor_abs, 1'b0}) begin
                            SR <= (SR - {divisor_abs, 1'b0}) << 1 | 1;
                        end else begin
                            SR <= SR << 1;
                        end
                        cnt <= cnt + 1;
                    end else begin

                        remainder <= SR[8:1];
                        quotient <= SR[0];
                        start_cnt <= 0;

                        if (sign) begin

                            if (dividend_sign ^ divisor_sign) quotient <= ~quotient + 1;
                            if (dividend_sign) remainder <= ~remainder + 1;
                        end
                        result_reg <= {remainder, quotient};
                        res_valid <= 1;
                    end
                end
            end else begin

                if (opn_valid) res_valid <= 0;
            end
        end
    end
endmodule

