    input [3:0] B,
    input Cin,
    output [3:0] Sum,
    output Cout
);


    wire [4:0] sum_total;
    assign sum_total = A + B + Cin;


    wire correction_flag;
    assign correction_flag = (sum_total >= 5'd10);


    wire [4:0] sum_corrected;
