module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z = 0
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exp, b_exp, z_exp;
    reg [22:0] a_mant, b_mant;
    reg [23:0] a_mantissa, b_mantissa;
    reg [49:0] product;
    reg guard, round, sticky;
    reg [1:0] shift_needed;


    wire a_is_nan = (a_exp == 8'hff && a_mant != 0);
    wire b_is_nan = (b_exp == 8'hff && b_mant != 0);
    wire a_is_inf = (a_exp == 8'hff && a_mant == 0);
    wire b_is_inf = (b_exp == 8'hff && b_mant == 0);
    wire a_is_zero = (a_exp == 0 && a_mant == 0);
    wire b_is_zero = (b_exp == 0 && b_mant == 0);

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            z <= 0;
        end else begin
            case (counter)

                0: begin
                    a_sign <= a[31];
                    a_exp <= a[30:23];
                    a_mant <= a[22:0];
                    b_sign <= b[31];
                    b_exp <= b[30:23];
                    b_mant <= b[22:0];
                    a_mantissa <= {1'b1, a_mant};
                    b_mantissa <= {1'b1, b_mant};
                    counter <= 1;
                end


                1: begin
                    if (a_is_nan || b_is_nan) begin
                        z_sign <= a_sign ^ b_sign;
                        z_exp <= 8'hff;
                        z_mant <= 1;
                        z <= {z_sign, z_exp, z_mant};
                    end else if (a_is_zero || b_is_zero) begin
                        z_sign <= a_sign ^ b_sign;
                        z_exp <= 0;
                        z_mant <= 0;
                        z <= {z_sign, z_exp, z_mant};
                    end else if (a_is_inf || b_is_inf) begin
                        if ((a_is_inf && b_is_zero) || (b_is_inf && a_is_zero)) begin

                            z_sign <= a_sign ^ b_sign;
                            z_exp <= 8'hff;
                            z_mant <= 1;
                            z <= {z_sign, z_exp, z_mant};
                        end else begin
                            z_sign <= a_sign ^ b_sign;
                            z_exp <= 8'hff;
                            z_mant <= 0;
                            z <= {z_sign, z_exp, z_mant};
                        end
                    end else begin

                        z_exp <= a_exp + b_exp - 8'd127;
                        product <= a_mantissa * b_mantissa;
                        counter <= 2;
                    end
                end


                2: begin

                    if (product[49:48] >= 2'b10) begin

                        product <= {1'b0, product[49:1]};
                        shift_needed <= 2'd1;
                        z_exp <= z_exp + 1;
                    end else if (product[49:48] == 2'b01) begin
                        shift_needed <= 2'd0;
                    end else begin

                        shift_needed <= 2'd0;
                    end

                    counter <= 3;
                end


                3: begin

                    z_mant <= product[46:24];


                    if (guard && (round || sticky || z_mant[0])) begin
                        z_mant <= z_mant + 1;

                        if (z_mant == 24'h1000000) begin
                            z_mant <= 24'h0;
                            z_exp <= z_exp + 1;
                        end
                    end

                    if (z_exp >= 8'hff) begin
                        z_exp <= 8'hff;
                        z_mant <= 0;
                    end else if (z_exp == 0 && z_mant == 0) begin


                    end

                    z_sign <= a_sign ^ b_sign;
                    z <= {z_sign, z_exp, z_mant};
                    counter <= 0;
                end

                default: counter <= 0;
            endcase
        end
    end

endmodule

