) (
  input wclk,
  input wrstn,
  input rclk,
  input rrstn,
  input winc,
  input rinc,
  input [WIDTH-1:0] wdata,
  output reg wfull,
  output reg rempty,
  output [WIDTH-1:0] rdata
);

  localparam ADDR_BITS = $clog2(DEPTH);
  localparam PTR_WIDTH = ADDR_BITS + 1;


  dual_port_RAM #(
    .WIDTH(WIDTH),
    .DEPTH(DEPTH)
  ) ram_inst (
    .wclk(wclk),
    .wenc(winc && !wfull),
    .waddr(wptr_bin[ADDR_BITS-1:0]),
    .wdata(wdata),
    .rclk(rclk),
    .renc(rinc && !rempty),
    .raddr(rptr_bin[ADDR_BITS-1:0]),
    .rdata(rdata)
  );


  reg [PTR_WIDTH-1:0] wptr_bin, rptr_bin;
  wire [PTR_WIDTH-1:0] wptr, rptr;
  function [PTR_WIDTH-1:0] bin2gray(input [PTR_WIDTH-1:0] bin);
    bin2gray = bin ^ (bin >> 1);
  endfunction
  assign wptr = bin2gray(wptr_bin);
  assign rptr = bin2gray(rptr_bin);


  reg [PTR_WIDTH-1:0] rptr_gray_sync1, rptr_gray_sync2;

  reg [PTR_WIDTH-1:0] wptr_gray_sync1, wptr_gray_sync2;



  wire wfull_next = (wptr[PTR_WIDTH-1] != rptr_gray_sync2[PTR_WIDTH-1]) &&
                    (wptr[PTR_WIDTH-2] != rptr_gray_sync2[PTR_WIDTH-2]) &&
                    (wptr[PTR_WIDTH-3:0] == rptr_gray_sync2[PTR_WIDTH-3:0]);
  wire rempty_next = (rptr == wptr_gray_sync2);


  always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) {rptr_gray_sync1, rptr_gray_sync2} <= 0;
    else {rptr_gray_sync1, rptr_gray_sync2} <= {rptr, rptr_gray_sync1};
  end

  always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) {wptr_gray_sync1, wptr_gray_sync2} <= 0;
    else {wptr_gray_sync1, wptr_gray_sync2} <= {wptr, wptr_gray_sync1};
  end


  always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) wptr_bin <= 0;
    else if (winc && !wfull) wptr_bin <= wptr_bin + 1;
  end

  always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) rptr_bin <= 0;
    else if (rinc && !rempty) rptr_bin <= rptr_bin + 1;
  end

  always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) wfull <= 0;
    else wfull <= wfull_next;
  end

  always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) rempty <= 1;
    else rempty <= rempty_next;
  end

endmodule


