module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);

    parameter idle = 2'd0;
    parameter s1_red = 2'd1;
    parameter s2_yellow = 2'd2;
    parameter s3_green = 2'd3;

    reg [1:0] state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;
    reg r_red, r_yellow, r_green;

    assign red = r_red;
    assign yellow = r_yellow;
    assign green = r_green;
    assign clock = cnt;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            {r_red, r_yellow, r_green} <= 3'b000;
            cnt <= 10;
        end else begin

            p_red <= r_red;
            p_yellow <= r_yellow;
            p_green <= r_green;

            case (state)
                idle: begin
                    state <= s1_red;
                end

                s1_red: begin
                    {r_red, r_yellow, r_green} <= 3'b100;
                    if (cnt == 0) begin
                        state <= s3_green;
                        cnt <= 60;
                    end else cnt <= cnt - 1;
                end

                s3_green: begin
                    {r_red, r_yellow, r_green} <= 3'b001;
                    if (pass_request && r_green) begin
                        cnt <= (cnt > 10) ? 10 : cnt;
                    end else if (cnt == 0) begin
                        state <= s2_yellow;
                        cnt <=5;
                    end else cnt <= cnt - 1;
                end

                s2_yellow: begin
                    {r_red, r_yellow, r_green} <= 3'b010;
                    if (cnt == 0) begin
                        state <= s1_red;
                        cnt <=10;
                    end else cnt <= cnt - 1;
                end

                default: begin
                    state <= idle;
                end
            endcase
        end
    end

endmodule

