module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output [31:0] r,
    output zero,
    output carry,
    output negative,
    output overflow,
    output flag
);



parameter ADD  = 6'b100000;
parameter ADDU = 6'b100001;
parameter SUB  = 6'b100010;
parameter SUBU = 6'b100011;
parameter AND  = 6'b100100;
parameter OR   = 6'b100101;
parameter XOR  = 6'b100110;
parameter NOR  = 6'b100111;
parameter SLT  = 6'b101010;
parameter SLTU = 6'b101011;
parameter SLL  = 6'b000000;
parameter SRL  = 6'b000010;
parameter SRA  = 6'b000011;
parameter SLLV = 6'b000100;
parameter SRLV = 6'b000110;
parameter SRAV = 6'b000111;
parameter LUI  = 6'b001111;



reg [31:0] r_reg;

reg carry_reg;
reg overflow_reg;
reg negative_reg;

wire zero_reg;



wire flag_slt = ($signed(a) < $signed(b)) ? 1 : 0;
wire flag_sltu = (a < b) ? 1 : 0;

assign flag = ( (aluc == SLT) ) ? flag_slt : 
              ( (aluc == SLTU) ) ? flag_sltu : 1'bz;



assign zero_reg = (r_reg == 0);



assign negative_reg = r_reg[31];



assign r = r_reg;
assign carry = carry_reg;
assign negative = negative_reg;
assign zero = zero_reg;
assign overflow = overflow_reg;



always @* begin



    r_reg = 32'd0;
    carry_reg = 0;
    overflow_reg = 0;

    case (aluc)


        ADD: begin 
            {carry_reg, r_reg} = {1'b0,a} + {1'b0,b};

            overflow_reg = ( (a[31] == b[31]) && (r_reg[31] != a[31]) );
        end

        ADDU: begin 
            {carry_reg, r_reg} = {1'b0,a} + {1'b0,b};
            overflow_reg = 0;

        end

        SUB: begin
            {carry_reg, r_reg} = {1'b0,a} - {1'b0,b};































            {carry_reg, r_reg} = ( {1'b0,a} >= {1'b0,b} ) ? {1'b1, a - b } : {1'b0, a - b };

            Wait no, perhaps the code for subtraction:











            reg [32:0] subtract_33;
            subtract_33 = {1'b0,a} - {1'b0,b};
            r_reg = subtract_33[31:0];
            carry_reg = ~subtract_33[32];



            overflow_reg = ( (a[31] != b[31]) && (r_reg[31] != a[31]) );
        end

        SUBU: begin
            {carry_reg, r_reg} = {1'b0,a} - {1'b0,b};
            overflow_reg = 0;

        end



        AND: begin
            r_reg = a & b;
            carry_reg = 0;

            overflow_reg = 0;
        end

        OR: begin
            r_reg = a | b;
            carry_reg = 0;
            overflow_reg = 0;
        end

        XOR: begin
            r_reg = a ^ b;
            carry_reg = 0;
            overflow_reg = 0;
        end

        NOR: begin
            r_reg = ~(a | b);
            carry_reg = 0;
            overflow_reg = 0;
        end



        SLT: begin
            r_reg = ( $signed(a) < $signed(b) ) ? 32'd1 : 32'd0;
            carry_reg = 0;
            overflow_reg = 0;
        end



        SLTU: begin
            r_reg = ( a < b ) ? 32'd1 : 32'd0;
            carry_reg = 0;
            overflow_reg = 0;
        end



        SLL: begin

            r_reg = b << a[4:0];
            carry_reg = 0;

            overflow_reg = 0;
        end

        SRL: begin

            r_reg = b >> a[4:0];
            carry_reg = 0;
            overflow_reg = 0;
        end

        SRA: begin

            r_reg = $signed(b) >>> a[4:0];
            carry_reg = 0;
            overflow_reg = 0;
        end

        SLLV: begin

            r_reg = b << a[4:0];
            carry_reg = 0;
            overflow_reg = 0;
        end

        SRLV: begin
            r_reg = b >> a[4:0];
            carry_reg = 0;
            overflow_reg = 0;
        end

        SRAV: begin
            r_reg = $signed(b) >>> a[4:0];
            carry_reg = 0;
            overflow_reg = 0;
        end



        LUI: begin

            r_reg = { a[15:0], 16'b0 };
            carry_reg = 0;
            overflow_reg = 0;
        end


        default: begin
            r_reg = 32'bz;
            carry_reg = 0;
            overflow_reg = 0;
        end
    endcase
end

