module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output [15:0] result
);

    reg [7:0] abs_dividend;
    reg [7:0] abs_divisor;
    reg [7:0] quotient, remainder;
    reg [3:0] cnt;
    reg processing;
    reg [15:0] SR;
    reg [7:0] NEG_DIVISOR;
    reg saved_sign;
    reg [7:0] saved_dividend, saved_divisor;


    function [7:0] get_abs(input [7:0] val, input sign);
        begin
            if (sign && val[7])
                get_abs = ~val + 1;
            else
                get_abs = val;
        end
    endfunction

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            quotient <= 0;
            remainder <= 0;
            cnt <= 0;
            processing <= 0;
            SR <= 0;
            NEG_DIVISOR <= 0;
            saved_dividend <= 0;
            saved_divisor <= 0;
            saved_sign <= 0;
        end else begin
            if (opn_valid && !res_valid && !processing) begin

                saved_dividend <= get_abs(dividend, sign);
                saved_divisor <= get_abs(divisor, sign);
                saved_sign <= sign;

                SR <= {get_abs(dividend, sign), 8'b0} << 1;
                NEG_DIVISOR <= -get_abs(divisor, sign);
                cnt <= 1;
                processing <= 1;
                res_valid <= 0;
            end else if (processing && cnt <= 8) begin
                if (cnt == 8) begin

                    {remainder, quotient} <= SR;
                    processing <= 0;
                    res_valid <= 1;
                    cnt <= 0;
                end else begin

                    if ($signed(SR) >= $signed({NEG_DIVISOR, 8'b0})) begin
                        SR <= (SR - {NEG_DIVISOR, 8'b0}) << 1 | 1;
                    end else begin
                        SR <= SR << 1;
                    end
                    cnt <= cnt + 1;
                end
            end
            if (res_valid) begin
                res_valid <= 0;

            end
        end
    end

    assign result = (saved_sign && (saved_dividend[7] ^ saved_divisor[7])) ? 
                    {~remainder + 1, ~quotient + 1} : {remainder, quotient};

endmodule

