    input start,
    input [15:0] ain,
    input [15:0] bin,
    output [31:0] yout,
    output done
);

    reg [4:0] i;
    reg [15:0] areg;
    reg [15:0] breg;
    reg [31:0] yout_r;
    reg done_r;

    assign yout = yout_r;
    assign done = done_r;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            i <= 5'd0;
            areg <= 16'd0;
            breg <= 16'd0;
            yout_r <= 32'd0;
            done_r <= 1'b0;
        end else begin

            if (start) begin
                if (i < 17)
                    i <= i + 1;
                else
                    i <= i;
            end else begin
                i <= 5'd0;
            end


            if (i == 16)
                done_r <= 1'b1;
            else if (i == 17)
                done_r <= 1'b0;


            if (i == 5'd0) begin
                areg <= ain;
                breg <= bin;
                yout_r <= 32'd0;
            end else if (i >= 5'd1 && i < 5'd17) begin
                if (areg[i-1]) begin
                    yout_r <= yout_r + ( ( {16'd0, breg} ) << (i-1) );
                end
            end
        end
    end

endmodule

