module fixed_point_adder #(
    parameter Q = 8,
    parameter N = 16
)(
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

    wire [N-1:0] abs_a = a[N-1] ? (~a + 1) : a;
    wire [N-1:0] abs_b = b[N-1] ? (~b + 1) : b;

    reg [N-1:0] res_reg;
    wire sign_a = a[N-1];
    wire sign_b = b[N-1];

    always @* begin
        if (sign_a == sign_b) begin
            res_reg = a + b;
        end else begin
            if (abs_a > abs_b) begin
                res_reg = a - b;
            end else if (abs_b > abs_a) begin
                res_reg = b - a;
            end else begin
                res_reg = 0;
            end
        end
    end

    assign c = res_reg;

endmodule

