module fixed_point_subtractor #(
    parameter Q = 16,
    parameter N = 32
)(
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

    wire sign_a = a[N-1];
    wire sign_b = b[N-1];


    wire [N-1:0] a_abs = sign_a ? (~a + 1) : a;
    wire [N-1:0] b_abs = sign_b ? (~b + 1) : b;

    wire same_sign = (sign_a == sign_b);

    reg [N-1:0] diff_reg;
    reg res_sign_reg;

    always @* begin
        if (same_sign) begin
            diff_reg = a - b;
            res_sign_reg = sign_a;
        end
        else begin
            if (a_abs > b_abs) begin
                diff_reg = a_abs - b_abs;
                res_sign_reg = sign_a;
            end
            else if (b_abs > a_abs) begin
                diff_reg = b_abs - a_abs;
                res_sign_reg = sign_b;
            end
            else begin
                diff_reg = 0;
                res_sign_reg = 0;
            end
        end


        if (diff_reg == 0)
            res_sign_reg = 0;


        if (res_sign_reg)
            diff_reg = ~diff_reg + 1;
    end

    assign c = diff_reg;

endmodule

