    assign b_is_nan = (b_exponent == 8'hff) && (|b_mantissa);
    assign a_is_inf = (a_exponent == 8'hff) && (a_mantissa == 0);
    assign b_is_inf = (b_exponent == 8'hff) && (b_mantissa == 0);
    assign a_is_zero = (a_exponent == 0) && (a_mantissa == 0);
    assign b_is_zero = (b_exponent == 0) && (b_mantissa == 0);

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            z <= 0;
            z_sign <= 0;
            z_exponent <= 0;
            a_sign <= 0;
            b_sign <= 0;
            a_exponent <= 0;
            b_exponent <= 0;
            a_mantissa <= 0;
            b_mantissa <= 0;
            a_man <= 0;
            b_man <= 0;
            product <= 0;
        end else begin
            case (counter)

                0: begin
                    a_sign <= a[31];
