                        z <= {a_sign ^ b_sign, 8'h0, 23'h0};
                        counter <= 0;
                    end else begin
                        product <= a_man * b_man;
                        z_exponent <= a_exponent + b_exponent - 127;
                        z_sign <= a_sign ^ b_sign;
                        counter <= 2;
                    end
                end


                2: begin
                    if (product[47]) begin
                        product <= product >> 1;
                        z_exponent <= z_exponent + 1;
                    end

                    z <= {z_sign, z_exponent[7:0], product[46:24]};
                    counter <= 0;
                end
            endcase
        end
    end

