module fsm (
    input IN,
    input CLK,
    input RST,
    output reg MATCH
);


    localparam S0 = 3'd0;
    localparam S1 = 3'd1;
    localparam S2 = 3'd2;
    localparam S3 = 3'd3;
    localparam S4 = 3'd4;

    reg [2:0] current_state, next_state;


    always @(posedge CLK or posedge RST) begin
        if (RST) begin
            current_state <= S0;
        end
        else begin
            current_state <= next_state;
        end
    end


    always @(*) begin
        next_state = current_state;
        MATCH = 1'b0;

        case (current_state)
            S0: begin
                if (IN)
                    next_state = S1;
            end
            S1: begin
                if (~IN)
                    next_state = S2;
                else
                    next_state = S1;
            end
            S2: begin
                if (~IN)
                    next_state = S3;
                else
                    next_state = S1;
            end
            S3: begin
                if (IN)
                    next_state = S4;
                else
                    next_state = S0;
            end
            S4: begin
                if (IN) begin
                    MATCH = 1'b1;
                    next_state = S1;
                end
                else
                    next_state = S0;
            end
            default: next_state = S0;
        endcase
    end

endmodule

