module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input  wire                   wclk,
    input  wire                   rclk,
    input  wire                   wrstn,
    input  wire                   rrstn,
    input  wire                   winc,
    input  wire                   rinc,
    input  wire [WIDTH-1:0]       wdata,
    output wire                   wfull,
    output wire                   rempty,
    output wire [WIDTH-1:0]       rdata
);

localparam ADDR_BITS = $clog2(DEPTH);
localparam PTR_WIDTH = ADDR_BITS + 1;


reg [PTR_WIDTH-1:0] wptr_bin, rptr_bin;
reg [PTR_WIDTH:0] wptr_gray, rptr_gray;


reg [PTR_WIDTH:0] rptr_gray_sync_wr [1:0];
reg [PTR_WIDTH:0] wptr_gray_sync_rd [1:0];


wire [$clog2(DEPTH)-1:0] waddr = wptr_bin[ADDR_BITS-1:0];
wire [$clog2(DEPTH)-1:0] raddr = rptr_bin[ADDR_BITS-1:0];
wire wen = winc & ~wfull;
wire ren = rinc & ~rempty;


dual_port_RAM #(
    .WIDTH(WIDTH),
    .DEPTH(DEPTH)
) ram_inst (
    .wclk(wclk),
    .wenc(wen),
    .waddr(waddr),
    .wdata(wdata),
    .rclk(rclk),
    .renc(ren),
    .raddr(raddr),
    .rdata(rdata)
);


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        wptr_bin <= 0;
        wptr_gray <= 0;
        rptr_gray_sync_wr[0] <= 0;
        rptr_gray_sync_wr[1] <= 0;
    end else begin
        rptr_gray_sync_wr[0] <= rptr_gray;
        rptr_gray_sync_wr[1] <= rptr_gray_sync_wr[0];
        if (wen) wptr_bin <= wptr_bin + 1;
        wptr_gray <= (wptr_bin >> 1) ^ wptr_bin;
    end
end


always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        rptr_bin <= 0;
        rptr_gray <= 0;
        wptr_gray_sync_rd[0] <= 0;
        wptr_gray_sync_rd[1] <= 0;
    end else begin
        wptr_gray_sync_rd[0] <= wptr_gray;
        wptr_gray_sync_rd[1] <= wptr_gray_sync_rd[0];
        if (ren) rptr_bin <= rptr_bin + 1;
        rptr_gray <= (rptr_bin >> 1) ^ rptr_bin;
    end
end


wire [PTR_WIDTH-1:0] rptr_bin_synced = gray2bin(rptr_gray_sync_wr[1]);
wire [PTR_WIDTH-1:0] wptr_next = wptr_bin + (wen ? 1 : 0);

assign wfull = ((wptr_next - rptr_bin_synced) >= DEPTH) || 
               ((wptr_bin[PTR_WIDTH-1] != rptr_bin_synced[PTR_WIDTH-1]) && 
                (wptr_bin[PTR_WIDTH-2:0] == rptr_bin_synced[PTR_WIDTH-2:0]));

wire [PTR_WIDTH-1:0] wptr_bin_synced = gray2bin(wptr_gray_sync_rd[1]);
assign rempty = (rptr_bin == wptr_bin_synced);


function [PTR_WIDTH-1:0] gray2bin (input [PTR_WIDTH-1:0] gray);
    reg [PTR_WIDTH-1:0] bin;
    integer i;
    begin
        bin[PTR_WIDTH-1] = gray[PTR_WIDTH-1];
        for (i = PTR_WIDTH-2;
 i >= 0;
 i = i - 1)
            bin[i] = bin[i + 1] ^ gray[i];
        gray2bin = bin;
    end
endfunction

endmodule


