module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);


    parameter IDLE = 0;
    parameter S1_RED = 1;
    parameter S2_YELLOW = 2;
    parameter S3_GREEN = 3;


    reg [1:0] state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;
    reg red_reg, yellow_reg, green_reg;


    assign clock = cnt;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
        end else begin
            case (state)
                IDLE: state <= S1_RED;
                S1_RED: begin
                    if (cnt == 0)
                        state <= S2_YELLOW;
                    else
                        state <= S1_RED;
                end
                S2_YELLOW: begin
                    if (cnt == 0)
                        state <= S3_GREEN;
                    else
                        state <= S2_YELLOW;
                end
                S3_GREEN: begin
                    if (cnt == 0)
                        state <= S1_RED;
                    else
                        state <= S3_GREEN;
                end
                default: state <= IDLE;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 10;
        end else begin
            if (pass_request && green_reg && (cnt > 10))
                cnt <= 10;
            else if ((p_green && !green_reg))
                cnt <= 60;
            else if ((p_yellow && !yellow_reg))
                cnt <= 5;
            else if ((p_red && !red_reg))
                cnt <= 10;
            else
                cnt <= cnt - 1;
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            red_reg <= 0;
            yellow_reg <= 0;
            green_reg <= 0;
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
        end else begin
            p_red <= red_reg;
            p_yellow <= yellow_reg;
            p_green <= green_reg;

            case (state)
                S1_RED: begin
                    red_reg <= 1;
                    yellow_reg <= 0;
                    green_reg <= 0;
                end
                S2_YELLOW: begin
                    red_reg <= 0;
                    yellow_reg <= 1;
                    green_reg <= 0;
                end
                S3_GREEN: begin
                    red_reg <= 0;
                    yellow_reg <= 0;
                    green_reg <= 1;
                end
                default: begin
                    red_reg <= 0;
                    yellow_reg <= 0;
                    green_reg <= 0;
                end
            endcase
        end
    end

    assign red = red_reg;
    assign yellow = yellow_reg;
    assign green = green_reg;

endmodule

