    parameter NOR   = 6'b100111;
    parameter SLT   = 6'b101010;
    parameter SLTU  = 6'b101011;
    parameter SLL   = 6'b000000;
    parameter SRL   = 6'b000010;
    parameter SRA   = 6'b000011;
    parameter SLLV  = 6'b000100;
    parameter SRLV  = 6'b000110;
    parameter SRAV  = 6'b000111;
    parameter LUI   = 6'b001111;

    reg [31:0] res;
    reg carry_out;
    reg op_overflow;

    always @* begin
        res = 32'd0;
        zero = 1'b0;
        carry = 1'b0;
        negative = 1'b0;
        overflow = 1'b0;
        flag = 1'bz;

        case (aluc)
            ADD: begin

                {carry_out, res} = {1'b0, a} + {1'b0, b};

                op_overflow = (a[31] == b[31]) && (res[31] != a[31]);
                overflow = op_overflow;
                carry = carry_out;
            end
            ADDU: begin

                {carry_out, res} = {1'b0, a} + {1'b0, b};
                overflow = 1'b0;
                carry = carry_out;
            end
            SUB: begin

                {carry_out, res} = {1'b0, a} - {1'b0, b};

                op_overflow = (a[31] != b[31]) && (res[31] != a[31]);
                overflow = op_overflow;

                carry = ~carry_out;
            end
            SUBU: begin

                {carry_out, res} = {1'b0, a} - {1'b0, b};
                overflow = 1'b0;

                carry = ~carry_out;
            end
            AND: begin
                res = a & b;
            end
            OR: begin
                res = a | b;
            end
            XOR: begin
                res = a ^ b;
            end
            NOR: begin
                res = ~(a | b);
            end
            SLT: begin
                res = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
                flag = 1'b1;
            end
            SLTU: begin
                res = (a < b) ? 32'd1 : 32'd0;
                flag = 1'b1;
            end
            SLL: begin
                res = b << a[4:0];

                carry = 1'b0;
            end
            SRL: begin
                res = b >> a[4:0];
                carry = 1'b0;
            end
            SRA: begin
                res = $signed(b) >>> a[4:0];
                carry = 1'b0;
            end
            SLLV: begin
                res = b << a[4:0];
                carry = 1'b0;
            end
            SRLV: begin
                res = b >> a[4:0];
                carry = 1'b0;
            end
            SRAV: begin
                res = $signed(b) >>> a[4:0];
                carry = 1'b0;
            end
            LUI: begin
                res = {a[15:0], 16'd0};
            end
            default: begin
                res = 32'bz;
            end
        endcase


        zero = (res == 32'd0);
        negative = res[31];


        if (aluc != SLT && aluc != SLTU) flag = 1'bz;
        r = res;
    end

