module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] abs_dividend, abs_divisor;
reg quotient_sign, remainder_sign;
reg [7:0] quotient, remainder;
reg [7:0] NEG_DIVISOR;
reg [8:0] SR;
reg [3:0] cnt;
reg in_progress;
reg [7:0] dividend_reg, divisor_reg;


always @* begin
    if (sign && dividend[7]) abs_dividend = ~dividend + 1;
    else abs_dividend = dividend;
    if (sign && divisor[7]) abs_divisor = ~divisor + 1;
    else abs_divisor = divisor;
end


always @* begin
    if (remainder_sign && sign)
        remainder = ~abs_dividend + 1;
    else
        remainder = abs_dividend;
    if (quotient_sign && sign)
        quotient = ~abs_divisor + 1;
    else
        quotient = abs_divisor;
end

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        in_progress <= 0;
        cnt <= 0;
        SR <= 0;
        quotient <= 0;
        remainder <= 0;
        quotient_sign <= 0;
        remainder_sign <= 0;
        dividend_reg <= 0;
        divisor_reg <= 0;
        result <= 0;
    end else begin
        if (opn_valid && !res_valid && !in_progress) begin
            in_progress <= 1;
            res_valid <= 0;
            dividend_reg <= dividend;
            divisor_reg <= divisor;

            if (sign) begin
                quotient_sign <= dividend[7] ^ divisor[7];
                remainder_sign <= dividend[7];
                quotient <= dividend[7] ? (~dividend + 1) : dividend;
                remainder <= divisor[7] ? (~divisor + 1) : divisor;
            end else begin
                quotient_sign <= 0;
                remainder_sign <= 0;
                quotient <= dividend;
                remainder <= divisor;
            end

            SR <= {quotient, 1'b0};
            NEG_DIVISOR <= ~remainder + 1;
            cnt <= 0;
        end

        if (in_progress && !res_valid) begin
            if (cnt < 8) begin
                if (SR[8:1] >= NEG_DIVISOR) begin
                    SR <= {SR[8:1] - NEG_DIVISOR, 1'b0};
                    quotient <= (quotient << 1) | 1;
                end else begin
                    SR <= {SR[8:1], 1'b0};
                    quotient <= quotient << 1;
                end
                cnt <= cnt + 1;
            end else begin
                in_progress <= 0;
                res_valid <= 1;
                result <= {remainder, quotient};
            end
        end

        if (res_valid && opn_valid) begin
            res_valid <= 0;
            in_progress <= 0;
            cnt <= 0;
        end
    end
end

endmodule

