module fixed_point_adder #(
    parameter Q = 8,
    parameter N = 16
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

reg [N-1:0] res;

wire a_sign = a[N-1];
wire b_sign = b[N-1];


wire [N-1:0] abs_a = a_sign ? (~a + 1) : a;
wire [N-1:0] abs_b = b_sign ? (~b + 1) : b;

always @* begin
    if (a_sign == b_sign) begin

        res = a + b;
    end else begin

        if (abs_a > abs_b) begin
            res = a - b;
            res[N-1] = a_sign;

        end else if (abs_b > abs_a) begin
            res = b - a;
            res[N-1] = b_sign;
        end else begin

            res = {1'b0, {(N-1){1'b0}}};
        end
    end
end

assign c = res;

endmodule

