module sub_64bit (
    input [63:0] A,
    input [63:0] B,
    output [63:0] result,
    output overflow
);

wire [63:0] res;
assign res = A - B;

wire sign_A = A[63];
wire sign_B = B[63];
wire sign_res = res[63];


wire positive_overflow = (~sign_A) & sign_B & sign_res;


wire negative_overflow = sign_A & (~sign_B) & (~sign_res);

assign overflow = positive_overflow | negative_overflow;

assign result = res;

endmodule

