    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            rptr <= 0;
            rptr_gray <= 0;
        end else begin
            if (rinc && !rempty) rptr <= rptr + 1;
            rptr_gray <= (rptr >> 1) ^ rptr;

