module LIFObuffer(
    input [3:0] dataIn,
    input RW,
    input EN,
    input Rst,
    input Clk,
    output EMPTY,
    output FULL,
    output reg [3:0] dataOut
);

reg [3:0] stack_mem [0:3];
reg [2:0] SP;

integer i;

always @(posedge Clk) begin
    if (Rst) begin
        SP <= 4;
        for (i = 0;
 i < 4;
 i = i + 1)
            stack_mem[i] <= 0;
    end
    else if (EN) begin
        if (RW == 0 && !FULL) begin 
            stack_mem[SP - 1] <= dataIn;
            SP <= SP - 1;
        end
        else if (RW == 1 && !EMPTY) begin 
            dataOut <= stack_mem[SP];
            stack_mem[SP] <= 0;

            SP <= SP + 1;
        end
    end
end

assign EMPTY = (SP == 4);
assign FULL = (SP == 0);

endmodule

