module pulse_detect(
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

    localparam S0 = 2'd0,
               S1 = 2'd1,
               S2 = 2'd2;

    reg [1:0] state;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S0;
            data_out <= 1'b0;
        end else begin
            case (state)
                S0: begin
                    if (data_in == 1'b0) begin
                        state <= S1;
                        data_out <= 1'b0;
                    end else begin
                        state <= S0;
                        data_out <= 1'b0;
                    end
                end
                S1: begin
                    if (data_in == 1'b1) begin
                        state <= S2;
                        data_out <= 1'b0;
                    end else begin
                        state <= S0;
                        data_out <= 1'b0;
                    end
                end
                S2: begin
                    if (data_in == 1'b0) begin
                        data_out <= 1'b1;
                        state <= S0;
                    end else begin
                        data_out <= 1'b0;
                        state <= S0;
                    end
                end
                default: begin
                    state <= S0;
                    data_out <= 1'b0;
                end
            endcase
        end
    end

endmodule

