module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);

    parameter idle = 0,
              s1_red = 1,
              s2_yellow = 2,
              s3_green = 3;

    reg [1:0] state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;
    reg p_red_prev, p_yellow_prev, p_green_prev;

    assign clock = cnt;
    assign red = p_red;
    assign yellow = p_yellow;
    assign green = p_green;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
            cnt <= 10;
            p_red_prev <= 0;
            p_yellow_prev <= 0;
            p_green_prev <= 0;
        end else begin
            p_red_prev <= p_red;
            p_yellow_prev <= p_yellow;
            p_green_prev <= p_green;

            case (state)
                idle: begin
                    state <= s1_red;
                    p_red <= 1;
                    cnt <= 3;
                end

                s1_red: begin
                    if (cnt == 1) begin
                        state <= s3_green;
                        cnt <= 60;
                        p_red <= 0;
                        p_green <= 1;
                    end else begin
                        cnt <= cnt - 1;
                    end
                end

                s3_green: begin
                    if (pass_request && p_green && (cnt > 10))
                        cnt <= 10;
                    if (cnt == 1) begin
                        state <= s2_yellow;
                        cnt <= 5;
                        p_green <= 0;
                        p_yellow <= 1;
                    end else begin
                        cnt <= cnt - 1;
                    end
                end

                s2_yellow: begin
                    if (cnt == 1) begin
                        state <= s1_red;
                        cnt <= 3;
                        p_yellow <= 0;
                        p_red <= 1;
                    end else begin
                        cnt <= cnt - 1;
                    end
                end

                default: state <= idle;
            endcase

            if (!p_red && p_red_prev)
                cnt <= 3;
            else if (!p_green && p_green_prev)
                cnt <= 60;
            else if (!p_yellow && p_yellow_prev)
                cnt <=5;

            if (pass_request && p_green && (cnt >10))
                cnt <=10;
        end
    end

endmodule

