module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output [15:0] result
);

    reg processing;
    reg [3:0] cnt;
    reg [7:0] abs_dividend;
    reg [7:0] abs_divisor;
    reg [7:0] quo;
    reg [7:0] rem;
    reg remainder_sign;
    reg quotient_sign;
    reg [7:0] abs_divisor_neg;

    reg [15:0] result_reg;

    assign result = result_reg;


    reg sign_quo;
    reg sign_rem;

    always @(posedge clk) begin
        if (rst) begin
            processing <= 0;
            cnt <= 0;
            res_valid <= 0;
            quo <= 0;
            rem <= 0;
            abs_dividend <= 0;
            abs_divisor <= 0;
            remainder_sign <= 0;
            quotient_sign <= 0;
            result_reg <= 0;
        end else begin
            if (opn_valid && !processing && !res_valid) begin

                processing <= 1;
                cnt <= 0;
                res_valid <= 0;


                if (sign) begin

                    abs_dividend <= dividend[7] ? (~dividend + 1) : dividend;
                    abs_divisor <= divisor[7] ? (~divisor + 1) : divisor;
                    remainder_sign <= dividend[7];
                    quotient_sign <= dividend[7] ^ divisor[7];
                end else begin

                    abs_dividend <= dividend;
                    abs_divisor <= divisor;
                    remainder_sign <= 0;
                    quotient_sign <= 0;
                end


                rem <= 0;
                quo <= abs_dividend;
            end else if (processing) begin
                if (cnt < 8) begin

                    if (rem >= abs_divisor) begin
                        rem <= rem - abs_divisor;
                        quo <= (quo << 1) | 1;
                    end else begin
                        quo <= quo << 1;
                    end


                    rem <= (rem << 1) | (quo >> 7);
                    quo <= quo << 1;

                    cnt <= cnt + 1;
                end else begin

                    processing <= 0;
                    res_valid <= 1;

                    if (quotient_sign)
                        quo <= ~quo + 1;
                    if (remainder_sign)
                        rem <= ~rem + 1;

                    result_reg <= { rem, quo };
                end
            end


            if (res_valid) begin
                res_valid <= 0;
            end
        end
    end

endmodule

