module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg [7:0] a_exp, b_exp;
    reg [22:0] a_man, b_man;
    reg a_sign, b_sign;
    reg [9:0] z_exponent;
    reg z_sign;
    reg [49:0] product;
    reg [23:0] a_mantissa, b_mantissa;
    reg [49:0] product_man;
    reg guard_bit, round_bit, sticky;


    wire a_zero = (a_exp == 0 && a_man == 0);
    wire b_zero = (b_exp == 0 && b_man == 0);
    wire a_inf = (a_exp == 8'hff && a_man == 0);
    wire b_inf = (b_exp == 8'hff && b_man == 0);
    wire a_nan = (a_exp == 8'hff && a_man != 0);
    wire b_nan = (b_exp == 8'hff && b_man != 0);


    reg [49:0] product_round;
    reg [23:0] z_mantissa;
    reg [9:0] z_exp_adj;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            z <= 0;
            product <= 0;
            a_sign <= 0;
            b_sign <= 0;
            a_exp <= 0;
            b_exp <= 0;
            a_man <= 0;
            b_man <= 0;

        end else begin
            case (counter)
                0: begin

                    a_sign <= a[31];
                    a_exp <= a[30:23];
                    a_man <= a[22:0];
                    b_sign <= b[31];
                    b_exp <= b[30:23];
                    b_man <= b[22:0];
                    counter <= 1;
                end

                1: begin

                    if (a_nan || b_nan) begin
                        z <= 32'h7FC00000;

                    end else if (a_inf || b_inf) begin
                        if (a_zero || b_zero) begin
                            z <= 32'h7FC00000;

                        end else begin
                            z_exponent <= 9'h1FF;
                            z_mantissa <= 0;
                            z_sign <= a_sign ^ b_sign;
                            z <= {z_sign, 8'hFF, z_mantissa};
                        end
                    end else if (a_zero || b_zero) begin
                        z <= {a_sign ^ b_sign, 31'h0};
                    end else begin

                        product_man <= {1'b0, a_man} * {1'b0, b_man};
                        z_sign <= a_sign ^ b_sign;
                        z_exp_adj <= a_exp + b_exp - 127;
                        counter <= 2;
                    end
                end

                2: begin

                    if (product_man[49] || product_man[48]) begin
                        product_man <= product_man >> 1;
                        z_exp_adj <= z_exp_adj + 1;
                    end
                    counter <= 3;
                end

                3: begin



                    if (z_exp_adj > 255) begin

                        z <= {z_sign, 8'hFF, 23'h0};
                    end else begin
                        z <= {z_sign, z_exp_adj[7:0], product_man[47:25]};
                    end
                    counter <= 0;
                end

                default: counter <= 0;
            endcase
        end
    end

endmodule

