module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wclk,
    input wrstn,
    input winc,
    input [WIDTH-1:0] wdata,
    output wfull,
    input rclk,
    input rrstn,
    input rinc,
    output rempty,
    output [WIDTH-1:0] rdata
);

localparam ADDR_WIDTH = $clog2(DEPTH);
localparam PTR_WIDTH = ADDR_WIDTH + 1;


wire [ADDR_WIDTH-1:0] waddr, raddr;
wire wen, ren;


reg [ADDR_WIDTH:0] waddr_bin, raddr_bin;
reg [ADDR_WIDTH:0] wptr_bin, rptr_bin;
reg [ADDR_WIDTH:0] wptr_gray, rptr_gray;


reg [ADDR_WIDTH:0] rptr_gray_sync_wclk [1:0];
reg [ADDR_WIDTH:0] wptr_gray_sync_rclk [1:0];


reg wfull_reg, rempty_reg;


dual_port_RAM #(
    .WIDTH(WIDTH),
    .DEPTH(DEPTH)
) ram (
    .wclk(wclk),
    .wen(wen),
    .waddr(waddr),
    .wdata(wdata),
    .ren(ren),
    .rclk(rclk),
    .raddr(raddr),
    .rdata(rdata)
);


function [ADDR_WIDTH:0] bin2gray(input [ADDR_WIDTH:0] bin);
    bin2gray = bin ^ (bin >> 1);
endfunction

function [ADDR_WIDTH:0] gray2bin(input [ADDR_WIDTH:0] gray);
    reg [ADDR_WIDTH:0] bin;
    integer i;
    begin
        bin[ADDR_WIDTH] = gray[ADDR_WIDTH];
        for (i = ADDR_WIDTH-1;
 i >= 0;
 i = i-1)
            bin[i] = bin[i+1] ^ gray[i];
        gray2bin = bin;
    end
endfunction


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        waddr_bin <= 0;
        wptr_bin <= 0;
        wptr_gray <= 0;
    end else begin
        if (winc && !wfull_reg) begin
            waddr_bin <= waddr_bin + 1;
        end
        wptr_bin <= waddr_bin;
        wptr_gray <= bin2gray(waddr_bin);
    end
end


always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        raddr_bin <= 0;
        rptr_bin <= 0;
        rptr_gray <= 0;
    end else begin
        if (rinc && !rempty_reg) begin
            raddr_bin <= raddr_bin + 1;
        end
        rptr_bin <= raddr_bin;
        rptr_gray <= bin2gray(raddr_bin);
    end
end


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        rptr_gray_sync_wclk[0] <= 0;
        rptr_gray_sync_wclk[1] <= 0;
    end else begin
        rptr_gray_sync_wclk[0] <= rptr_gray;
        rptr_gray_sync_wclk[1] <= rptr_gray_sync_wclk[0];
    end
end


always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        wptr_gray_sync_rclk[0] <= 0;
        wptr_gray_sync_rclk[1] <= 0;
    end else begin
        wptr_gray_sync_rclk[0] <= wptr_gray;
        wptr_gray_sync_rclk[1] <= wptr_gray_sync_rclk[0];
    end
end


wire [ADDR_WIDTH:0] rptr_sync = gray2bin(rptr_gray_sync_wclk[1]);
wire full_condition = ((wptr_bin - rptr_sync) >= DEPTH);

wire [ADDR_WIDTH:0] wptr_sync = gray2bin(wptr_gray_sync_rclk[1]);
wire empty_condition = (wptr_sync == rptr_bin);


always @(*) begin
    wfull_reg = full_condition;
    rempty_reg = empty_condition;
end


assign wfull = wfull_reg;
assign rempty = rempty_reg;


assign wen = winc && !wfull_reg;
assign ren = rinc && !rempty_reg;
assign waddr = waddr_bin[ADDR_WIDTH-1:0];
assign raddr = raddr_bin[ADDR_WIDTH-1:0];

endmodule


module dual_port_RAM #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wclk,
    input wen,
    input [$clog2(DEPTH)-1:0] waddr,
    input [WIDTH-1:0] wdata,
    input rclk,
    input ren,
    input [$clog2(DEPTH)-1:0] raddr,
    output reg [WIDTH-1:0] rdata
);

reg [WIDTH-1:0] ram [0:DEPTH-1];


always @(posedge wclk) begin
    if (wen)
        ram[waddr] <= wdata;
end


always @(posedge rclk) begin
    if (ren)
        rdata <= ram[raddr];
end

endmodule

