module LIFObuffer (
    input [3:0] dataIn,
    input RW,
    input EN,
    input Rst,
    input Clk,
    output EMPTY,
    output FULL,
    output reg [3:0] dataOut
);

reg [3:0] stack_mem [0:3];
reg [2:0] sp;

integer i;


assign EMPTY = (sp == 4);
assign FULL = (sp == 0);

always @(posedge Clk) begin
    if (Rst) begin
        sp <= 4;

        for (i = 0;
 i < 4;
 i = i + 1)
            stack_mem[i] <= 0;
        dataOut <= 0;
    end else begin
        if (EN) begin
            if (RW == 0) begin 
                if (!FULL) begin
                    stack_mem[sp - 1] <= dataIn;
                    sp <= sp - 1;
                end
            end else begin 
                if (!EMPTY) begin
                    dataOut <= stack_mem[sp - 1];
                    sp <= sp + 1;
                end
            end
        end
    end
end

endmodule

