    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);
    parameter idle = 0,
              s1_red = 1,
              s2_yellow = 2,
              s3_green = 3;

    reg [7:0] cnt;
    reg [1:0] state;
    reg p_red, p_yellow, p_green;
    reg r_red, r_yellow, r_green;

    assign clock = cnt;
    assign red = r_red;
    assign yellow = r_yellow;
    assign green = r_green;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
        end else begin
            case (state)
                idle: begin
                    state <= s1_red;
                end
                s1_red: begin
                    if (cnt == 0) begin
                        state <= s3_green;
                        cnt <= 60 - 1;
                    end
                    p_red <= 1;
                end
                s3_green: begin
                    p_green <= 1;
                    if (pass_request && green) begin
                        if (cnt > 10) cnt <= 10;
                        else cnt <= cnt;
