                default: state <= idle;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 10;
            state <= idle;
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
