                    else cnt <= 5 - 1;
                end
                s2_yellow: begin
                    if (cnt > 0) cnt <= cnt - 1;
                    else cnt <= 10 - 1;
                end
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            r_red <= 0;
            r_yellow <= 0;
            r_green <= 0;
        end else begin
            r_red <= p_red;
            r_yellow <= p_yellow;
            r_green <= p_green;
        end
    end

