module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [7:0] saved_dividend, saved_divisor;
    reg sign_q, sign_r;
    reg [3:0] cnt;
    reg start_cnt;
    reg [15:0] SR;
    reg [7:0] neg_divisor;
    reg sign_dividend, sign_divisor;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            start_cnt <= 0;
            cnt <= 0;
            SR <= 0;
            saved_dividend <= 0;
            saved_divisor <= 0;
            neg_divisor <= 0;
            sign_dividend <= 0;
            sign_divisor <= 0;
            sign_q <= 0;
            sign_r <= 0;
            result <= 0;
        end else begin
            if (opn_valid && !res_valid) begin

                if (sign) begin
                    saved_dividend <= dividend[7] ? -dividend : dividend;
                    saved_divisor <= divisor[7] ? -divisor : divisor;
                    sign_dividend <= dividend[7];
                    sign_divisor <= divisor[7];
                    sign_r <= dividend[7];
                    sign_q <= dividend[7] ^ divisor[7];
                end else begin
                    saved_dividend <= dividend;
                    saved_divisor <= divisor;
                    sign_dividend <= 0;
                    sign_divisor <= 0;
                    sign_q <= 0;
                    sign_r <= 0;
                end


                SR <= {saved_dividend, 1'b0};
                neg_divisor <= -saved_divisor;
                cnt <= 1;
                start_cnt <= 1;
                res_valid <= 0;
            end

            if (start_cnt) begin
                if (cnt == 4'd8) begin

                    if (sign) begin
                        result[7:0] <= sign_q ? -SR[7:0] : SR[7:0];
                        result[15:8] <= sign_r ? -saved_dividend : saved_dividend;
                    end else begin
                        result <= {SR[15:8], SR[7:0]};
                    end
                    start_cnt <= 0;
                    res_valid <= 1;
                end else begin

                    if ((SR >> 15) >= saved_divisor) begin
                        SR <= {SR[14:0], 1'b1} - {11'b0, saved_divisor};
                    end else begin
                        SR <= SR << 1;
                    end
                    cnt <= cnt + 1;
                end
            end else if (res_valid && opn_valid) begin
                res_valid <= 0;
            end
        end
    end
endmodule

