module fixed_point_adder #(
    parameter Q = 8,
    parameter N = 16
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);
    reg [N-1:0] res;
    reg sign_a, sign_b;
    reg [N-2:0] mag_a, mag_b;
    reg [N-2:0] mag_diff;
    reg sum_sign;

    always @* begin
        sign_a = a[N-1];
        sign_b = b[N-1];
        mag_a = a[N-2:0];
        mag_b = b[N-2:0];
        if (sign_a == sign_b) begin
            res = {sign_a, mag_a + mag_b};
        end else begin
            if (mag_a > mag_b) begin
                mag_diff = mag_a - mag_b;
                sum_sign = sign_a;
            end else if (mag_b > mag_a) begin
                mag_diff = mag_b - mag_a;
                sum_sign = sign_b;
            end else begin
                mag_diff = 0;
                sum_sign = 0;
            end
            res = {sum_sign, mag_diff};
        end
    end

    assign c = res;
endmodule

