module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign;
    reg [9:0] a_exp, b_exp;
    reg [23:0] a_man, b_man;
    reg [49:0] product;
    reg [9:0] exp_sum;
    reg [24:0] man_tmp;
    reg guard, round, sticky;


    wire a_zero = (a_exp == 0) && (a_man == 0);
    wire b_zero = (b_exp == 0) && (b_man == 0);
    wire a_inf = (a_exp == 8'hFF) && (a_man == 0);
    wire b_inf = (b_exp == 8'hFF) && (b_man == 0);
    wire a_nan = (a_exp == 8'hFF) && (a_man != 0);
    wire b_nan = (b_exp == 8'hFF) && (b_man != 0);

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            z <= 0;
        end else begin
            case (counter)
                0: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exp <= a[30:23];
                    b_exp <= b[30:23];
                    a_man <= (a_exp != 0) ? {1'b1, a[22:0]} : {1'b0, a[22:0]};
                    b_man <= (b_exp != 0) ? {1'b1, b[22:0]} : {1'b0, b[22:0]};
                    counter <= 1;
                end

                1: begin

                    if (a_nan || b_nan) begin
                        z <= {1'b0, 8'hFF, a_man | b_man};

                        counter <= 0;
                    end else if (a_zero || b_zero) begin
                        z <= {a_sign ^ b_sign, 31'd0};
                        counter <= 0;
                    end else if (a_inf || b_inf) begin
                        if ((a_zero && b_inf) || (b_zero && a_inf)) begin
                            z <= {1'b0, 8'hFF, 23'h0};

                        end else begin
                            z <= {a_sign ^ b_sign, 8'hFF, 23'h0};
                        end
                        counter <= 0;
                    end else begin
                        product <= a_man * b_man;
                        exp_sum <= a_exp + b_exp - 9'd127;
                        counter <= 2;
                    end
                end

                2: begin

                    man_tmp = product;
                    guard = product[24];
                    round = product[23];
                    sticky = |product[22:0];


                    if (product[49] && product[48]) begin
                        man_tmp = man_tmp >> 1;
                        exp_sum = exp_sum + 1;
                    end else if (product[49]) begin
                        exp_sum = exp_sum + 1;
                    end else begin
                        man_tmp = man_tmp >> 24;
                    end


                    if (guard && (round || sticky)) begin
                        man_tmp = man_tmp + 1;
                        if (man_tmp[24]) begin
                            man_tmp = man_tmp >> 1;
                            exp_sum = exp_sum + 1;
                        end
                    end


                    if (exp_sum >= 255) begin
                        z <= {a_sign ^ b_sign, 8'hFF, 23'h0};
                    end else if (exp_sum <= 0) begin
                        z <= {a_sign ^ b_sign, 31'h0};
                    end else begin
                        z <= {a_sign ^ b_sign, exp_sum[7:0], man_tmp[23:1]};
                    end

                    counter <= 0;
                end

                default: counter <= 0;
            endcase
        end
    end

endmodule

