    else if (EN) begin
        if (!RW) begin 
            if (!FULL) begin
                stack_mem[sp - 1] <= dataIn;
                sp <= sp - 1;
            end
        end
        else begin 
            if (!EMPTY) begin
                dataOut_reg <= stack_mem[sp - 1];
                stack_mem[sp - 1] <= 4'b0;
                sp <= sp + 1;
            end
        end
    end
end

