module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

    reg [1:0] state;
    localparam S_IDLE = 0;
    localparam S_FIRST = 1;
    localparam S_SECOND = 2;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S_IDLE;
            data_out <= 0;
        end else begin
            case (state)
                S_IDLE: begin
                    data_out <= 0;
                    if (data_in == 0) begin
                        state <= S_FIRST;
                    end else begin
                        state <= S_IDLE;
                    end
                end
                S_FIRST: begin
                    data_out <= 0;
                    if (data_in == 1) begin
                        state <= S_SECOND;
                    end else begin
                        state <= S_IDLE;
                    end
                end
                S_SECOND: begin
                    data_out <= 0;
                    if (data_in == 0) begin
                        data_out <= 1;
                        state <= S_IDLE;
                    end else begin
                        state <= S_IDLE;
                    end
                end
