module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);


    parameter idle = 2'd0,
              s1_red = 2'd1,
              s2_yellow = 2'd2,
              s3_green = 2'd3;


    reg [1:0] state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;


    assign red = p_red;
    assign yellow = p_yellow;
    assign green = p_green;
    assign clock = cnt;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            cnt <= 8'd10;
            {p_red, p_yellow, p_green} <= 3'b000;
        end else begin
            case (state)
                idle: begin
                    state <= s1_red;
                    cnt <= 8'd3;
                    {p_red, p_yellow, p_green} <= 3'b100;
                end
                s1_red: begin
                    if (cnt == 0) begin
                        state <= s3_green;
                        cnt <= 8'd60;
                        {p_red, p_yellow, p_green} <= 3'b001;
                    end else begin
                        cnt <= cnt - 1;
                    end
                end
                s3_green: begin
                    if (cnt == 0) begin
                        state <= s2_yellow;
                        cnt <= 8'd5;
                        {p_red, p_yellow, p_green} <= 3'b010;
                    end else begin
                        cnt <= cnt - 1;
                    end
                end
                s2_yellow: begin
                    if (cnt == 0) begin
                        state <= s1_red;
                        cnt <= 8'd10;
                        {p_red, p_yellow, p_green} <= 3'b100;
                    end else begin
                        cnt <= cnt - 1;
                    end
                end
                default: state <= idle;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 8'd10;
        end else begin
            if (pass_request && green) begin
