                if (green && (cnt == 0)) begin
                    cnt <= 8'd5;
                end else if (yellow && (cnt == 0)) begin
                    cnt <= 8'd10;
                end else if (red && (cnt == 0)) begin
                    cnt <= 8'd60;
                end else begin
                    cnt <= cnt - 1;
                end
            end
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            {p_red, p_yellow, p_green} <= 3'b000;
        end else begin
            {p_red, p_yellow, p_green} <= {red, yellow, green};
        end
    end

endmodule

