module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output reg carry,
    output reg negative,
    output reg overflow,
    output flag
);

    parameter ADD = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND = 6'b100100;
    parameter OR = 6'b100101;
    parameter XOR = 6'b100110;
    parameter NOR = 6'b100111;
    parameter SLT = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL = 6'b000000;
    parameter SRL = 6'b000010;
    parameter SRA = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI = 6'b001111;

    reg [31:0] res;
    reg c_flag;
    reg o_flag;
    reg [31:0] sum_temp;


    assign zero = (res == 32'd0);


    assign negative = res[31];


    assign flag = ( (aluc == SLT) || (aluc == SLTU) ) ? res[0] : 1'bz;


    always @* begin

        res = 32'bz;
        carry = 0;
        overflow = 0;

        case (aluc)
            ADD: begin
                sum_temp = a + b;
                res = sum_temp;
                carry = (a + b) > 32'hFFFFFFFF;

                overflow = (a[31] == b[31]) && (res[31] != a[31]);
            end

            ADDU: begin
                sum_temp = a + b;
                res = sum_temp;
                carry = (sum_temp > 32'hFFFFFFFF);


            end

            SUB: begin
                sum_temp = a - b;
                res = sum_temp;

                overflow = (a[31] != b[31]) && (sum_temp[31] != a[31]);
                carry = (a >= b);

            end

            SUBU: begin
                sum_temp = a - b;
                res = sum_temp;
                carry = (a >= b);

                overflow = 0;

            end

            AND: begin
                res = a & b;

            end

            OR: begin
                res = a | b;
            end

            XOR: begin
                res = a ^ b;
            end

            NOR: begin
                res = ~(a | b);
            end

            SLT: begin
                res = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
            end

            SLTU: begin
                res = (a < b) ? 32'd1 : 32'd0;
            end

            SLL: begin
                res = b << a[4:0];
            end

            SRL: begin
                res = b >> a[4:0];
            end

            SRA: begin
                res = $signed(b) >>> a[4:0];
            end

            SLLV: begin
                res = b << a[4:0];
            end

            SRLV: begin
                res = b >> a[4:0];
            end

            SRAV: begin
                res = $signed(b) >>> a[4:0];
            end

            LUI: begin
                res = {b[15:0], 16'b0};



            end

            default: res = 32'bz;
        endcase
    end


    always @* begin
        r = res;
    end

endmodule

