module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg processing;
    reg [15:0] SR;
    reg [3:0] cnt;
    reg [7:0] divisor_abs;
    reg [7:0] saved_dividend_abs, saved_divisor_abs;
    reg sign_q, sign_r;

    wire [7:0] abs_dividend = (sign & dividend[7]) ? (~dividend + 1) : dividend;
    wire [7:0] abs_divisor = (sign & divisor[7]) ? (~divisor + 1) : divisor;

    always @(posedge clk) begin
        if (rst) begin
            processing <= 0;
            res_valid <= 0;
            SR <= 0;
            cnt <= 0;
            divisor_abs <= 0;
            saved_dividend_abs <= 0;
            saved_divisor_abs <= 0;
            sign_q <= 0;
            sign_r <= 0;
            result <= 0;
        end else begin
            if (res_valid) begin
                res_valid <= 0;
            end

            if (opn_valid && !processing && !res_valid) begin
                saved_dividend_abs <= abs_dividend;
                saved_divisor_abs <= abs_divisor;

                SR <= {abs_dividend, 8'b0} << 1;
                divisor_abs <= abs_divisor;

                if (sign) begin
                    sign_r <= dividend[7];
                    sign_q <= (dividend[7] ^ divisor[7]);
                end else begin
                    sign_r <= 0;
                    sign_q <= 0;
                end

                cnt <= 4'd1;
                processing <= 1;
            end

            if (processing) begin
                if (cnt < 8) begin
                    reg [8:0] sub_res;
                    sub_res = {1'b0, SR[15:8]} - {1'b0, divisor_abs};

                    if (!sub_res[8]) begin
                        SR[15:8] <= sub_res[7:0];
                    end

                    SR <= SR << 1;
                    cnt <= cnt + 1;
                end else begin
                    processing <= 0;
                    res_valid <= 1;

                    reg [7:0] rem, quo;
                    rem = SR[15:8];
                    quo = SR[7:0];

                    if (sign) begin
                        if (sign_r) rem = -rem;
                        if (sign_q) quo = -quo;
                    end

                    result <= {rem, quo};
                end
            end
        end
    end

endmodule

