            if (count == 2'd3) begin

                data_out <= sum + data_in;
                valid_out <= 1'b1;

                sum <= 10'd0;
                count <= 2'd0;
            end
            else begin
                sum <= sum + data_in;
                count <= count + 1;
            end
        end
    end
end

