module fixed_point_adder #(
    parameter Q = 16,
    parameter N = 32
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

    reg [N-1:0] res;

    wire sign_a = a[N-1];
    wire sign_b = b[N-1];
    wire same_sign = (sign_a == sign_b);


    wire [N-2:0] abs_a = sign_a ? (~a[N-2:0] + 1) : a[N-2:0];
    wire [N-2:0] abs_b = sign_b ? (~b[N-2:0] + 1) : b[N-2:0];


    wire [N-1:0] sum_same = {sign_a, abs_a + abs_b};


    wire a_gt_b = (abs_a > abs_b);
    wire [N-2:0] mag_diff;
    assign mag_diff = a_gt_b ? (abs_a - abs_b) :
                      ((abs_b > abs_a) ? (abs_b - abs_a) : {(N-2){1'b0}});

    wire diff_sign;
    assign diff_sign = a_gt_b ? sign_a :
                       ((abs_b > abs_a) ? sign_b : 1'b0);

    wire [N-1:0] res_diff = {diff_sign, mag_diff};


    always @* begin
        if (same_sign)
            res = sum_same;
        else
            res = res_diff;
    end

    assign c = res;

endmodule

