module fixed_point_subtractor #(
    parameter Q = 4,
    parameter N = 8
)(
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

    reg [N-1:0] res;
    wire sign_a = a[N-1];
    wire sign_b = b[N-1];
    wire [N-2:0] a_mag = sign_a ? (~a[N-2:0] + 1) : a[N-2:0];
    wire [N-2:0] b_mag = sign_b ? (~b[N-2:0] + 1) : b[N-2:0];
    wire same_sign = sign_a == sign_b;

    always @* begin
        if (same_sign) begin
            res = a - b;
        end
        else begin
            if (a_mag > b_mag) begin
                res[N-2:0] = a_mag - b_mag;
                res[N-1] = sign_a;
            end
            else if (b_mag > a_mag) begin
                res[N-2:0] = b_mag - a_mag;
                res[N-1] = sign_b;
            end
            else begin
                res = 0;
            end
        end

        if (res == 0)
            res[N-1] = 0;
    end

    assign c = res;

endmodule

