    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent;
    reg [23:0] a_mantissa, b_mantissa;
    reg [49:0] product;
    reg [7:0] sum_exp;
    reg guard, round, sticky;


    reg a_zero, b_zero;
    reg a_inf, b_inf;
    reg a_nan, b_nan;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'd0;
            a_sign <= 0;
            b_sign <= 0;
            z_sign <= 0;
            a_exponent <= 0;
            b_exponent <= 0;
            a_mantissa <= 0;
            b_mantissa <= 0;
            product <= 0;
            guard <= 0;
            round <= 0;
            sticky <= 0;
            sum_exp <= 0;
            a_zero <= 0;
            b_zero <= 0;
            a_inf <= 0;
            b_inf <= 0;
            a_nan <= 0;
            b_nan <= 0;
        end else begin
            case (counter)
                3'b000: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_zero <= (a[30:0] == 31'd0);
                    b_zero <= (b[30:0] == 31'd0);
                    a_inf <= (a[30:23] == 8'hff) && (a[22:0] == 0);
                    b_inf <= (b[30:23] == 8'hff) && (b[22:0] == 0);
                    a_nan <= (a[30:23] == 8'hff) && (a[22:0] != 0);
                    b_nan <= (b[30:23] == 8'hff) && (b[22:0] != 0);
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];

                    a_mantissa <= (a[30:23] == 8'd0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                    b_mantissa <= (b[30:23] == 8'd0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};

                    counter <= counter + 1;
                end

                3'b001: begin

                    if (a_nan || b_nan) begin
                        z <= 32'hFC000000;

                    end else if ((a_inf && b_zero) || (b_inf && a_zero)) begin
                        z <= 32'hFC000000;

                    end else if (a_inf || b_inf) begin

                        z_sign <= a_sign ^ b_sign;
                        z[30:0] <= 31'h7F800000;
                    end else if (a_zero || b_zero) begin

                        z <= {z_sign, 31'd0};
                    end else begin

                        product <= a_mantissa * b_mantissa;
                        sum_exp <= a_exponent + b_exponent - 8'd127;
                    end
                    counter <= counter + 1;
                end

                3'b010: begin

                    if (product[49]) begin

                        z_mantissa <= {product[48:25], guard, round};
                        sum_exp <= sum_exp + 1;
                    end else begin

                        z_mantissa <= {product[47:24], guard, round};
                    end

                    sticky <= |product[23:0];
                    guard <= product[24];
                    round <= product[23];

                    if (sum_exp >= 255)
                        z <= {z_sign, 8'hFF, 23'd0};
                    else if (sum_exp <= 0)
                        z <= {z_sign, 31'd0};
                    else
                        z <= {z_sign, sum_exp, z_mantissa};
                    counter <= 0;
                end
            endcase
