module sub_64bit (
    input [63:0] A,
    input [63:0] B,
    output [63:0] result,
    output overflow
);
    wire [63:0] result_wire;
    assign result_wire = A - B;

    wire A_sign = A[63];
    wire B_sign = B[63];
    wire result_sign = result_wire[63];

    wire pos_ov = (~A_sign) & B_sign & result_sign;
    wire neg_ov = A_sign & (~B_sign) & ~result_sign;

    assign overflow = pos_ov | neg_ov;
    assign result = result_wire;

endmodule

