            S2: begin
                MATCH = 1'b0;
                next_state = IN ? S1 : S3;
            end
            S3: begin
                MATCH = 1'b0;
                next_state = IN ? S4 : S1;
            end
            S4: begin
                MATCH = IN;
                next_state = IN ? S1 : S0;
            end
            default: begin
                MATCH = 1'b0;
                next_state = S0;
            end
        endcase
    end
