module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wire wclk,
    input wire wrstn,
    input wire rclk,
    input wire rrstn,
    input wire winc,
    input wire rinc,
    input wire [WIDTH-1:0] wdata,
    output reg wfull,
    output reg rempty,
    output wire [WIDTH-1:0] rdata
);

    localparam ADDR_WIDTH = $clog2(DEPTH);
    localparam PTR_WIDTH = ADDR_WIDTH + 1;


    reg [PTR_WIDTH-1:0] waddr_bin;
    reg [PTR_WIDTH-1:0] waddr_gray;


    reg [PTR_WIDTH-1:0] raddr_bin;
    reg [PTR_WIDTH-1:0] raddr_gray;


    dual_port_RAM #(
        .WIDTH(WIDTH),
        .DEPTH(DEPTH)
    ) ram (
        .wclk(wclk),
        .wenc(winc && !wfull),
        .waddr(waddr_bin[ADDR_WIDTH-1:0]),
        .wdata(wdata),
        .rclk(rclk),
        .renc(rinc && !rempty),
        .raddr(raddr_bin[ADDR_WIDTH-1:0]),
        .rdata(rdata)
    );


    reg [PTR_WIDTH-1:0] raddr_gray_sync_wr0, raddr_gray_sync_wr1;
    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            raddr_gray_sync_wr0 <= 0;
            raddr_gray_sync_wr1 <= 0;
        end else begin
            raddr_gray_sync_wr0 <= raddr_gray;
            raddr_gray_sync_wr1 <= raddr_gray_sync_wr0;
        end
    end


    reg [PTR_WIDTH-1:0] waddr_gray_sync_rd0, waddr_gray_sync_rd1;
    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            waddr_gray_sync_rd0 <= 0;
            waddr_gray_sync_rd1 <= 0;
        end else begin
            waddr_gray_sync_rd0 <= waddr_gray;
            waddr_gray_sync_rd1 <= waddr_gray_sync_rd0;
        end
    end


    always @(*) begin
        waddr_gray = waddr_bin ^ (waddr_bin >> 1);
        raddr_gray = raddr_bin ^ (raddr_bin >> 1);
    end


    wire [PTR_WIDTH-1:0] waddr_bin_next = waddr_bin + (winc && !wfull);
    wire [PTR_WIDTH-1:0] raddr_bin_next = raddr_bin + (rinc && !rempty);


    wire wfull_wire = (waddr_gray == {~raddr_gray_sync_wr1[PTR_WIDTH-1 -: 2], raddr_gray_sync_wr1[ADDR_WIDTH-1:0]});
    wire rempty_wire = (waddr_gray_sync_rd1 == raddr_gray);


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) wfull <= 0;
        else wfull <= wfull_wire;
    end

    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) rempty <= 1;
        else rempty <= rempty_wire;
    end


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) waddr_bin <= 0;
        else if (winc && !wfull) waddr_bin <= waddr_bin + 1;
    end


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) raddr_bin <= 0;
        else if (rinc && !rempty) raddr_bin <= raddr_bin + 1;
    end

endmodule

