module LIFObuffer (
    input Clk,
    input Rst,
    input EN,
    input RW,
    input [3:0] dataIn,
    output EMPTY,
    output FULL,
    output reg [3:0] dataOut
);

reg [3:0] stack_mem [0:3];

reg [2:0] SP;



assign EMPTY = (SP == 4);
assign FULL = (SP == 0);

integer i;


always @(posedge Clk) begin
    if (Rst) begin
        SP <= 4;


        for (i = 0;
 i < 4;
 i = i + 1)
            stack_mem[i] <= 4'b0;
        dataOut <= 4'b0;
    end
    else if (EN) begin
        if (!FULL && !RW) begin 
            stack_mem[SP-1] <= dataIn;
            SP <= SP - 1;
        end
        else if (!EMPTY && RW) begin 
            dataOut <= stack_mem[SP];
            SP <= SP + 1;
        end
    end
end

endmodule

