module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out = 0
);

    reg state;
    localparam S0 = 0, S1 = 1;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S0;
            data_out <= 0;
        end else begin
            data_out <= 0;

            case (state)
                S0: begin
                    if (data_in)
                        state <= S1;
                    else
                        state <= S0;
                end
                S1: begin
                    if (data_in)
                        state <= S1;
                    else begin
                        state <= S0;
                        data_out <= 1;
                    end
                end
            endcase
        end
    end

endmodule

