module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);


    parameter [1:0] idle = 2'b00,
                    s1_red = 2'b01,
                    s2_yellow = 2'b10,
                    s3_green = 2'b11;


    reg [7:0] cnt;
    reg [1:0] state;
    reg p_red, p_yellow, p_green;
    reg prev_p_green, prev_p_yellow, prev_p_red;


    assign clock = cnt;
    assign red = p_red;
    assign yellow = p_yellow;
    assign green = p_green;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
            prev_p_green <= 0;
            prev_p_yellow <= 0;
            prev_p_red <= 0;
        end else begin
            prev_p_green <= p_green;
            prev_p_yellow <= p_yellow;
            prev_p_red <= p_red;

            case (state)
                idle: begin
                    state <= s1_red;
                    {p_red, p_yellow, p_green} <= 3'b100;
                end
                s1_red: begin
                    if (cnt == 3) begin
                        state <= s3_green;
                        {p_red, p_yellow, p_green} <= 3'b001;
                    end else begin
                        state <= s1_red;
                        {p_red, p_yellow, p_green} <= 3'b100;
                    end
                end
                s3_green: begin
                    if (cnt == 60) begin
                        state <= s2_yellow;
                        {p_red, p_yellow, p_green} <= 3'b010;
                    end else begin
                        state <= s3_green;
                        {p_red, p_yellow, p_green} <= 3'b001;
                    end
                end
                s2_yellow: begin
                    if (cnt == 5) begin
                        state <= s1_red;
                        {p_red, p_yellow, p_green} <= 3'b100;
                    end else begin
                        state <= s2_yellow;
                        {p_red, p_yellow, p_green} <= 3'b010;
                    end
                end
                default: state <= idle;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 10;
        end else begin
            if (pass_request && p_green) begin
                cnt <= 10;
            end else if (!p_green && prev_p_green) begin
                cnt <= 60;
            end else if (!p_yellow && prev_p_yellow) begin
                cnt <= 5;
            end else if (!p_red && prev_p_red) begin
                cnt <= 10;
            end else begin
                cnt <= cnt - 1;
            end
        end
    end

endmodule

