            next_wave = wave + 1;
            if (next_wave == 5'd31)
                next_state = 1;
            else
                next_state = 0;
        end
        1: begin 
            next_wave = wave - 1;
            if (next_wave == 5'd0)
                next_state = 0;
            else
                next_state = 1;
