                    if (cnt == 8) begin

                        result[15:8] <= (sign && remainder_sign) ? (~shift_reg[23:16] + 1) : shift_reg[23:16];
                        result[7:0] <= (quotient_sign) ? (~shift_reg[15:8] + 1) : shift_reg[15:8];
