                        state <= IDLE;
                    end else begin

                        if (shift_reg[23:16] >= abs_divisor) begin
                            shift_reg <= { (shift_reg[23:16] - abs_divisor), shift_reg[15:0], 1'b1 };
                        end else begin
                            shift_reg <= { shift_reg[23:16], shift_reg[15:0], 1'b0 };
                        end
                        cnt <= cnt + 1;
                    end
                end
            endcase
