module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output [15:0] result,
    output [15:0] odd
);

    reg [15:0] a_reg, b_reg;
    reg [15:0] quotient, remainder;


    reg [15:0] divisor;
    reg [15:0] temp;
    integer i;


    always @* begin
        a_reg = A;
        b_reg = B;
    end


    always @* begin
        quotient = 16'd0;
        remainder = 16'd0;
        divisor = {8'd0, b_reg};


        temp = 16'd0;

        for (i = 15;
 i >= 0;
 i = i - 1) begin
            temp = (temp << 1) | (a_reg[i] ? 1'd1 : 1'd0);
            if (temp >= divisor) begin
                temp = temp - divisor;
                quotient[i] = 1'd1;
            end else begin
                quotient[i] = 1'd0;
            end
        end

        remainder = temp;
    end

    assign result = quotient;
    assign odd = remainder;

endmodule

