module cla_16bit (
    input [16:1] A,
    input [16:1] B,
    input Cin,
    output [16:1] S,
    output Cout
);
    wire [16:1] G, P;
    wire [17:1] C;

    assign C[0] = Cin;

    generate
        genvar i;
        for (i = 1;
 i <= 16;
 i = i + 1) begin : gp
            assign G[i] = A[i] & B[i];
            assign P[i] = A[i] | B[i];
            assign C[i+1] = G[i] | (P[i] & C[i]);
        end
    endgenerate

    generate
        genvar j;
        for (j = 1;
 j <= 16;
 j = j + 1) begin : sum
            assign S[j] = (A[j] ^ B[j]) ^ C[j];
        end
    endgenerate

    assign Cout = C[17];
endmodule

