    wire b_zero = (b_exp == 0) && (b_man == 0);
    wire a_inf = (a_exp == 8'hff);
    wire b_inf = (b_exp == 8'hff);
    wire a_nan = (a_exp == 8'hff) && (a_man != 0);
    wire b_nan = (b_exp == 8'hff) && (b_man != 0);
    wire zero_inf = (a_zero && b_inf) || (b_zero && a_inf);

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            z <= 0;
