                        b_man_adj <= (b_exp != 0) ? {1'b1, b_man} : {1'b0, b_man};
                        sum_exp <= a_exp + b_exp - 127;
                        counter <= 2;
                    end
                end

                2: begin

                    product <= a_man_adj * b_man_adj;

                    if (product[47]) begin
                        sum_exp <= sum_exp + 1;
                        product <= product >> 1;
                    end

                    counter <= 3;
                end

                3: begin





                    z_sign <= a_sign ^ b_sign;
                    z_exponent <= sum_exp[7:0];
                    z_mantissa <= product[46:24];

                    z <= {z_sign, z_exponent, z_mantissa};
                    counter <= 0;
                end
            endcase
