module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wclk,
    input wrstn,
    input rclk,
    input rrstn,
    input winc,
    input rinc,
    input [WIDTH-1:0] wdata,
    output wfull,
    output rempty,
    output [WIDTH-1:0] rdata
);

    localparam ADDR_WIDTH = $clog2(DEPTH);
    localparam PTR_WIDTH = ADDR_WIDTH + 1;


    reg [ADDR_WIDTH-1:0] waddr, raddr;
    reg wen, ren;


    dual_port_RAM #(
        .WIDTH(WIDTH),
        .DEPTH(DEPTH)
    ) ram_inst (
        .wclk(wclk),
        .wenc(wen),
        .waddr(waddr),
        .wdata(wdata),
        .rclk(rclk),
        .renc(ren),
        .raddr(raddr),
        .rdata(rdata)
    );


    reg [PTR_WIDTH-1:0] wbin, rbin;
    wire [PTR_WIDTH-1:0] wgray, rgray;
    assign wgray = wbin ^ (wbin >> 1);
    assign rgray = rbin ^ (rbin >> 1);


    reg [PTR_WIDTH-1:0] rgray_sync1, rgray_sync2;
    reg [PTR_WIDTH-1:0] wgray_sync1, wgray_sync2;


    function [PTR_WIDTH-1:0] gray2bin;
        input [PTR_WIDTH-1:0] gray;
        integer i;
        begin
            gray2bin[PTR_WIDTH-1] = gray[PTR_WIDTH-1];
            for (i = PTR_WIDTH-2;
 i >= 0;
 i = i - 1)
                gray2bin[i] = gray2bin[i+1] ^ gray[i];
        end
    endfunction

    wire [PTR_WIDTH-1:0] rbin_sync, wbin_sync;
    assign rbin_sync = gray2bin(rgray_sync2);
    assign wbin_sync = gray2bin(wgray_sync2);


    reg wfull, rempty;
    reg [PTR_WIDTH-1:0] wbin_next, rbin_next;


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn)
            wbin <= 0;
        else
            wbin <= wbin_next;
    end


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn)
            rbin <= 0;
        else
            rbin <= rbin_next;
    end


    wire [ADDR_WIDTH-1:0] waddr_bin = wbin[ADDR_WIDTH-1:0];
    assign wen = !wfull && winc;
    assign wbin_next = wen ? wbin + 1 : wbin;
    assign waddr = wen ? waddr_bin : waddr_bin;


    wire [ADDR_WIDTH-1:0] raddr_bin = rbin[ADDR_WIDTH-1:0];
    assign ren = !rempty && rinc;
    assign rbin_next = ren ? rbin + 1 : rbin;
    assign raddr = ren ? raddr_bin : raddr_bin;


    assign wfull = ( (wbin_next == {~rbin_sync[PTR_WIDTH-1], rbin_sync[PTR_WIDTH-2:0]} ) 
                   && ( (wbin_next[PTR_WIDTH-1] != rbin_sync[PTR_WIDTH-1]) 
                   || (wbin_next[PTR_WIDTH-2:0] != rbin_sync[PTR_WIDTH-2:0]) )) 
                  || ( (wbin_next - rbin_sync) >= DEPTH );


    assign rempty = ( rbin == wbin_sync );


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            rgray_sync1 <= 0;
            rgray_sync2 <= 0;
        end else begin
            rgray_sync1 <= rgray;
            rgray_sync2 <= rgray_sync1;
        end
    end


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            wgray_sync1 <= 0;
            wgray_sync2 <= 0;
        end else begin
            wgray_sync1 <= wgray;
            wgray_sync2 <= wgray_sync1;
        end
    end

endmodule


module dual_port_RAM #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wclk,
    input wenc,
    input [$clog2(DEPTH)-1:0] waddr,
    input [WIDTH-1:0] wdata,
    input rclk,
    input renc,
    input [$clog2(DEPTH)-1:0] raddr,
    output reg [WIDTH-1:0] rdata
);

    reg [WIDTH-1:0] mem [0:DEPTH-1];


    always @(posedge wclk) begin
        if (wenc)
            mem[waddr] <= wdata;
    end


    always @(posedge rclk) begin
        if (renc)
            rdata <= mem[raddr];
    end

endmodule

