module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output red,
    output yellow,
    output green,
    output [7:0] clock
);


    parameter idle     = 2'd0,
              s1_red   = 2'd1,
              s2_yellow= 2'd2,
              s3_green = 2'd3;

    reg [1:0] state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end else begin
            case (state)
                idle: state <= s1_red;
                s1_red: if (cnt == 0) state <= s3_green;
                s3_green: if (cnt == 0) state <= s2_yellow;
                s2_yellow: if (cnt == 0) state <= s1_red;
                default: state <= idle;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 10;
        end else begin
            if (pass_request && p_green && (cnt > 10)) begin
                cnt <= 10;
            end else if (cnt == 0) begin
                case (state)
                    s1_red: cnt <= 60;

                    s3_green: cnt <= 5;

                    s2_yellow: cnt <= 10;

                    default: cnt <= cnt - 1;
                endcase
            end else begin
                cnt <= cnt - 1;
            end
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
        end else begin
            p_red <= (state == s1_red);
            p_yellow <= (state == s2_yellow);
            p_green <= (state == s3_green);
        end
    end

    assign red = p_red;
    assign yellow = p_yellow;
    assign green = p_green;
    assign clock = cnt;

endmodule

