module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid = 0,
    output [15:0] result
);

    reg [15:0] SR;

    reg [3:0] cnt;
    reg processing;
    reg [7:0] quotient;
    reg [7:0] remainder;
    reg [7:0] divisor_abs;
    reg [7:0] divisor_neg;
    reg [7:0] dividend_abs;
    reg dividend_sign;
    reg divisor_sign;
    reg saved_sign;
    reg [7:0] q_unsigned;
    reg [7:0] r_unsigned;


    assign result = {remainder, quotient};


    always @* begin

        if (sign && dividend[7])
            dividend_abs = ~dividend + 1;
        else
            dividend_abs = dividend;


        if (sign && divisor[7]) begin
            divisor_abs = ~divisor + 1;
            divisor_neg = divisor;

        end else begin
            divisor_abs = divisor;
            divisor_neg = ~divisor + 1;
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            processing <= 0;
            cnt <= 0;
            quotient <= 0;
            remainder <= 0;
            SR <= 0;
            dividend_sign <= 0;
            divisor_sign <= 0;
            saved_sign <= 0;
            q_unsigned <= 0;
            r_unsigned <= 0;
        end else begin
            if (opn_valid && !res_valid && !processing) begin

                dividend_sign <= sign && dividend[7];
                divisor_sign <= sign && divisor[7];
                saved_sign <= sign;


                SR <= {dividend_abs, 8'b0} << 1;
                divisor_neg <= divisor_neg;

                cnt <= 1;
                processing <= 1;
                res_valid <= 0;
            end else if (processing) begin
                if (cnt <= 8) begin

                    if (SR[15:8] >= divisor_abs) begin
                        SR <= { (SR[15:8] - divisor_abs), SR[7:0], 1'b1 };
                    end else begin
                        SR <= { SR[15:8], SR[7:0], 1'b0 };
                    end
                    cnt <= cnt + 1;
                end else begin

                    processing <= 0;
                    cnt <= 0;
                    q_unsigned <= SR[7:0];
                    r_unsigned <= SR[15:8];


                    if (saved_sign) begin
                        quotient <= (dividend_sign ^ divisor_sign) ? (~q_unsigned + 1) : q_unsigned;
                        remainder <= dividend_sign ? (~r_unsigned + 1) : r_unsigned;
                    end else begin
                        quotient <= q_unsigned;
                        remainder <= r_unsigned;
                    end
                    res_valid <= 1;
                end
            end
        end
    end
endmodule

