module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

reg [15:0] a_reg;
reg [7:0] b_reg;


always @(*) begin
    a_reg = A;
    b_reg = B;
end


always @(*) begin
    reg [15:0] dividend;
    reg [15:0] divisor_16;
    reg [15:0] rem_temp;
    reg [15:0] quotient;
    integer i;

    dividend = a_reg;
    divisor_16 = {8'd0, b_reg};

    rem_temp = 16'd0;
    quotient = 16'd0;

    for (i = 15;
 i >= 0;
 i = i - 1) begin

        rem_temp = (rem_temp << 1) | (dividend[i] & 1);


        if (rem_temp >= divisor_16) begin
            rem_temp = rem_temp - divisor_16;
            quotient[i] = 1'b1;
        end else begin
            quotient[i] = 1'b0;
        end
    end

    result = quotient;
    odd = rem_temp;
end

endmodule

