module fixed_point_adder #(
    parameter Q = 4,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

    reg [N-1:0] res;

    wire same_sign;
    assign same_sign = (a[N-1] == b[N-1]);

    wire [N-1:0] abs_a, abs_b;
    assign abs_a = a[N-1] ? (~a + 1) : a;
    assign abs_b = b[N-1] ? (~b + 1) : b;

    wire [N-1:0] sum;
    assign sum = a + b;

    reg [N-1:0] mag_sub;
    reg sign_sub;

    always @* begin
        if (abs_a > abs_b) begin
            mag_sub = abs_a - abs_b;
            sign_sub = a[N-1];
        end else if (abs_b > abs_a) begin
            mag_sub = abs_b - abs_a;
            sign_sub = b[N-1];
        end else begin
            mag_sub = 0;
            sign_sub = 0;
        end
    end

    reg [N-1:0] res_temp;

    always @* begin
        if (same_sign)
            res_temp = sum;
        else
            res_temp = {sign_sub, mag_sub[N-2:0]};
    end

    always @* begin
        c = res_temp;
    end

endmodule

