module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wclk,
    input wrstn,
    input rclk,
    input rrstn,
    input winc,
    input rinc,
    input [WIDTH-1:0] wdata,
    output rempty,
    output wfull,
    output [WIDTH-1:0] rdata
);
    localparam ADDR_WIDTH = $clog2(DEPTH);
    localparam PTR_WIDTH = ADDR_WIDTH + 1;


    reg [PTR_WIDTH-1:0] waddr_bin, raddr_bin;
    wire [PTR_WIDTH-1:0] waddr_gray, raddr_gray;
    reg [PTR_WIDTH-1:0] raddr_gray_sync1, raddr_gray_sync2;
    reg [PTR_WIDTH-1:0] waddr_gray_sync1, waddr_gray_sync2;


    dual_port_RAM #(
        .DEPTH(DEPTH),
        .WIDTH(WIDTH)
    ) ram (
        .wclk(wclk),
        .wenc(winc),
        .waddr(waddr_bin[ADDR_WIDTH-1:0]),
        .wdata(wdata),
        .rclk(rclk),
        .renc(rinc),
        .raddr(raddr_bin[ADDR_WIDTH-1:0]),
        .rdata(rdata)
    );


    assign waddr_gray = (waddr_bin >> 1) ^ waddr_bin;
    assign raddr_gray = (raddr_bin >> 1) ^ raddr_bin;


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn)
            waddr_bin <= 0;
        else if (winc && !wfull)
            waddr_bin <= waddr_bin + 1;
    end


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn)
            raddr_bin <= 0;
        else if (rinc && !rempty)
            raddr_bin <= raddr_bin + 1;
    end


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            raddr_gray_sync1 <= 0;
            raddr_gray_sync2 <= 0;
        end else begin
            raddr_gray_sync1 <= raddr_gray;
            raddr_gray_sync2 <= raddr_gray_sync1;
        end
    end


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            waddr_gray_sync1 <= 0;
            waddr_gray_sync2 <= 0;
        end else begin
            waddr_gray_sync1 <= waddr_gray;
            waddr_gray_sync2 <= waddr_gray_sync1;
        end
    end


    wire rempty;
    wire wfull_cond;

    assign rempty = (raddr_gray == waddr_gray_sync2);

    generate
        if (PTR_WIDTH >= 3) begin
            assign wfull_cond = ((waddr_gray[PTR_WIDTH-1] ^ raddr_gray_sync2[PTR_WIDTH-1]) &&
                                 (waddr_gray[PTR_WIDTH-2] ^ raddr_gray_sync2[PTR_WIDTH-2]) &&
                                 (waddr_gray[PTR_WIDTH-3:0] == raddr_gray_sync2[PTR_WIDTH-3:0]));
        end else begin
            assign wfull_cond = 1'b0;
        end
    endgenerate

    assign wfull = wfull_cond;

endmodule

