        for (i = 0;
 i < 4;
 i = i + 1) begin
            stack_mem[i] <= 4'b0;
        end
        SP <= 4;

    end
    else if (EN) begin
        if (!RW) begin 
            if (!FULL) begin
                stack_mem[SP - 1] <= dataIn;
                SP <= SP - 1;
            end
        end
        else begin 
            if (!EMPTY) begin
                dataOut <= stack_mem[SP - 1];
                stack_mem[SP - 1] <= 4'b0;
                SP <= SP + 1;
            end
        end
    end
end

