    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= 2'd0;
            data_out <= 0;
        end
        else begin
            case (state)
                2'd0: begin
                    data_out <= 0;
                    if (data_in == 0)
                        state <= 2'd1;
                    else
                        state <= 2'd0;
                end
                2'd1: begin
                    data_out <= 0;
                    if (data_in == 1)
                        state <= 2'd2;
