module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);


    localparam [1:0] 
        IDLE    = 2'b00,
        S1_RED  = 2'b01,
        S2_YELLOW = 2'b10,
        S3_GREEN = 2'b11;

    reg [1:0] state, next_state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;


    assign clock = cnt;
    assign red = p_red;
    assign yellow = p_yellow;
    assign green = p_green;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end


    always @* begin
        case (state)
            IDLE: next_state = S1_RED;
            S1_RED: next_state = (cnt == 0) ? S3_GREEN : S1_RED;
            S3_GREEN: next_state = (cnt == 0) ? S2_YELLOW : S3_GREEN;
            S2_YELLOW: next_state = (cnt == 0) ? S1_RED : S2_YELLOW;
            default: next_state = IDLE;
        endcase
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 10;
        end else begin

            if (pass_request && green && (cnt > 10)) begin
                cnt <= 10;
            end else if (green && !p_green) begin 
                cnt <= 5;
            end else if (yellow && !p_yellow) begin 
                cnt <= 60;
            end else if (red && !p_red) begin 
                cnt <= 10;
            end else begin
                cnt <= cnt - 1;
            end
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
        end else begin
            p_red <= (state == S1_RED);
            p_yellow <= (state == S2_YELLOW);
            p_green <= (state == S3_GREEN);
        end
    end

endmodule

