module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output [15:0] result
);

    reg [7:0] abs_dividend, abs_divisor;
    reg [7:0] saved_dividend, saved_divisor;
    reg [8:0] SR;

    reg [7:0] neg_divisor;

    reg [3:0] cnt;
    reg processing;
    reg [7:0] remainder;
    reg [7:0] quotient;


    assign result = {remainder, quotient};


    always @* begin
        if (sign) begin
            abs_dividend = dividend[7] ? (~dividend + 1) : dividend;
            abs_divisor = divisor[7] ? (~divisor + 1) : divisor;
        end else begin
            abs_dividend = dividend;
            abs_divisor = divisor;
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            processing <= 0;
            cnt <= 0;
            SR <= 0;
            remainder <= 0;
            quotient <= 0;
        end else begin
            if (opn_valid && !res_valid && !processing) begin

                saved_dividend <= dividend;
                saved_divisor <= divisor;

                SR <= {abs_dividend, 1'b0};

                neg_divisor <= -abs_divisor;

                cnt <= 4'd1;
                processing <= 1;
                res_valid <= 0;
            end

            if (processing) begin
                if (cnt == 4'd8) begin

                    processing <= 0;
                    res_valid <= 1;
                end else begin

                    if (SR >= {neg_divisor, 1'b0}) begin

                        SR <= SR - {neg_divisor, 1'b0};
                        quotient <= {quotient[6:0], 1'b1};
                    end else begin
                        quotient <= {quotient[6:0], 1'b0};
                    end
                    cnt <= cnt + 1;
                end
            end

            if (res_valid && opn_valid) begin
                res_valid <= 0;

            end
        end
    end

endmodule

