module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output [15:0] result,
    output [15:0] odd
);

    reg [15:0] a_reg;
    reg [7:0] b_reg;


    always @ (A, B) begin
        a_reg = A;
        b_reg = B;
    end


    reg [15:0] quotient;
    reg [15:0] remainder;
    integer i;


    always @ (A, B) begin
        quotient = 16'd0;
        remainder = 16'd0;

        for (i = 15;
 i >= 0;
 i = i - 1) begin

            remainder = (remainder << 1) | (a_reg[i] ? 1'b1 : 1'b0);

            if (remainder >= {8'd0, b_reg}) begin
                quotient[i] = 1'b1;
                remainder = remainder - {8'd0, b_reg};
            end else begin
                quotient[i] = 1'b0;
            end
        end
    end


    assign result = quotient;
    assign odd = remainder;

endmodule

