module fixed_point_adder #(
    parameter Q = 16,
    parameter N = 32
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);
    reg [N-1:0] res;


    wire sign_a = a[N-1];
    wire sign_b = b[N-1];
    wire [N-1:0] a_abs = sign_a ? (~a + 1) : a;
    wire [N-1:0] b_abs = sign_b ? (~b + 1) : b;


    always @* begin
        if (sign_a == sign_b) begin

            res = {sign_a, a_abs} + {sign_b, b_abs};
        end else begin

            if (a_abs >= b_abs)
                res = {1'b0, a_abs} - {1'b0, b_abs};

            else
                res = {1'b0, b_abs} - {1'b0, a_abs};
        end
    end

    assign c = res;
endmodule

