module sub_64bit (
    input [63:0] A,
    input [63:0] B,
    output [63:0] result,
    output overflow
);

    assign result = A - B;

    wire A_sign = A[63];
    wire B_sign = B[63];
    wire result_sign = result[63];


    wire pos_overflow = (~A_sign) & B_sign & result_sign;


    wire neg_overflow = A_sign & (~B_sign) & (~result_sign);


    assign overflow = pos_overflow | neg_overflow;

endmodule

ref_code:
module sub_64bit(
  input [63:0] A,
  input [63:0] B,
  output reg [63:0] result,
  output reg overflow
);
  always @(*) begin
    result = A - B;

    // Overflow happens when the sign of A and B are different, but the sign of result matches B
    if ((A[63] != B[63]) && (result[63] != A[63])) begin
      overflow = 1;
    end else begin
      overflow = 0;
    end
  end

endmodule
